def _mirror_test():
    import tempfile
    import numpy as np
    from PIL import Image
    bad, meas = [], {}
    tmp = Path(tempfile.mkdtemp(prefix="mirror_", dir=ROOT / "out"))
    try:
        for name, src, dst, chain, pose_l in (("nib", "puppet/examples/nib.puppet.json", "arm_L", ["arm_L", "arm_R"], {"arm_L": 30, "arm_R": -30}),
                                               ("ravi", "cast/generated/ravi.puppet.json", "upperarm_R", ["upperarm_L", "forearm_L", "hand_L", "upperarm_R", "forearm_R", "hand_R"],
                                                {"upperarm_L": 25, "forearm_L": 20, "upperarm_R": -25, "forearm_R": -20})):
            pz = _json(ROOT / src); (tmp / f"{name}.puppet.json").write_text(json.dumps(pz))
            r = puppet_mirror(str((tmp / f"{name}.puppet.json").relative_to(ROOT)), dst, replace=True)
            m = _json(tmp / f"{name}.puppet.json"); a = r["axis"]
            # only the arms, so the drawing should be symmetric about the axis
            keep = {k for k in m["parts"] if k in chain}; anc = set()
            for k in keep:
                q = m["parts"][k].get("parent")
                while q:
                    anc.add(q); q = m["parts"][q].get("parent")
            for k in list(m["parts"]):
                if k not in keep and k not in anc:
                    del m["parts"][k]
                elif k in anc:
                    m["parts"][k]["strokes"] = []
            m["swaps"] = {}; (tmp / f"{name}.arms.puppet.json").write_text(json.dumps(m))
            W, H = m["artboard"]; hip = (m["parts"].get("hip") or {}).get("pivot") or [W / 2, m.get("ground", H)]
            spec = {"size": [int(W) + 16, int(H) + 16], "bg": "#ffffff", "items": [{"puppet": str((tmp / f"{name}.arms.puppet.json").relative_to(ROOT)), "x": hip[0], "y": m.get("ground", H), "s": 1, "pose": {"angles": pose_l}}]}
            (tmp / "spec.json").write_text(json.dumps(spec))
            subprocess.run(["node", str(ROOT / "tools" / "pose_still.mjs"), str(tmp / "spec.json"), str(tmp / f"{name}.png")], check=True, cwd=ROOT, timeout=120)
            im = np.asarray(Image.open(tmp / f"{name}.png").convert("L"))[8:8 + int(H), 8:8 + int(W)] < 200
            ax = int(round(a)); w = min(ax, im.shape[1] - ax)
            left, right = im[:, ax - w:ax], im[:, ax:ax + w][:, ::-1]
            iou = float((left & right).sum() / max(1, (left | right).sum()))
            meas[name] = {"axis": a, "made": r["parts"], "symmetry_iou": round(iou, 3), "lint": r["lint"]}
            if iou < 0.9 or r["lint"]:
                bad.append(f"{name}: {meas[name]}")
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    return bad, meas


def _dressup_test():
    """v0.13 layer sets and gradient and texture fills (WP-18), on tests/poses/dressup.puppet.json"""
    import tempfile
    import numpy as np
    from PIL import Image
    from . import exporters as X, geom as G
    bad, meas = [], {}
    tmp = Path(tempfile.mkdtemp(prefix="dressup_", dir=ROOT / "out"))
    try:
        src = ROOT / "tests" / "poses" / "dressup.puppet.json"; pz = _json(src)
        # 1. a layer set picks its drawings together; a timeline keys it (held); a pick of the pose's own wins
        tl = {"layer_set": [[0, "summer"], [1, "winter"]], "blink": False}
        rel = str(src.relative_to(ROOT))
        cases = [{"pose": {"layer_set": "summer"}}, {"timeline": tl, "t": 0.5}, {"pose": {"layer_set": "winter"}}, {"timeline": tl, "t": 1.5},
                 {"pose": {"hat": "beanie", "scarf": "wool"}}, {"pose": {"layer_set": "winter", "hat": "cap"}}, {"pose": {"hat": "cap", "scarf": "wool"}}, {"pose": {}}]
        tiles = []
        for i, c in enumerate(cases):
            spec = {"size": [420, 700], "bg": "#ffffff", "flush": True, "items": [{"puppet": rel, "x": 210, "y": 680, "s": 0.68, **c}]}
            (tmp / f"c{i}.json").write_text(json.dumps(spec)); _run(["node", "tools/pose_still.mjs", str(tmp / f"c{i}.json"), str(tmp / f"c{i}.png")], timeout=300)
            tiles.append(np.asarray(Image.open(tmp / f"c{i}.png").convert("RGB")).astype(int))
        same = lambda a, b: int((np.abs(tiles[a] - tiles[b]).max(-1) > 8).sum())
        meas["layer_sets"] = {"timeline_summer_vs_set": same(1, 0), "timeline_winter_vs_set": same(3, 2), "set_vs_picks": same(2, 4),
                              "own_pick_wins": same(5, 6), "set_changes_look": same(2, 7)}
        m = meas["layer_sets"]
        if m["timeline_summer_vs_set"] or m["timeline_winter_vs_set"] or m["set_vs_picks"] or m["own_pick_wins"] or m["set_changes_look"] < 2000:
            bad.append(f"layer sets: {m}")
        cs = G.chosen_swaps(pz, {"layer_set": "winter", "hat": "cap"})
        meas["geom_chosen"] = {k: cs.get(k) for k in ("hat", "scarf")}
        if meas["geom_chosen"] != {"hat": "cap", "scarf": "wool"}:
            bad.append(f"geom layer set: {meas['geom_chosen']}")
        # 2. gradients: Lottie's gradient fill matches the SVG loader; textures are SVG-only (the flat fill elsewhere)
        nt = json.loads(json.dumps(pz)); nt.pop("textures")
        for part in list(nt["parts"].values()) + [sh for sw in nt["swaps"].values() for sh in sw["shapes"].values()]:
            for st in (part["strokes"] if isinstance(part, dict) else part):
                st.pop("texture", None)
        flat = json.loads(json.dumps(nt)); flat.pop("gradients")
        (tmp / "nt.puppet.json").write_text(json.dumps(nt)); (tmp / "flat.puppet.json").write_text(json.dumps(flat))
        W, H = 420, 700
        from .fxbake import DEFAULT_FRAME
        frame = {**DEFAULT_FRAME, "x": 210, "y": 680, "s": 0.68, "flip": 1, "layer_set": "winter"}
        lj = X.to_lottie({"fps": 30, "frames": 2, "cast": [{"puppet": str(tmp / "nt.puppet.json"), "frames": [frame, frame]}]}, (W, H), bg=None)
        (tmp / "a.json").write_text(json.dumps(lj))
        _run(["node", "tools/lottie_frames.mjs", str(tmp / "a.json"), str(tmp / "lw"), "0"], timeout=300)
        lw = Image.open(tmp / "lw" / "lw0000.png").convert("RGBA"); bgw = Image.new("RGBA", lw.size, "#ffffff"); bgw.alpha_composite(lw)
        lot = np.asarray(bgw.convert("RGB")).astype(float)
        svg = {}
        for k, f in (("gradient", "nt"), ("flat", "flat")):
            spec = {"size": [W, H], "bg": "#ffffff", "flush": True, "items": [{"puppet": str((tmp / f"{f}.puppet.json").relative_to(ROOT)), "x": 210, "y": 680, "s": 0.68, "pose": {"layer_set": "winter", "blink": 0}}]}
            (tmp / f"{k}.json").write_text(json.dumps(spec)); _run(["node", "tools/pose_still.mjs", str(tmp / f"{k}.json"), str(tmp / f"{k}.png")], timeout=300)
            svg[k] = np.asarray(Image.open(tmp / f"{k}.png").convert("RGB")).astype(float)
        baked = {"fps": 30, "frames": 2, "cast": [{"puppet": str(tmp / "nt.puppet.json"), "frames": [frame, frame]}]}
        (tmp / "a.sif").write_text(X.to_synfig(baked, (W, H), transparent=False))
        subprocess.run(["synfig", str(tmp / "a.sif"), "-t", "png", "-o", str(tmp / "sy.png"), "--time", "0s", "-q"], capture_output=True, timeout=600, check=True)
        sy = Image.open(tmp / "sy.png").convert("RGBA"); sbg = Image.new("RGBA", sy.size, "#ffffff"); sbg.alpha_composite(sy)
        syn = np.asarray(sbg.convert("RGB")).astype(float)
        psnr = lambda a, b: round(float(10 * np.log10(255 ** 2 / max(1e-9, ((a - b) ** 2).mean()))), 1)
        meas["lottie_gradient"] = {"psnr_vs_svg_gradient": psnr(lot, svg["gradient"]), "psnr_vs_svg_flat": psnr(lot, svg["flat"]),
                                   "svg_gradient_vs_flat_px": int((np.abs(svg["gradient"] - svg["flat"]).max(-1) > 24).sum())}
        meas["synfig_gradient"] = {"psnr_vs_svg_gradient": psnr(syn, svg["gradient"]), "psnr_vs_svg_flat": psnr(syn, svg["flat"])}
        for k in ("lottie_gradient", "synfig_gradient"):
            g = meas[k]
            if g["psnr_vs_svg_gradient"] < 30 or g["psnr_vs_svg_gradient"] < g["psnr_vs_svg_flat"] + 6 or meas["lottie_gradient"]["svg_gradient_vs_flat_px"] < 3000:
                bad.append(f"{k}: {g}")
        # the texture is drawn (multiplied over the fill): the torso's hatch darkens some of its pixels in a repeating pattern
        tex = np.asarray(Image.open(tmp / "c2.png").convert("RGB")).astype(float)
        diff = np.abs(tex - svg["gradient"]).max(-1) > 10
        meas["texture_px"] = int(diff.sum())
        if meas["texture_px"] < 2000:
            bad.append(f"texture: {meas['texture_px']} px changed")
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    return bad, meas


def _timeline2_test():
    """WP-19 on the Studio timeline page, on a scratch copy of pip-park: cuts, camera keys and lines dragged"""
    import socket, time
    bad, meas = [], {}
    name = "zz-tlcheck"; d = FILMS / name
    shutil.rmtree(d, ignore_errors=True); d.mkdir()
    for f in ("brief.md", "facts.json", "score.json", "script.json", "shots.json", "timing.json", "titles.json"):
        if (FILMS / "pip-park" / f).exists():
            shutil.copy(FILMS / "pip-park" / f, d / f)
    port = 8797; srv = None
    try:
        voice_build(name); film_preview(name)
        srv = subprocess.Popen([sys.executable, "-m", "dbe", "serve", str(port)], cwd=ROOT, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        for _ in range(50):
            with socket.socket() as s_:
                if s_.connect_ex(("127.0.0.1", port)) == 0:
                    break
            time.sleep(0.2)
        r = subprocess.run(["node", "tools/timeline_edit_check.mjs", str(port), name], cwd=ROOT, capture_output=True, text=True, timeout=1500)
        out = json.loads(r.stdout.strip().splitlines()[-1]) if r.stdout.strip() else {"error": r.stderr[-400:]}
    finally:
        if srv:
            srv.terminate(); srv.wait(timeout=20)
        shutil.rmtree(d, ignore_errors=True)
    meas.update(out)
    if out.get("error") or out.get("errs"):
        return [f"page: {out}"], meas
    fr = 1 / 30 + 1e-6
    c = out["cut"]
    if abs((c["s1_end"][1] - c["s1_end"][0]) - c["want_dt"]) > fr or c["s2_start"][1] != c["s1_end"][1]:
        bad.append(f"cut: {c}")
    ca, cm, cs = out["camkey_added"], out["camkey_moved"], out["camkey_set"]
    if len(ca) != 1 or not isinstance(ca[0][0], str) or ca[0][1] != [540, 960, 1] or len(cm["raw"]) != 1 or cm["raw"][0][0] == ca[0][0] \
            or cs[0][1] != [540, 960, 1.2] or out["camkey_deleted"] is not None:
        bad.append(f"camera keys: {ca} {cm} {cs} {out['camkey_deleted']}")
    cp, cd_ = out.get("curve_preset") or [], out.get("curve_dragged") or []
    if len(cp) < 3 or cp[2] != [0.42, 0, 1, 1] or len(cd_) != 2 or len(cd_[0]) < 3 or not isinstance(cd_[0][2], list) or cd_[0][2][:2] != [0.42, 0] \
            or cd_[0][2][3] <= 1 or cd_[1][1][2] != 1.4:
        bad.append(f"curve editor: preset {cp}, dragged {cd_}")
    else:   # the eased move plays the same in the player's sampler (JS) and the Blender sets' (Python)
        from . import keys as BG
        keys = [[0.0, cd_[0][1], cd_[0][2]], [1.0, cd_[1][1]]]
        ts = [i / 20 for i in range(21)]
        js = json.loads(_run(["node", "-e", "global.window=globalThis;require('./puppet/loader/puppet.js');require('./puppet/loader/acting.js');"
                              f"const k={json.dumps(keys)};console.log(JSON.stringify({json.dumps(ts)}.map(t=>Acting.sampleKeys(k,t)[2])))"])[-1])
        py = [BG.sample_keys(keys, t)[2] for t in ts]
        meas["curve_js_vs_python_max_diff"] = max(abs(a - b) for a, b in zip(js, py)); meas["curve_zoom_peak"] = round(max(js), 3)
        if meas["curve_js_vs_python_max_diff"] > 1e-6 or max(js) <= 1.4:
            bad.append(f"curve sampling: js {js} python {py}")
    L = out["line"]; b0, a0, u0 = dict(L["before"]), dict(L["after"]), dict(L["undone"]); m = L["moved"]
    if abs((a0[m] - b0[m]) - L["want_dt"]) > 2 * fr or any(abs(a0[k] - b0[k]) > 0.01 for k in b0 if k != m) or any(abs(u0[k] - b0[k]) > 0.01 for k in b0):
        bad.append(f"line: {L}")
    return bad, meas


def _reviewtiming_test():
    """WP-19 notes about line timing, on a scratch copy of pip-park: 'give the last line a beat before it' and 'the
    pause before the first line is too long' fixed by review.fix and verified on the voice track"""
    bad, meas = [], {}
    name = "zz-rvtiming"; d = FILMS / name
    shutil.rmtree(d, ignore_errors=True); d.mkdir()
    for f in ("brief.md", "facts.json", "score.json", "script.json", "shots.json", "timing.json", "titles.json"):
        if (FILMS / "pip-park" / f).exists():
            shutil.copy(FILMS / "pip-park" / f, d / f)
    try:
        voice_build(name); film_render(name)
        tm = _json(d / "timing.json"); L = {l["id"]: l for l in tm["lines"]}; ids = [l["id"] for l in tm["lines"]]
        fps = _shots(name).get("fps", 30)
        review_add(name, int(L[ids[-1]]["start"] * fps), "give the last line a beat before it")
        review_add(name, int(0.5 * fps), "the pause before the first line is too long")
        review_add(name, int(L[ids[1]]["start"] * fps), "this line feels somehow wrong")   # not a timing note
        res = review_fix(name)["notes"]
        meas["notes"] = [{k: n.get(k) for k in ("text", "status", "target", "measured", "check", "reason")} for n in res]
        tm2 = _json(d / "timing.json"); L2 = {l["id"]: l for l in tm2["lines"]}
        meas["starts"] = {k: [round(L[k]["start"], 3), round(L2[k]["start"], 3)] for k in ids}
        st = [n["status"] for n in res]
        if st[:2] != ["verified", "verified"] or st[2] == "verified":
            bad.append(f"statuses {st}")
        g1 = res[0].get("measured") or {}; g2 = res[1].get("measured") or {}
        if not (0.3 <= (g1.get("moved_s") or 0) <= 0.7) or not (-0.6 <= (g2.get("moved_s") or 0) <= -0.24):
            bad.append(f"amounts: last line {g1}, first line {g2}")
    finally:
        shutil.rmtree(d, ignore_errors=True)
    return bad, meas


def _reviewphone_test():
    """WP-19 review on a phone: the Studio served beyond this machine needs its key (checked over HTTP from another
    loopback address, so nothing leaves the machine), and the review room works at phone size (an emulated iPhone 13)"""
    import http.client, socket, time
    bad, meas = [], {}
    port, key, film = 8794, "phonecheck-" + os.urandom(4).hex(), "review-demo"
    rv = FILMS / film / "review.json"; keep = rv.read_text() if rv.exists() else None
    srv = subprocess.Popen([sys.executable, "-m", "dbe", "serve", str(port), "127.0.0.2"], cwd=ROOT, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                           env={**os.environ, "DBE_KEY": key})
    try:
        for _ in range(50):
            with socket.socket() as s_:
                if s_.connect_ex(("127.0.0.2", port)) == 0:
                    break
            time.sleep(0.2)

        def get(path, method="GET", cookie=None):   # from 127.0.0.3: another machine, as far as the server can tell
            c = http.client.HTTPConnection("127.0.0.2", port, timeout=30, source_address=("127.0.0.3", 0))
            c.request(method, path, body=b"{}" if method == "POST" else None, headers={"Cookie": cookie} if cookie else {})
            r = c.getresponse(); r.read(); return r.status, r.getheader("Set-Cookie") or ""
        gate = {"page_no_key": get(f"/review?film={film}")[0], "api_no_key": get("/api/engine.info", "POST")[0], "wrong_key": get(f"/review?film={film}&key=nope")[0]}
        st, ck = get(f"/review?film={film}&key={key}"); gate["with_key"] = st; gate["sets_cookie"] = ck.startswith(f"dbe_key={key}") and "HttpOnly" in ck
        gate["api_with_cookie"] = get("/api/engine.info", "POST", cookie=f"dbe_key={key}")[0]
        meas["gate"] = gate
        if (gate["page_no_key"], gate["api_no_key"], gate["wrong_key"], gate["with_key"], gate["api_with_cookie"]) != (403, 403, 403, 200, 200) or not gate["sets_cookie"]:
            bad.append(f"key gate: {gate}")
        r = subprocess.run(["node", "tools/review_phone_check.mjs", f"http://127.0.0.2:{port}", key, film], cwd=ROOT, capture_output=True, text=True, timeout=600)
        out = json.loads(r.stdout.strip().splitlines()[-1]) if r.stdout.strip() else {"error": r.stderr[-400:]}
    finally:
        srv.terminate(); srv.wait(timeout=20)
        if keep is not None:
            rv.write_text(keep)
    meas["phone"] = out
    if out.get("error") or out.get("errs"):
        return bad + [f"phone page: {out}"], meas
    L = out["layout"]
    if L["h_scroll"] or L["picture_h_share"] > 0.6 or L["composer"]["bottom"] > L["viewport"][1] or L["bar_h"] < 36 or L["text_font_px"] < 16:
        bad.append(f"phone layout: {L}")
    if abs(out["tap"]["frame"] - out["tap"]["want"]) > 2 or abs(out["drag"]["frame"] - out["drag"]["want"]) > 2 or out["step"]["frame"] != out["drag"]["frame"] + 1 \
            or out["pinned"]["frame"] != out["step"]["frame"]:
        bad.append(f"phone scrub and pin: {out}")
    return bad, meas


def _live_test():
    """WP-12 live page: (1) LIVE.solve on synthetic takes (forward kinematics through ravi, 1.5 px noise) against the
    clips that made them; (2) the page on Chromium's fake webcam playing a COCO photo, MediaPipe in WebAssembly,
    against actout.detect + retarget on the same frames as a video file."""
    import shutil, subprocess, tempfile, threading
    import numpy as np
    from http.server import ThreadingHTTPServer
    from . import actout as AO
    from .server import Handler
    if not (ROOT / "tools/live/node_modules/@mediapipe/tasks-vision").exists():
        return [], {"skipped": "bash tools/setup.sh live (npm install in tools/live) first"}
    srv = ThreadingHTTPServer(("127.0.0.1", 0), Handler); threading.Thread(target=srv.serve_forever, daemon=True).start()
    base = f"http://127.0.0.1:{srv.server_address[1]}/live?puppet=cast/generated/ravi.puppet.json"
    tmp = Path(tempfile.mkdtemp(prefix="livetest_")); bad, meas = [], {}
    pz = _json(ROOT / "cast" / "generated" / "ravi.puppet.json"); lib = _json(ROOT / "puppet" / "clips" / "humanoid.json")["clips"]

    def page(*a, timeout=600):
        r = subprocess.run(["node", str(ROOT / "tools/live/check.mjs"), *a], capture_output=True, text=True, timeout=timeout, cwd=ROOT)
        try:
            return json.loads(r.stdout.strip().splitlines()[-1])
        except Exception:
            return {"error": (r.stderr or r.stdout)[-600:]}
    try:
        for name in ("wave_R", "celebrate", "shrug"):
            c = lib[name]; kp = AO.synthetic_take(pz, c, seconds=max(c["duration"], 1.0)); (tmp / "take.json").write_text(json.dumps(kp))
            o = page(base, "solve", str(tmp / "take.json"))
            if o.get("error"):
                bad.append(f"{name}: {o['error']}"); continue
            ts = np.arange(len(kp["frames"])) / 30; ang = AO._sample_tracks(c["tracks"], np.minimum(ts, c["duration"]))
            err = {k: [abs((a[k] - ang[k][i] + 180) % 360 - 180) for i, a in enumerate(o["angles"]) if k in a] for k in ang}
            miss = [k for k, v in err.items() if len(v) < 0.9 * len(ts)]
            m = float(np.mean([np.mean(v) for v in err.values() if v])); mx = float(max(max(v) for v in err.values() if v))
            meas[name] = {"mean_deg": round(m, 2), "max_deg": round(mx, 2)}
            if m > 2.0 or mx > 8.0 or miss:
                bad.append(f"{name}: per-frame angles {m:.2f} deg mean, {mx:.2f} max" + (f", parts missing {miss}" if miss else ""))
        img = AO.MODELS.parent / "coco-val2017" / "000000368212.jpg"   # fetched by pose.benchmark; any photo of a whole person would do
        if not img.exists():
            meas["webcam"] = {"skipped": f"{img.name} not cached (python -m dbe pose.benchmark fetches it)"}
        else:
            subprocess.run(["ffmpeg", "-v", "error", "-y", "-loop", "1", "-i", str(img), "-vf", "scale=720:-2,pad=720:1280:0:(oh-ih)/2:color=gray,format=yuv420p",
                            "-frames:v", "45", "-r", "30", str(tmp / "cam.y4m")], check=True)
            subprocess.run(["ffmpeg", "-v", "error", "-y", "-i", str(tmp / "cam.y4m"), "-c:v", "libx264", "-qp", "0", "-pix_fmt", "yuv420p", str(tmp / "cam.mp4")], check=True)
            o = page(base + "&mirror=0&smooth=0", "camera", str(tmp / "cam.y4m"), "20")
            if o.get("error"):
                bad.append(f"webcam: {o['error']}")
            else:
                lv = o["live"]; kp = AO.detect(str(tmp / "cam.mp4"), face=False); (tmp / "py.json").write_text(json.dumps(kp))
                ref = page(base, "solve", str(tmp / "py.json"))   # Python MediaPipe's landmarks through the same per-frame solve
                med = lambda rows, k: float(np.degrees(np.angle(np.mean([np.exp(1j * np.radians(r[k])) for r in rows if k in r]))))
                parts_ = [k for k in ref.get("angles", [{}])[-1] if any(k in r for r in lv["history"])]
                d = {k: round(abs((med(lv["history"], k) - med(ref["angles"], k) + 180) % 360 - 180), 1) for k in parts_}
                W, H = kp["size"]; lp = np.array(kp["frames"][-1]["pose"])[11:29, :2] / [W, H]; lj = np.array(lv["lm"])[11:29, :2] / lv["size"]
                meas["webcam"] = {"frames": lv["frames"], "with_person": lv["detected"], "pose_ms": round(lv["ms"], 1), "load_s": o["load_s"],
                                  "parts": len(d), "median_deg_off_python_mediapipe": d, "landmarks_off_frame_share": round(float(np.abs(lp - lj).mean()), 4)}
                if len(d) < 10 or np.mean(list(d.values())) > 4 or max(d.values()) > 12 or lv["svg"] < 1000:
                    bad.append(f"webcam: {len(d)} parts, median angles off Python MediaPipe's by {d}")
    finally:
        srv.shutdown(); shutil.rmtree(tmp, ignore_errors=True)
    return bad, meas


# ---------------- act it out (plan 3.5) ----------------
@command("actout.rest", puppet=("string", "character file, cast/.../x.puppet.json"))
def actout_rest(puppet):
    """The rest direction (degrees, artboard space) of each bone a take can drive on this character, as actout.clip
    measures them: the live page (/live, WP-12) uses these so its angles are the same as the recorded clip's."""
    from . import actout as AO
    pz = _json(ROOT / puppet)
    return {"puppet": puppet, "rest": {k: round(v, 4) for k, v in AO.rest_directions(pz).items()},
            "parents": {k: v.get("parent") for k, v in pz["parts"].items()},
            "limits": {k: v["limits"] for k, v in pz["parts"].items() if v.get("limits")}}


@command("actout.clip", video=("string", "the take: a phone or webcam video (any format ffmpeg reads), path from the project root or absolute"),
         puppet=("string", "character file, cast/.../x.puppet.json"), name=("string", "name of the new clip on that character"),
         start=("number", "seconds into the video where the take starts", 0), duration=("number", "seconds to use (0 = to the end, at most 20)", 0),
         mirror=("boolean", "flip the take first (selfie and webcam previews are mirrored)", False),
         face=("string", "upper (eyes, brows, gaze; the mouth stays with lip-sync, the default) | all (the take's mouth too: for silent reactions, since it overrides lip-sync while the clip plays) | none", "upper"),
         root=("string", "move (the take's travel, planted feet kept on the ground) | in_place", "move"),
         arms=("string", "angles (joint angles copied: natural silhouettes, the default) | reach (hands placed where the take's hands are, scaled to this body: keeps claps and hands-on-body contacts)", "angles"),
         tolerance=("number", "largest angle error the reduced keys may have, in degrees", 1.5),
         save=("boolean", "write the clip into the character file (otherwise a copy under out/actout/)", True),
         people=("integer", "people in the take: each becomes a clip (<name>, <name>_2, ...; left to right as first seen)", 1),
         puppets=("array", "characters for the second and later people (default: the same character)", None),
         stabilize=("string", "auto (take out the camera's motion when the background moves more than 20 px) | on | off", "auto"))
def actout_clip(video, puppet, name, start=0, duration=0, mirror=False, face="upper", root="move", arms="angles", tolerance=1.5, save=True, people=1, puppets=None, stabilize="auto"):
    """Act it out (plan 3.5): a short take of a person becomes an action clip on a character. MediaPipe Pose and
    Face Landmarker read body points and face blendshapes per frame; they are retargeted onto the character's own
    rest pose (joint angles, the root's travel with planted feet held on the ground, foot contacts, mouth, eye and
    brow drawings, gaze), and keys are reduced against the eased curve the player will actually play. Parts the take
    cannot see (legs in a waist-up webcam take) are left out, so idle or other clips fill them. The clip is saved in
    the character (puppet format v0.7 clips), so shots, the bake and every exporter play it by name. Also writes
    out/actout/<name>_sheet.png: frames of the take above the character at the same moments."""
    import time
    import numpy as np
    from . import actout as AO
    t0 = time.time()
    if not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{0,40}", name):
        raise ValueError("clip names are letters, digits and _ (starting with a letter)")
    if face not in ("all", "upper", "none") or root not in ("move", "in_place") or arms not in ("reach", "angles"):
        raise ValueError("face is all, upper or none; root is move or in_place; arms is reach or angles")
    vid = Path(video) if Path(video).is_absolute() else ROOT / video
    if not vid.is_file():
        raise FileNotFoundError(f"no video at {video}")
    pfile = (ROOT / puppet).resolve()
    if not pfile.is_file():
        raise FileNotFoundError(f"no puppet at {puppet}")
    pz = _json(pfile)
    dur = min(float(duration) or 20.0, 20.0)
    cache = ROOT / "out" / "actout"; cache.mkdir(parents=True, exist_ok=True)
    if stabilize not in ("auto", "on", "off") or not 1 <= int(people) <= 4:
        raise ValueError("stabilize is auto, on or off; people is 1 to 4")
    key = AO.cache_key(vid, start=float(start), duration=dur, mirror=bool(mirror), face=face != "none" and int(people) == 1, fps=30, **({"people": int(people)} if int(people) > 1 else {}))
    kpf = cache / f"{key}.keypoints.json"
    cached = kpf.exists()
    kp = _json(kpf) if cached else AO.detect(vid, fps=30, start=float(start), duration=dur, mirror=bool(mirror), face=face != "none" and int(people) == 1, people=int(people))
    if not cached:
        kpf.write_text(json.dumps(kp))
    cam = None
    if stabilize != "off":   # WP-12: the camera's motion, from the background, taken out of every point
        arr, _ = AO.frames(vid, 30, float(start), dur, bool(mirror))
        path, prep = AO.camera_path(arr, kp); moved = float(max(np.ptp(path[:, 0]), np.ptp(path[:, 1])))
        cam = {"moved_px": round(moved, 1), "trusted": prep["trusted"], "taken_out": stabilize == "on" or (moved > 20 and prep["trusted"] >= 0.8)}
        if prep["trusted"] < 0.8:
            cam["note"] = "too little background to see the camera's motion (the performer fills the picture): taken as still"
        if cam["taken_out"]:
            kp = AO.stabilize(kp, path)
    takes = AO.split_people(kp, int(people)) if int(people) > 1 else [kp]
    outs = []
    for j, kpj in enumerate(takes):
        pf = pfile if j == 0 or not puppets or len(puppets) < j else (ROOT / puppets[j - 1]).resolve()
        pz = _json(pf); cname = name if j == 0 else f"{name}_{j + 1}"
        clip, rep = AO.retarget(kpj, pz, tol=float(tolerance), face=face if int(people) == 1 else "none", root=root, arms=arms)
        clip["source"] = {"take": vid.name, "start": float(start), "seconds": rep["seconds"], "mirror": bool(mirror), **({"person": j + 1} if int(people) > 1 else {}),
                          **({"camera_taken_out_px": cam["moved_px"]} if cam and cam["taken_out"] else {}),
                          "by": "actout.clip (MediaPipe Pose + Face Landmarker, retargeted to this character)"}
        pz.setdefault("clips", {})[cname] = clip
        ver = tuple(int(x) for x in str(pz.get("version", "0")).split(".") if x.isdigit())
        want = (0, 10) if clip.get("controls") else (0, 7)   # character clips arrived in v0.7, clip control tracks in v0.10
        if ver < want:
            pz["version"] = ".".join(map(str, want))
        if save:
            op = puppet_save(str(pf.relative_to(ROOT)), pz)["path"]
        else:
            op = str((cache / f"{cname}.puppet.json").relative_to(ROOT)); (ROOT / op).write_text(json.dumps(pz))
        outs.append((cname, op, clip, rep, kpj))
    name, out_path, clip, rep, kp = outs[0]
    sheet = _actout_sheet(vid, float(start), bool(mirror), out_path, name, clip["duration"], cache / f"{name}_sheet.png", kp)
    return {"clip": name, "puppet": out_path, "saved": bool(save), "report": rep, "keypoints": str(kpf.relative_to(ROOT)),
            "reused_keypoints": cached, "timing": {**(kp.get("timing") or {}), "total_s": round(time.time() - t0, 1)},
            "sheet": str(sheet.relative_to(ROOT)) if sheet else None, **({"camera": cam} if cam else {}),
            **({"people": [{"clip": c, "puppet": o, "report": {k: r[k] for k in ("tracks", "root", "person_found")}} for c, o, _, r, _ in outs]} if len(outs) > 1 else {})}


def _actout_sheet(vid, start, mirror, puppet_rel, clip, dur, out, kp=None, n=6):
    """take frames (top, cropped around the performer) over the character playing the new clip (bottom) at the same
    moments"""
    import tempfile
    from PIL import Image
    tdir = Path(tempfile.mkdtemp(prefix="actout_"))
    times = [round(dur * (i + 0.5) / n, 3) for i in range(n)]
    col, h = 240, 400
    spec = {"size": [col * n, h], "bg": "#f4f3ee", "items": [
        {"puppet": puppet_rel, "x": col * i + col // 2, "y": h - 12, "s": 0.36, "t": t,
         "timeline": {"clips": [{"clip": clip, "start": 0, "fadeIn": 0, "fadeOut": 0}], "blink": False, "springs": False}} for i, t in enumerate(times)]}
    (tdir / "spec.json").write_text(json.dumps(spec))
    try:
        _run(["node", "tools/pose_still.mjs", str(tdir / "spec.json"), str(tdir / "pz.png")], timeout=300)
    except Exception:
        return None
    sheet = Image.new("RGB", (col * n, h * 2), "#f4f3ee"); sheet.paste(Image.open(tdir / "pz.png").convert("RGB"), (0, h))
    for i, t in enumerate(times):
        f = tdir / f"v{i}.png"
        subprocess.run(["ffmpeg", "-v", "error", "-y", "-ss", f"{start + t:.3f}", "-i", str(vid), "-frames:v", "1"] + (["-vf", "hflip"] if mirror else []) + [str(f)], check=False)
        if not f.exists():
            continue
        im = Image.open(f).convert("RGB")
        fr = (kp or {}).get("frames") or []
        pose = fr[min(len(fr) - 1, int(round(t * kp["fps"])))].get("pose") if fr else None
        if pose:   # crop around the performer (keypoints are in the detection frame's pixels)
            k = im.width / kp["size"][0]; xs = [q[0] * k for q in pose]; ys = [q[1] * k for q in pose]
            cx, cy = (min(xs) + max(xs)) / 2, (min(ys) + max(ys)) / 2
            bh = max((max(ys) - min(ys)) * 1.15, (max(xs) - min(xs)) * 1.2 * h / col, 40)
            bw = bh * col / h
            box = Image.new("RGB", (int(bw), int(bh)), "#f4f3ee"); box.paste(im, (-int(cx - bw / 2), -int(cy - bh / 2))); im = box
        im.thumbnail((col, h))
        sheet.paste(im, (col * i + (col - im.width) // 2, (h - im.height) // 2))
    sheet.save(out); shutil.rmtree(tdir, ignore_errors=True)
    return out


# ---------------- phone-first creator flow (plan 3.6) ----------------
DOODLES = ROOT / "out" / "doodle"


def _doodle_dir(id):
    if not re.fullmatch(r"[0-9a-f]{12}", id or ""):
        raise ValueError("not a doodle id")
    d = DOODLES / id
    if not d.is_dir():
        raise FileNotFoundError(f"no doodle {id}")
    return d


def _doodle_build(d, spec):
    spec = {**spec, "photo": str(d / "photo.png")}
    spec.pop("found", None)
    (d / "spec.json").write_text(json.dumps(spec))
    out = json.loads(_run([PY, "dbe/ink.py", str(d / "spec.json"), str(d / "doodle.puppet.json")])[-1])
    return out


@command("doodle.snap", photo=("string", "a phone photo of a pen doodle (path from the project root or absolute; /upload puts one in out/actout/takes/)"),
         name=("string", "the character's name", "Doodle"))
def doodle_snap(photo, name="Doodle"):
    """Phone-first creator flow (plan 3.6), step 1: a photo of a doodle becomes a talking doodle puppet with suggested
    cuts and pivots. The photo is turned upright, cropped to the ink and scaled; closed loops give the head and body
    (or one blob), marks inside the head the eyes (blinking by squash) and mouth (talking shapes drawn to match in the
    same line), strokes leaving the body's sides the arms and a tail, marks above the body ride with the head. Returns
    the doodle id, the ink spec (polygons and pivots to confirm or move, then doodle.cut) and what was found, with
    reasons and notes for anything it could not find."""
    import hashlib
    from . import autorig as AR
    src = Path(photo) if Path(photo).is_absolute() else ROOT / photo
    if not src.is_file():
        raise FileNotFoundError(f"no photo at {photo}")
    id = hashlib.sha256(src.read_bytes()).hexdigest()[:12]
    d = DOODLES / id; d.mkdir(parents=True, exist_ok=True)
    info = AR.prepare(src, d / "photo.png")
    spec = AR.suggest(str(d / "photo.png"), name=name)
    built = _doodle_build(d, spec)
    rel = lambda p: str(p.relative_to(ROOT))
    return {"id": id, "photo": rel(d / "photo.png"), "size": info["size"], "puppet": rel(d / "doodle.puppet.json"),
            "found": spec["found"], "spec": {k: v for k, v in spec.items() if k != "found"}, "built": built}


@command("doodle.page", photo=("string", "a phone photo of a page with one or more pen doodles"),
         names=("array", "a name per doodle, left to right then top to bottom (missing names: Doodle 1, Doodle 2, ...)", None))
def doodle_page(photo, names=None):
    """A page with several doodles (WP-18): each drawing on the page becomes its own doodle puppet. The page is split
    where the ink falls into separate groups (gaps closed, loops filled, so eyes stay with their head; specks left
    out), each group is cropped with the others painted out, and each crop goes through doodle.snap. Returns the
    doodles in reading order, each as doodle.snap returns it, with its box on the page."""
    import hashlib
    from . import autorig as AR
    src = Path(photo) if Path(photo).is_absolute() else ROOT / photo
    if not src.is_file():
        raise FileNotFoundError(f"no photo at {photo}")
    pid = hashlib.sha256(src.read_bytes()).hexdigest()[:12]
    work = DOODLES / f"page-{pid}"
    crops = AR.split_page(src, work)
    names = list(names or [])
    out = []
    for i, c in enumerate(crops):
        nm = names[i] if i < len(names) and names[i] else (f"Doodle {i + 1}" if len(crops) > 1 else "Doodle")
        out.append({**doodle_snap(c["photo"], nm), "name": nm, "box": c["box"]})
    return {"page": pid, "count": len(out), "doodles": out, "left_out": getattr(AR.split_page, "left_out", [])}


@command("doodle.cut", id=("string", "doodle id from doodle.snap"), spec=("object", "the ink spec with confirmed or moved cuts and pivots"))
def doodle_cut(id, spec):
    """Step 2: rebuild a doodle puppet from confirmed cuts and pivots (parts' polygons and pivots, swaps' boxes;
    remove a part to leave it on the body)."""
    d = _doodle_dir(id)
    for pid, ps in (spec.get("parts") or {}).items():
        if pid not in ("head", "arm_L", "arm_R", "tail", "body"):
            raise ValueError(f"doodle parts are head, arm_L, arm_R, tail (and body as the rest), not {pid}")
        if "pivot" not in ps or ("poly" in ps and len(ps["poly"]) < 3):
            raise ValueError(f"{pid} needs a pivot and a polygon of 3 or more points")
    built = _doodle_build(d, spec)
    used = sorted({ps["assist"] for ps in (spec.get("parts") or {}).values() if ps.get("assist")})
    if used:   # cuts suggested by a model (doodle.click): the puppet's provenance says so
        from . import assists as A
        pz = _json(d / "doodle.puppet.json")
        for mdl in used:
            A.record(pz, mdl, "cut polygons: " + ", ".join(k for k, ps in spec["parts"].items() if ps.get("assist") == mdl))
        (d / "doodle.puppet.json").write_text(json.dumps(pz))
    return {"id": id, "puppet": str((d / "doodle.puppet.json").relative_to(ROOT)), "built": built, **({"assists": used} if used else {})}


@command("doodle.click", id=("string", "doodle id from doodle.snap"), part=("string", "head | arm_L | arm_R | tail"),
         points=("array", "taps on the photo: [[x, y], ...] inside the piece, [x, y, 0] for a tap outside it (photo pixels)"),
         spec=("object", "the ink spec being checked (default: the doodle's last one)", None))
def doodle_click(id, part, points, spec=None):
    """Click-to-mask cuts (WP-18): taps on the photo give that piece's cut from SAM 2.1 tiny (an in-house assist,
    recorded in the puppet's provenance when the cut is used). The mask, with the ink it touches, is grown by the line
    width and outlined; a new piece gets a pivot where it comes nearest the rest of the drawing (for the head, the
    bottom of the mask). Returns the spec with that piece replaced (pass it to doodle.cut), the polygon and how sure
    the model is. The first tap on a photo takes about 4 s (the picture is encoded once and cached)."""
    import time
    import numpy as np
    from scipy import ndimage
    from . import assists as A, autorig as AR
    if part not in ("head", "arm_L", "arm_R", "tail"):
        raise ValueError("part is head, arm_L, arm_R or tail")
    if not points or not all(isinstance(q, (list, tuple)) and len(q) in (2, 3) for q in points):
        raise ValueError("points: [[x, y], ...] or [x, y, 0] for outside")
    d = _doodle_dir(id); photo = d / "photo.png"
    spec = json.loads(json.dumps(spec)) if spec else {k: v for k, v in _json(d / "spec.json").items() if k != "photo"}
    t0 = time.time()
    m, iou = A.sam_mask(photo, points, cache=d / "sam.npz")
    ink = AR._ink().extract(str(photo)) > 0.35
    edt = ndimage.distance_transform_edt(ink); w = float(max(2.0, 2 * np.percentile(edt[ink], 90))) if ink.any() else 3.0
    m = m | (ink & ndimage.binary_dilation(m, iterations=int(w) + 1))   # the line around a filled region belongs to it
    lab, n = ndimage.label(m, np.ones((3, 3)))
    if n > 1:   # keep the piece that was tapped (or the largest)
        hit = {int(lab[int(q[1]), int(q[0])]) for q in points if (len(q) < 3 or q[2]) and 0 <= int(q[1]) < m.shape[0] and 0 <= int(q[0]) < m.shape[1]} - {0}
        sizes = ndimage.sum(m, lab, range(1, n + 1))
        keep = hit or {int(np.argmax(sizes)) + 1}
        m = np.isin(lab, list(keep))
    if m.sum() < 20:
        raise ValueError("nothing found there: tap on the piece itself")
    m = ndimage.binary_fill_holes(m)
    core = None
    if part != "head":   # a limb: drop the body and head loops it touches (the drawing filled, thin strokes opened away)
        g = int(max(2, round(w * 1.5))); pad = g + 2   # the loops' insides (as autorig finds them), out to their lines
        mc = ndimage.binary_closing(np.pad(ink, pad), iterations=g)[pad:-pad, pad:-pad] | ink
        lab, n = ndimage.label(ndimage.binary_fill_holes(mc) & ~mc)
        ys_, xs_ = np.nonzero(ink); area = (np.ptp(xs_) + 1) * (np.ptp(ys_) + 1)
        big = [i + 1 for i, a_ in enumerate(ndimage.sum(np.ones_like(lab), lab, range(1, n + 1))) if a_ > 0.015 * area]
        core = ndimage.binary_dilation(np.isin(lab, big), iterations=int(w) + 1) if big else np.zeros_like(ink)
        limb = m & ~ndimage.binary_dilation(core, iterations=int(w * 1.5) + 1)
        if limb.sum() >= 20:
            lab, n = ndimage.label(limb, np.ones((3, 3))); m = lab == (int(np.argmax(ndimage.sum(limb, lab, range(1, n + 1)))) + 1) if n > 1 else limb
    poly = AR._poly(ndimage.binary_dilation(m, iterations=int(w)), w)
    old = (spec.get("parts") or {}).get(part) or {}
    ys, xs = np.nonzero(m)
    if old.get("pivot"):
        pivot = old["pivot"]
    elif part == "head":
        pivot = [int(round(xs.mean())), int(ys.max())]
    else:   # where the limb comes nearest the body
        if core is not None and core.any():
            # along the stroke's own direction from its end nearest the body, to where it meets the body's line
            dist = ndimage.distance_transform_edt(~core)
            k = int(np.argmin(dist[ys, xs])); c0 = np.array([xs.mean(), ys.mean()])
            v = np.linalg.svd(np.stack([xs, ys], 1) - c0, full_matrices=False)[2][0]
            if np.dot(v, [xs[k], ys[k]] - c0) < 0:
                v = -v
            q = np.array([xs[k], ys[k]], float); body_line = ink & ndimage.binary_dilation(core, iterations=int(w) + 1)
            for _ in range(int(4 * w) + 10):
                xi, yi = int(round(q[0])), int(round(q[1]))
                if not (0 <= yi < ink.shape[0] and 0 <= xi < ink.shape[1]) or body_line[yi, xi]:
                    break
                q += v
            pivot = [int(round(q[0])), int(round(q[1]))]
        else:
            k = int(np.argmax(ys)); pivot = [int(xs[k]), int(ys[k])]
    parent = old.get("parent") or ("body" if part != "head" else "body")
    spec.setdefault("parts", {})[part] = {**old, "poly": poly, "pivot": pivot, "parent": parent, "z": old.get("z", {"head": 20, "tail": 8}.get(part, 12)), "assist": "sam21_tiny"}
    return {"id": id, "part": part, "poly": poly, "pivot": pivot, "iou": round(iou, 3), "pixels": int(m.sum()), "seconds": round(time.time() - t0, 2), "spec": spec}


@command("doodle.say", puppet=("string", "puppet file (a doodle from doodle.snap, or any character)"), text=("string", "the line to say"),
         voice=("string", "a clean voice (Kokoro voices are clean)", "kokoro:af_heart"))
def doodle_say(puppet, text, voice="kokoro:af_heart"):
    """Step 3: the character says a line. The line is voiced in a separate process (Kokoro) with lip-sync cues from
    the model's own phoneme timings, and a short acting timeline is made for it: idle, a hop on an exclamation, a
    wave on a greeting, head and body beats while talking, blinks. Returns the audio file and the timeline, which the
    page plays live (Acting.evaluate with the template's clips)."""
    import hashlib
    reg = _voice_registry()
    if reg.get(voice, {}).get("status") != "clean":
        raise PermissionError(f"{voice} is not a clean voice")
    if not text.strip() or len(text) > 300:
        raise ValueError("say one line (up to 300 characters)")
    pz = _json(ROOT / puppet)
    if pz is None:
        raise FileNotFoundError(f"no puppet at {puppet}")
    out = DOODLES / "say"; out.mkdir(parents=True, exist_ok=True)
    wav = out / (hashlib.sha256(f"{voice}|{text}".encode()).hexdigest()[:16] + ".wav")
    r = json.loads(_run([PY, "engine/say_line.py", text, voice, str(wav), VOICES], timeout=300)[-1])
    dur, lead = r["duration"], 0.35
    tpl = pz.get("template", "humanoid"); low = text.lower().strip()
    clips = [{"clip": "idle", "start": 0}]
    if tpl == "doodle":
        if re.match(r"(hi|hello|hey|hiya|good (morning|afternoon|evening))\b", low):
            clips.append({"clip": "wave_R" if "arm_R" in pz["parts"] else "wave_L", "start": 0.0, "end": lead + 0.9, "fadeIn": 0.1, "fadeOut": 0.2})
        if "!" in text:
            clips.append({"clip": "hop", "start": 0.0, "additive": True, "fadeIn": 0, "fadeOut": 0})
        clips.append({"clip": "talk", "start": lead, "end": lead + dur, "weight": 0.8, "fadeIn": 0.1, "fadeOut": 0.2})
    else:
        if re.match(r"(hi|hello|hey)\b", low):
            clips.append({"clip": "wave_R", "start": 0.0, "end": lead + 1.2, "weight": 3})
        clips.append({"clip": "talk_beat", "start": lead, "end": lead + dur, "weight": 1})
    tl = {"clips": clips, "visemes": [[round(t + lead, 3), sh] for t, sh in r["visemes"]], "blink": True, "springs": False}
    return {"audio": str(wav.relative_to(ROOT)), "lead": lead, "duration": round(lead + dur + 0.6, 2), "timeline": tl, "visemes": len(r["visemes"]), "voice": voice}


@command("doodle.keep", id=("string", "doodle id"), name=("string", "the character's name"), owner=("string", "who drew it (the rights holder)"),
         voice=("string", "the character's voice", "kokoro:af_heart"))
def doodle_keep(id, name, owner, voice="kokoro:af_heart"):
    """Step 4: keep the doodle as a cast member (cast/drawn/<name>.puppet.json, rights: owner), with its voice, so
    films, the Rig Canvas and drawing requests can use it."""
    d = _doodle_dir(id); pz = _json(d / "doodle.puppet.json")
    slug = re.sub(r"[^a-z0-9_-]", "_", name.lower()).strip("_") or "doodle"
    pz["name"] = name; pz.setdefault("meta", {}).update({"author": owner, "license": "LicenseRef-owner", "made": "phone photo, auto cuts (doodle.snap)"})
    path = f"cast/drawn/{slug}.puppet.json"
    f = ROOT / path; f.parent.mkdir(parents=True, exist_ok=True); pz["meta"]["cast_path"] = path
    f.write_text(json.dumps(pz))
    idx = _json(ROOT / "cast" / "index.json", {"puppets": []})
    if not any(p.get("path") == path for p in idx["puppets"]):
        cast_add(path, slug, owner, "LicenseRef-owner", "drawn by the owner; photo cut and rigged by doodle.snap (plan 3.6)", voice={"voice": voice}, rights="owner", owner=owner)
    return {"path": path, "id": slug}


# ---------------- drawing request queue with ghost guides (plan 3.6, E20) ----------------
def _req_puppet(puppet):
    f = (ROOT / puppet).resolve()
    if not (str(f).startswith(str((ROOT / "cast").resolve()) + "/") or str(f).startswith(str(DOODLES.resolve()) + "/")) or not f.is_file():
        raise ValueError("drawing requests are for characters under cast/ or doodles under out/doodle/")
    return f


@command("drawing.requests", puppet=("string", "character file (cast/... or a doodle under out/doodle/)"),
         film=("string", "a film whose directions need drawings from this character (script.rigcheck); empty: every costly move", ""))
def drawing_requests(puppet, film=""):
    """Drawing request queue (plan 3.6, E20): each drawing this character is missing, for a film's directions or for
    its costly moves, becomes a request with the reason and a ghost guide (out/requests/): the character faintly at
    rest on its own artboard, the related drawing it has, and a dashed box where the new one goes: swap shapes, parts,
    pupils, a turned view, a tail drawn as a chain (WP-18). Needs that are rigged rather than drawn (new clips) are
    listed for the Rig Canvas. Queue: <puppet>.requests.json."""
    from . import director as DR, drawreq as RQ
    f = _req_puppet(puppet); p = _json(f); rel = str(f.relative_to(ROOT))
    if film:
        ch = next((v for v in script_rigcheck(film)["characters"].values() if v["puppet"] == rel), None)
        needs = (ch or {}).get("needs_drawings", {})
    else:
        needs = {}
        for c in DR.abilities(p, _clip_lib(p.get("template", "humanoid"), p))["costly"]:
            for lbl in c.get("draw", []):
                needs.setdefault(lbl, []).append(c["move"])
    qp = RQ.queue_path(rel); q = _json(qp, {"puppet": rel, "requests": []})
    # needs once left to the Rig Canvas that are now drawn over a ghost (pupils, a turned view: WP-18) are asked again
    q["requests"] = [r for r in q["requests"] if not (r["status"] == "rig_canvas" and RQ.parse_need(r["need"])[0]["kind"] != "canvas")]
    have = {(r.get("swap"), r.get("shape"), r.get("part"), r.get("what"), r.get("view")) for r in q["requests"]}
    for r in RQ.make_requests(p, needs):
        k = (r.get("swap"), r.get("shape"), r.get("part"), r.get("what"), r.get("view"))
        if k in have:
            continue
        r["id"] = f"r{max([int(x['id'][1:]) for x in q['requests'] if x['id'][1:].isdigit()] + [0]) + 1}"
        if film:
            r["film"] = film
        q["requests"].append(r); have.add(k)
    gdir = ROOT / "out" / "requests" / (f.parent.name if f.name == "doodle.puppet.json" else f.name.split(".")[0]); gdir.mkdir(parents=True, exist_ok=True)
    rest = None
    for r in q["requests"]:
        if r["status"] != "open" or (r.get("ghost") and (ROOT / r["ghost"]).exists()):
            continue
        if rest is None:
            rest = gdir / "rest.png"; (gdir / "rest.json").write_text(json.dumps(RQ.ghost_spec(p, rel)))
            _run(["node", "tools/pose_still.mjs", str(gdir / "rest.json"), str(rest)], timeout=300)
        r["ghost"] = str(RQ.compose_ghost(rest, p, r, gdir / f"{r['id']}.png").relative_to(ROOT))
    qp.write_text(json.dumps(q, indent=1))
    return {**q, "open": sum(r["status"] == "open" for r in q["requests"]), "rig_canvas": sum(r["status"] == "rig_canvas" for r in q["requests"])}


@command("drawing.fulfil", puppet=("string", "character file"), id=("string", "request id"),
         image=("string", "the drawing: made on the ghost guide (same framing), a canvas export or a photo"),
         render=("boolean", "re-render the request's film afterwards", False))
def drawing_fulfil(puppet, id, image, render=False):
    """Slot a drawing into the rig (plan 3.6, E20): ink is lifted from the drawing inside the request's box and stored
    as that swap shape or part (a tail gets its pivot where the stroke meets the body), the character is saved, and
    the request closes only when the rig check no longer lists the need; the moves that became free are reported.
    With render, the film that asked for it is re-rendered."""
    from . import director as DR, drawreq as RQ
    f = _req_puppet(puppet); rel = str(f.relative_to(ROOT)); p = _json(f)
    qp = RQ.queue_path(rel); q = _json(qp, {"requests": []})
    r = next((x for x in q["requests"] if x["id"] == id), None)
    if not r:
        raise ValueError(f"no request {id}")
    if r["status"] == "rig_canvas":
        raise ValueError(f"{r['need']} is rigged in the Rig Canvas, not drawn over a guide")
    img = Path(image) if Path(image).is_absolute() else ROOT / image
    lib = _clip_lib(p.get("template", "humanoid"), p)
    before = {c["move"] for c in DR.abilities(p, lib)["free"]}
    st, A = RQ.lift(img, p, r)
    where = RQ.slot(p, r, st, A)
    if rel.startswith("cast/"):
        puppet_save(rel, p)
    else:
        f.write_text(json.dumps(p))
    now_free = sorted({c["move"] for c in DR.abilities(p, lib)["free"]} - before)
    ok = not RQ.missing(p, r)
    r.update(status="done" if ok else "open", slotted=where, freed=now_free)
    qp.write_text(json.dumps(q, indent=1))
    out = {"request": r, "verified": ok, "now_free": now_free}
    if ok and render and r.get("film"):
        out["render"] = film_render(r["film"]).get("qa")
    return out


# ---------------- production orchestrator and board (plan 3.7) ----------------
def _today(today=""):
    import datetime as _dt
    return _dt.date.fromisoformat(today) if today else _dt.date.today()


@command("prod.plan", film=("string", "film folder name (it may not exist yet for claude or manual runners)"),
         post_on=("string", "posting date, YYYY-MM-DD"), runner=("string", "pipeline | claude | manual", "pipeline"),
         priority=("integer", "lower goes first among films posting the same day", 1),
         brief=("string", "for a new film: the brief (written to films/<film>/brief.md in its workspace)", ""),
         storyboard=("object", "for a new film: {format, brief} for film.from_template, built in its workspace at launch", None),
         plan=("object", "the calendar row it comes from (quarter, date, start_by, fact_lock_by, role, review)", None),
         budget_usd=("number", "for a claude runner: the most its session may spend (0: the board's default)", 0))
def prod_plan(film, post_on, runner="pipeline", priority=1, brief="", storyboard=None, plan=None, budget_usd=0):
    """Put a film on the production board (plan 3.7) with its posting date and the kind of session that makes it:
    pipeline (tools/film_agent.py rebuilds an existing film through every gate), claude (a Claude Code session with
    the director prompt), manual (any agent, given the written protocol)."""
    import datetime as _dt
    from . import production as PR
    _dt.date.fromisoformat(post_on)
    if runner not in ("pipeline", "claude", "manual"):
        raise ValueError("runner is pipeline, claude or manual")
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]{0,60}", film):
        raise ValueError("film names are lower-case letters, digits and -")
    if runner == "pipeline" and not (FILMS / film).is_dir():
        raise FileNotFoundError(f"the pipeline runner rebuilds an existing film; {film} does not exist")
    with PR.registry() as reg:
        e = reg["films"].get(film) or {"film": film, "state": "planned", "checkpoints": [], "events": []}
        if e["state"] not in ("planned", "queued", "stopped", "failed", "needs_work"):
            raise ValueError(f"{film} is {e['state']}; stop it first to re-plan")
        e.update(post_on=post_on, runner=runner, priority=priority, **({"brief": brief} if brief else {}),
                 **({"storyboard": storyboard} if storyboard else {}), **({"plan": plan} if plan else {}), **({"budget_usd": budget_usd} if budget_usd else {}))
        PR.event(e, "planned", post_on=post_on, runner=runner); reg["films"][film] = e
        return {k: e[k] for k in ("film", "post_on", "runner", "state")}


@command("prod.launch", film=("string", "one film, or empty for every planned film", ""), max_parallel=("integer", "sessions at once (0: keep the board's setting)", 0))
def prod_launch(film="", max_parallel=0):
    """Start production sessions (plan 3.7): each film gets a git worktree on branch film/<name> and a session that
    reports at checkpoints; beyond max_parallel, films queue and start as others finish (prod.status starts them)."""
    from . import production as PR
    with PR.registry() as reg:
        if max_parallel:
            reg["max_parallel"] = int(max_parallel)
        todo = [reg["films"][film]] if film else [e for e in reg["films"].values() if e["state"] == "planned"]
        for e in todo:
            if e["state"] not in ("planned", "stopped", "failed", "needs_work"):
                continue
            if e["runner"] != "pipeline":   # a new film's brief and draft storyboard go into its workspace (WP-06)
                sb = PR.prepare(e)
                if sb:
                    PR.event(e, "storyboard drafted", ok=sb["ok"], checks=sb["checks"], facts_need_sources=len(sb.get("facts_need_sources", [])))
            e["state"] = "queued"; PR.event(e, "queued")
        PR.tick(reg)
        return {"running": [k for k, e in reg["films"].items() if e["state"] == "running"], "queued": [k for k, e in reg["films"].items() if e["state"] == "queued"],
                "max_parallel": reg["max_parallel"]}


@command("prod.checkpoint", film=("string", "film"), stage=("string", "research | first_render | final"),
         report=("object", "the session's report: research {contradictions: [...]}, first_render {shot}, final {}", None))
def prod_checkpoint(film, stage, report=None):
    """A film session reports a checkpoint (plan 3.7). The orchestrator measures for itself in the film's workspace
    (research: research.check and counter-evidence in the ledger; first_render: the shot file's size; final: qa.json
    checks, loudness, layout, the director's verdict) and answers with a verdict (ok, ready, fail, blocked,
    escalate), the owner's pending instructions, and whether to continue. Research that contradicts the brief
    escalates to the owner and pauses the film."""
    from . import production as PR
    if stage not in PR.STAGES:
        raise ValueError(f"stage is one of {PR.STAGES}")
    return PR.checkpoint(film, stage, report or {})


@command("prod.status", today=("string", "date for the schedule (YYYY-MM-DD; default today)", ""))
def prod_status(today=""):
    """The production board (plan 3.7): every film with its state, checkpoints and verdicts, latest measurements,
    escalations, and where it stands against its posting date (on_track, due_soon, late, needs_owner); starts queued
    films when sessions finish. Also a calendar of posting dates by week."""
    import datetime as _dt
    from . import production as PR
    d = _today(today)
    with PR.registry() as reg:
        PR.tick(reg)
        films = []
        for e in sorted(reg["films"].values(), key=lambda e: (e["post_on"], e.get("priority", 1))):
            cps = e.get("checkpoints", [])
            last = {}
            for c in cps:
                last[c["stage"]] = {k: c[k] for k in ("verdict", "reasons", "measured", "at")}
            media = {k: str((PR.reg_dir() / e["film"] / f).relative_to(ROOT)) for k, f in (("poster", "poster.jpg"), ("first", "first.jpg"), ("final", "final.mp4"))
                     if (PR.reg_dir() / e["film"] / f).exists() and ROOT in (PR.reg_dir() / e["film"] / f).resolve().parents}
            films.append({"film": e["film"], "post_on": e["post_on"], "runner": e["runner"], "state": e["state"], "schedule": PR.schedule(e, reg["lead_days"], d),
                          "plan": e.get("plan"), "channel": (e.get("plan") or {}).get("channel"),
                          "cost_usd": e.get("cost_usd"), "costs": e.get("costs", []),   # WP-03: what its Claude Code sessions spent
                          "checkpoints": last, "escalation": e.get("escalation") if e["state"] == "escalated" else None,
                          "approved": (e.get("approvals") or [None])[-1], "narrowed": e.get("narrowed", []), "media": media,
                          "session": {k: v for k, v in (e.get("session") or {}).items() if k in ("runner", "started", "pid", "log")},
                          "events": e.get("events", [])[-5:]})
        weeks = {}
        for f in films:
            p = _dt.date.fromisoformat(f["post_on"]); wk = (p - _dt.timedelta(days=p.weekday())).isoformat()
            weeks.setdefault(wk, []).append({"film": f["film"], "post_on": f["post_on"], "status": f["schedule"]["status"], "channel": f["channel"]})
        counts = {}
        for f in films:
            counts[f["state"]] = counts.get(f["state"], 0) + 1
        chans = {c["id"]: {"name": c["name"], "colour": c["colour"]} for c in plan_channels()}   # WP-32: films by channel
        nf = PR.reg_dir() / "notifications.jsonl"
        notes = [json.loads(x) for x in nf.read_text().splitlines()[-20:]] if nf.exists() else []
        return {"today": d.isoformat(), "max_parallel": reg["max_parallel"], "lead_days": reg["lead_days"], "counts": counts, "channels": chans,
                "notifications": notes[::-1], "budget_usd": reg.get("budget_usd"), "spent_usd": round(sum(e.get("cost_usd") or 0 for e in reg["films"].values()), 2),
                "calendar": [{"week_of": k, "films": v} for k, v in sorted(weeks.items())], "films": films}


def _prod_entry(reg, film):
    e = reg["films"].get(film)
    if not e:
        raise KeyError(f"{film} is not in the production registry")
    return e


@command("prod.session_prompt", film=("string", "a film running with a manual runner"))
def prod_session_prompt(film):
    """The prompt for any agent session making a film (WP-03): the production protocol (brief, checkpoints, how to
    report) and the director prompt, ready to paste into a Claude Code session on this machine or in the cloud that
    works in the film's workspace."""
    from . import production as PR
    with PR.registry(write=False) as reg:
        e = _prod_entry(reg, film)
    pd = Path(e.get("workspace") or "") / ".production" / "PRODUCTION.md"
    if not pd.exists():
        raise FileNotFoundError(f"{film} has no workspace yet: prod.launch it")
    return {"film": film, "workspace": e["workspace"], "branch": e.get("branch"),
            "prompt": pd.read_text() + "\n\n" + (ROOT / "docs" / "director-prompt.md").read_text()}


@command("prod.stop", film=("string", "film"), reason=("string", "why", ""))
def prod_stop(film, reason=""):
    """Stop a film's session (plan 3.7); its workspace and branch stay, so it can be relaunched."""
    from . import production as PR
    with PR.registry() as reg:
        e = _prod_entry(reg, film); PR.kill(e); e["state"] = "stopped"; PR.event(e, "stopped by the owner", reason=reason)
        return {"film": film, "state": "stopped"}


@command("prod.narrow", film=("string", "film"), text=("string", "the change of scope, in plain words (e.g. drop the dosage claim; 30 s cut only)"))
def prod_narrow(film, text):
    """Narrow a film's scope (plan 3.7): the change is added to its brief in the workspace and delivered to the
    session with its next checkpoint answer."""
    from . import production as PR
    with PR.registry() as reg:
        e = _prod_entry(reg, film)
        e.setdefault("inbox", []).append({"at": PR.now(), "text": text}); e.setdefault("narrowed", []).append(text)
        if e.get("workspace"):
            PR.narrow_brief(e, text)
        PR.event(e, "narrowed", text=text)
        return {"film": film, "narrowed": e["narrowed"]}


@command("prod.relaunch", film=("string", "film"))
def prod_relaunch(film):
    """Start a stopped, failed, needs_work or escalated film's session again in its workspace (renders there are reused)."""
    from . import production as PR
    with PR.registry() as reg:
        e = _prod_entry(reg, film); PR.kill(e)
        if e["state"] == "escalated" and not e.get("decisions"):
            raise ValueError(f"{film} waits for the owner's decision on its research (prod.decide)")
        e["state"] = "queued"; PR.event(e, "relaunched"); PR.tick(reg)
        return {"film": film, "state": e["state"]}


@command("prod.decide", film=("string", "escalated film"), decision=("string", "proceed | narrow | stop"), note=("string", "for narrow: the change of scope; otherwise why", ""))
def prod_decide(film, decision, note=""):
    """The owner's decision on research that contradicts a film's brief (plan 3.7): proceed as briefed, narrow the
    scope (the note is added to the brief) and continue, or stop. Proceed and narrow relaunch the session."""
    from . import production as PR
    if decision not in ("proceed", "narrow", "stop"):
        raise ValueError("decision is proceed, narrow or stop")
    if decision == "narrow" and not note:
        raise ValueError("say how to narrow it")
    with PR.registry() as reg:
        e = _prod_entry(reg, film)
        if e["state"] != "escalated":
            raise ValueError(f"{film} is not waiting for a decision")
        e.setdefault("decisions", []).append({"at": PR.now(), "decision": decision, "note": note})
        PR.event(e, f"owner decided: {decision}", note=note)
        if decision == "stop":
            e["state"] = "stopped"; return {"film": film, "state": "stopped"}
        if decision == "narrow":
            e.setdefault("inbox", []).append({"at": PR.now(), "text": note}); e.setdefault("narrowed", []).append(note); PR.narrow_brief(e, note)
        e["state"] = "queued"; PR.tick(reg)
        return {"film": film, "state": e["state"]}


@command("prod.approve", film=("string", "film"), by=("string", "who approves (the owner)"), note=("string", "", ""))
def prod_approve(film, by, note=""):
    """The owner approves a film whose final render passed QA (plan 3.7); only approved films can be merged."""
    from . import production as PR
    with PR.registry() as reg:
        e = _prod_entry(reg, film)
        fin = [c for c in e.get("checkpoints", []) if c["stage"] == "final"]
        if e["state"] != "waiting_owner" or not fin or fin[-1]["verdict"] != "ready":
            raise ValueError(f"{film} has no passing final render to approve (state {e['state']})")
        if (fin[-1].get("measured") or {}).get("expert_review") == "pending":   # WP-05
            from . import research as RS
            led = RS.ledger(Path(e["workspace"]) / "films" / film) if e.get("workspace") else []
            if not any(x.get("role") == "expert_review" and x.get("verdict") == "cleared" for x in led):
                raise PermissionError(f"{film} needs an expert review before approval: a qualified reviewer records ledger.add role expert_review verdict cleared")
        e.setdefault("approvals", []).append({"by": by, "at": PR.now(), "note": note}); e["state"] = "approved"; PR.event(e, "approved", by=by)
        return {"film": film, "state": "approved"}


@command("prod.merge", film=("string", "approved film"))
def prod_merge(film):
    """Merge an approved film's branch into the current branch (plan 3.7), refusing a branch that touches anything
    outside the film's folder (or new characters in cast/drawn/); the approved render and QA report are copied next
    to the film data."""
    from . import production as PR
    with PR.registry() as reg:
        e = _prod_entry(reg, film)
        if e["state"] != "approved":
            raise ValueError(f"{film} is not approved (state {e['state']})")
        changed = PR.merge(e); e["state"] = "merged"; PR.event(e, "merged", files=len(changed))
        return {"film": film, "state": "merged", "files": changed}


# ---------------- content planner (plan 3.8) ----------------
CH_ARG = ("string", "channel id (default: the default channel, plan/channels.json)", "")


def _plan_bank(channel=""):
    from . import planner as PL
    return _json(PL.chan_dir(channel) / "ideas.json", {"note": "idea bank (plan 3.8): sweeps add ideas; the planner schedules them", "ideas": []})


def _plan_save(name, obj, channel=""):
    from . import planner as PL
    d = PL.chan_dir(channel); d.mkdir(parents=True, exist_ok=True); (d / name).write_text(json.dumps(obj, indent=1, ensure_ascii=False) + "\n")


def _plan_cal(quarter, channel=""):
    from . import planner as PL
    c = _json(PL.chan_dir(channel) / f"{quarter}.json")
    if not c:
        raise FileNotFoundError(f"no calendar for {quarter} on channel {channel or PL.default_channel()}: plan.schedule first")
    return c


@command("plan.quarters", channel=CH_ARG)
def plan_quarters(channel=""):
    """Quarters that have a calendar on a channel, newest first."""
    from . import planner as PL
    return sorted((f.stem for f in PL.chan_dir(channel).glob("*-Q*.json")), reverse=True)


@command("plan.channels")
def plan_channels():
    """The channels the studio plans for (WP-32), each with its audience, fields, brand kit, cast and quarters; the
    default first."""
    from . import planner as PL
    out = []
    for cid in sorted(PL.channel_ids(), key=lambda c: c != PL.default_channel()):
        ch = PL.channel(cid); br = _json(ROOT / "brand" / f"{ch.get('brand', 'brand')}.json", {})
        out.append({"id": cid, "name": ch["name"], "audience": ch["audience"], "fields": ch["fields"], "locale": ch.get("locale"),
                    "brand": ch.get("brand", "brand"), "colour": (br.get("palette") or {}).get(br.get("wordmark_accent", "primary")) or "#888888",
                    "cast": ch.get("cast"), "series": (ch["rules"].get("series") or {}).get("name"), "quarters": plan_quarters(cid),
                    "default": cid == PL.default_channel()})
    return out


@command("plan.channel", update=("object", "fields to change (name, audience, fields, locale, languages, rules, brand, cast, voices)", None),
         channel=("string", "channel id (default: the default channel); a new id makes a new channel from the defaults", ""))
def plan_channel(update=None, channel=""):
    """The channel the content planner plans for (plan 3.8): audience, topic fields, locale for the local quota, and the
    spread rules (posting days, the weekly series, topic diversity, field gap, local quota, analysis cadence, lead and
    fact-lock days per sweep), and (WP-32) its brand kit (brand/<brand>.json), default cast {role: character} and voices
    {character: voice}. plan/channels/<id>/channel.json."""
    from . import planner as PL
    ch = PL.channel(channel)
    if update:
        for k, v in update.items():
            ch[k] = {**ch[k], **v} if isinstance(v, dict) and isinstance(ch.get(k), dict) else v
        if ch.get("brand") and not (ROOT / "brand" / f"{ch['brand']}.json").exists():
            raise FileNotFoundError(f"no brand kit brand/{ch['brand']}.json")
        _plan_save("channel.json", {k: v for k, v in ch.items() if k != "id"}, channel)
    return ch


@command("plan.sweep_prompt", sweep=("string", "dated_hook | recent | evergreen | tool | analysis | local"), quarter=("string", "e.g. 2027-Q1"),
         count=("integer", "ideas to ask for", 20), channel=CH_ARG)
def plan_sweep_prompt(sweep, quarter, count=20, channel=""):
    """The research prompt for one sweep (plan 3.8), for a research agent with web search: what to find for this
    channel and quarter, the sourcing rules (real, opened sources; nothing invented) and the exact JSON to return,
    which plan.ideas_add accepts."""
    from . import planner as PL
    if sweep not in PL.SWEEPS:
        raise ValueError(f"sweep is one of {PL.SWEEPS}")
    return {"sweep": sweep, "channel": PL.channel(channel)["id"], "prompt": PL.sweep_prompt(sweep, quarter, PL.channel(channel), count)}


@command("plan.ideas_add", ideas=("array", "ideas in the sweep schema (plan.sweep_prompt)"), by=("string", "who found them (agent or person)"),
         check_urls=("boolean", "fetch every cited URL and refuse sources that do not exist", True), channel=CH_ARG)
def plan_ideas_add(ideas, by, check_urls=True, channel=""):
    """Add ideas to the bank (plan 3.8): each is checked (fields, sweep, a source URL, a date for dated hooks,
    fresh_until for recent stories, data and terms for analyses), near-duplicates of banked ideas are refused, and
    with check_urls every cited URL is fetched: an idea whose sources are all missing (404, or no such host) is
    refused, a missing source is dropped from an idea that has others, and each source records what the check saw."""
    from . import planner as PL
    rej0 = []
    if check_urls:
        st = PL.check_sources(ideas); keep = []
        for x in ideas:
            srcs = [dict(s, checked=st.get(s.get("url"), "unchecked")) for s in x.get("sources", []) if isinstance(s, dict)]
            good = [s for s in srcs if s["checked"] != "missing"]
            data_missing = isinstance(x.get("data"), dict) and st.get(x["data"].get("url")) == "missing"
            if not good or data_missing:
                rej0.append({"title": x.get("title"), "why": ["sources not found: " + ", ".join(s["url"] for s in srcs if s["checked"] == "missing")]}); continue
            keep.append({**x, "sources": good})
        ideas = keep
    bank = _plan_bank(channel); added, rejected = PL.add_ideas(bank, ideas, PL.channel(channel), by); rejected = rej0 + rejected
    _plan_save("ideas.json", bank, channel)
    return {"added": len(added), "ids": added, "rejected": rejected, "bank": len(bank["ideas"])}


@command("plan.ideas", sweep=("string", "filter", ""), field=("string", "filter", ""), status=("string", "filter", ""), channel=CH_ARG)
def plan_ideas(sweep="", field="", status="", channel=""):
    """The idea bank, filtered, with counts by sweep, field and status."""
    from collections import Counter
    ideas = [i for i in _plan_bank(channel)["ideas"] if (not sweep or i["sweep"] == sweep) and (not field or i["field"] == field) and (not status or i["status"] == status)]
    return {"count": len(ideas), "by_sweep": dict(Counter(i["sweep"] for i in ideas)), "by_field": dict(Counter(i["field"] for i in ideas)),
            "by_status": dict(Counter(i["status"] for i in ideas)), "ideas": ideas}


@command("plan.schedule", quarter=("string", "e.g. 2027-Q1"), planned_on=("string", "the day the plan is made (lead times count from it; default today)", ""),
         channel=CH_ARG)
def plan_schedule(quarter, planned_on="", channel=""):
    """Make the quarter's calendar (plan 3.8): dated hooks on their day, the weekly series, the analysis cadence, the
    local quota, then the rest, an empty field getting the next slot; each row with a start-by date and a fact-lock
    date. Writes plan/<quarter>.json (ideas used are marked planned) and returns plan.check's verdict."""
    import datetime as _dt
    from . import planner as PL
    ch = PL.channel(channel); bank = _plan_bank(channel); po = _dt.date.fromisoformat(planned_on) if planned_on else _dt.date.today()
    old = _json(PL.chan_dir(channel) / f"{quarter}.json")
    if old and any(r.get("film") for r in old["rows"]):
        raise ValueError(f"{quarter} already has briefed rows; edit it rather than re-planning")
    for i in bank["ideas"]:   # re-planning frees this quarter's ideas
        if i["status"] == "planned" and i.get("quarter") == quarter:
            i["status"] = "idea"
    rows = PL.schedule(quarter, bank, ch, po)
    used = {r["idea"] for r in rows if r.get("idea")}
    for i in bank["ideas"]:
        if i["id"] in used:
            i["status"] = "planned"; i["quarter"] = quarter
    cal = {"quarter": quarter, "planned_on": po.isoformat(), "channel": ch["name"], "channel_id": ch["id"], "rules": ch["rules"], "rows": rows}
    _plan_save(f"{quarter}.json", cal, channel); _plan_save("ideas.json", bank, channel)
    return PL.check(cal, bank, ch)


@command("plan.check", quarter=("string", "e.g. 2027-Q1"), channel=CH_ARG)
def plan_check(quarter, channel=""):
    """Check a quarter's calendar against every spread rule (plan 3.8), independently of how it was made: slots
    filled, posts per week, topic diversity, field gap, local quota, analysis cadence, series cadence, dated hooks on
    their day and recent stories while fresh, lead times, a fact-lock date on every row, an empty field getting the
    next slot, no repeats, sources on every idea."""
    from . import planner as PL
    return PL.check(_plan_cal(quarter, channel), _plan_bank(channel), PL.channel(channel))


@command("plan.track", quarter=("string", "e.g. 2027-Q1"), today=("string", "YYYY-MM-DD (default today)", ""), channel=CH_ARG)
def plan_track(quarter, today="", channel=""):
    """The live tracker (plan 3.8): every row with where it really is (planned, briefed, in production, final ready,
    approved, merged, posted, from the films and the production registry), its fact-lock status (locked once the
    film's ledger has a cleared fact gate) and what is overdue."""
    from . import planner as PL, production as PR
    reg = {}
    if (PR.reg_dir() / "registry.json").exists():
        with PR.registry(write=False) as r:
            reg = r["films"]
    rows = PL.track(_plan_cal(quarter, channel), _plan_bank(channel), reg, _today(today))
    from collections import Counter
    return {"quarter": quarter, "channel": PL.channel(channel)["id"], "today": _today(today).isoformat(), "stages": dict(Counter(r["stage"] for r in rows)),
            "overdue": [r for r in rows if r["overdue"]], "rows": rows}


@command("plan.brief", quarter=("string", "e.g. 2027-Q1"), date=("string", "the row's posting date"),
         storyboard=("boolean", "also draft the storyboard from the row's format template (film.from_template)", True),
         launch=("boolean", "put it on the production board with its posting date and start its session (prod.plan + prod.launch)", False),
         runner=("string", "production runner when launching: claude | manual", "claude"), channel=CH_ARG)
def plan_brief(quarter, date, storyboard=True, launch=False, runner="claude", channel=""):
    """Calendar to production in one command (plan 3.8, WP-06, feature map E24): the row's brief (hook, angle, why now,
    starting-point sources, research leads, cautions, start-by and fact-lock dates, review level), a draft storyboard
    from the format template the row names (myth_vs_data, explainer, dialogue), drafted from the idea's own words with
    every fact unsourced so the research gate holds it, and its storyboard.check. Without launch it is written to
    films/<slug>/ for a look; with launch it goes onto the board with its plan row and starts a session, and the brief
    and storyboard are committed on the film's branch in its workspace (nothing is left in the main checkout)."""
    from . import planner as PL
    cal = _plan_cal(quarter, channel); bank = _plan_bank(channel); ch = PL.channel(channel)
    row = next((r for r in cal["rows"] if r["date"] == date and r.get("idea")), None)
    if not row:
        raise ValueError(f"no planned row on {date}")
    idea = next(i for i in bank["ideas"] if i["id"] == row["idea"])
    film = row.get("film") or PL.slug(idea["title"])
    d = FILMS / film
    if (d / "script.json").exists():
        raise FileExistsError(f"films/{film} already has a script")
    text = PL.brief_md(idea, row, ch)
    fmt, fields = PL.draft_storyboard(idea, row)
    fields.update({k: ch[k] for k in ("cast", "voices") if ch.get(k)})   # WP-32: the channel's cast, voices and brand kit
    fields["brand"] = ch.get("brand", "brand")
    out = {"film": film, "format": fmt, "channel": ch["id"]}
    if launch:
        if runner not in ("claude", "manual"):
            raise ValueError("a new film is made by a claude or manual session")
        plan = {"channel": ch["id"], "quarter": quarter, "date": row["date"], "start_by": row["start_by"], "fact_lock_by": row["fact_lock"]["by"],
                "role": row.get("role"), "review": row.get("review", "standard"), "idea": idea["id"], "title": idea["title"]}
        out["production"] = prod_plan(film, date, runner=runner, brief=text, storyboard={"format": fmt, "brief": fields} if storyboard else None, plan=plan)
        out["launch"] = prod_launch(film)
        from . import production as PR
        with PR.registry(write=False) as reg:
            ev = [x for x in reg["films"][film]["events"] if x.get("what") == "storyboard drafted"]
        out["storyboard"] = ev[-1] if ev else None
        out["brief"] = f"films/{film}/brief.md (in its workspace, branch film/{film})"
    else:
        d.mkdir(parents=True, exist_ok=True); (d / "brief.md").write_text(text)
        out["brief"] = f"films/{film}/brief.md"
        if storyboard:
            out["storyboard"] = film_from_template(film, fmt, fields)["storyboard"]
    row["film"] = film; idea["status"] = "briefed"; idea["film"] = film
    _plan_save(f"{quarter}.json", cal, channel); _plan_save("ideas.json", bank, channel)
    return out


@command("plan.posted", quarter=("string", "e.g. 2027-Q1"), date=("string", "the row's posting date"), url=("string", "where it was posted"), channel=CH_ARG)
def plan_posted(quarter, date, url, channel=""):
    """Mark a calendar row as posted, with its link (the tracker's last stage)."""
    cal = _plan_cal(quarter, channel); row = next((r for r in cal["rows"] if r["date"] == date and r.get("idea")), None)
    if not row:
        raise ValueError(f"no planned row on {date}")
    row["posted"] = {"url": url, "at": _today().isoformat()}; _plan_save(f"{quarter}.json", cal, channel)
    bank = _plan_bank(channel)
    for i in bank["ideas"]:
        if i["id"] == row["idea"]:
            i["status"] = "posted"
    _plan_save("ideas.json", bank, channel)
    return row


# ---------------- series production (WP-28) ----------------
SERIES = ROOT / "series"


def _series(sid):
    d = SERIES / sid
    if not (d / "bible.json").exists():
        raise FileNotFoundError(f"no series/{sid}/bible.json")
    return d


@command("series.plan", series=("string", "series id (series/<id>/bible.json, briefs.json)"))
def series_plan(series):
    """Plan a series' episodes (WP-28): each brief in series/<id>/briefs.json becomes an episode with its posting date
    from the bible's cadence, the running gags due that episode, the props it carries and what each role knows by
    then. Writes series/<id>/episodes.json and schedule.ics (one event per episode)."""
    from . import series as SR
    d = _series(series); b = SR.load(d); briefs = _json(d / "briefs.json")["episodes"]
    eps = SR.plan_episodes(b, briefs); old = {e["n"]: e for e in _json(d / "episodes.json", {"episodes": []})["episodes"]}
    for e in eps:   # keep what was made of an episode already
        for k in ("status", "qa", "length_s"):
            if k in old.get(e["n"], {}):
                e[k] = old[e["n"]][k]
    (d / "episodes.json").write_text(json.dumps({"series": series, "episodes": eps}, indent=1, ensure_ascii=False) + "\n")
    ics = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//Doodleberry//series//EN"]
    for e in eps:
        day = e["date"].replace("-", "")
        ics += ["BEGIN:VEVENT", f"UID:{e['name']}@doodleberry", f"DTSTAMP:{day}T000000Z", f"DTSTART;VALUE=DATE:{day}", f"SUMMARY:{b['title']} #{e['n']}: {e['title']}", "END:VEVENT"]
    (d / "schedule.ics").write_text("\r\n".join(ics + ["END:VCALENDAR"]) + "\r\n")
    return {"series": series, "episodes": [{k: e[k] for k in ("n", "name", "date", "title", "gags", "props", "learns")} for e in eps]}


@command("series.make", series=("string", "series id"), episodes=("array", "episode numbers (default all)", None), render=("boolean", "voice, act and render", True))
def series_make(series, episodes=None, render=True):
    """Make a series' episodes from data (WP-28): each episode's film from the bible's format and its brief (gag lines
    in place), the persisting props held by their owners in every shot they are in, voiced, acted (the gesture planner,
    then the gags' acting directions) and rendered; then continuity is checked across every episode made."""
    from . import series as SR
    d = _series(series); b = SR.load(d); ep_all = _json(d / "episodes.json")["episodes"]
    want = set(episodes or [e["n"] for e in ep_all]); out = []
    for ep in ep_all:
        if ep["n"] not in want:
            continue
        name = ep["name"]
        if (FILMS / name).exists():
            shutil.rmtree(FILMS / name)
        film_from_template(name, b["format"], SR.brief_for(b, ep))
        sj = _json(FILMS / name / "shots.json")
        for sh_, props in zip(sj["shots"], SR.prop_entries(b, ep, sj["shots"])):
            if props:
                sh_["props"] = props
        sj["series"] = {"id": series, "episode": ep["n"]}
        (FILMS / name / "shots.json").write_text(json.dumps(sj, indent=1, ensure_ascii=False))
        row = {"n": ep["n"], "film": name, **_series_research(d, b, ep)}
        pk = ep["brief"].get("packaging")
        if pk:   # titles and thumbnails written with the brief, each checked as any film's are (WP-07)
            ts = title_set(name, titles=pk.get("titles"), thumbnails=pk.get("thumbnails"), by=pk.get("by", "series brief"))
            row["titles_passing"] = ts.get("titles_passing", ts.get("passing"))
        if render:
            voice_build(name); retime(name); acting_plan(name)
            dr = SR.directions(b, ep)
            if dr:
                ad = acting_direct(name, text=dr); row["directed"] = dr
            r = film_heal(name, rounds=3)   # render, and repair what the QA bar and layout checks find
            if ep["brief"].get("packaging"):
                try:
                    cover_make(name); row["covers"] = True
                except Exception as e:
                    row["covers"] = f"not made: {str(e)[:100]}"
            row["healed"] = [x["what"] for e in r.get("rounds") or [] for x in e.get("repairs", [])][:8]
            r = {"qa": _json(FILMS / name / "build" / "qa.json", {}).get("checks", {})}
            row["qa_failures"] = sorted(k for k, v in (r.get("qa") or {}).items() if v is False)
            row["length_s"] = round(float(_run(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", str(FILMS / name / "build" / "final.mp4")])[-1]), 2)
            ep["status"] = "rendered" if not row["qa_failures"] else "qa failing"; ep["qa"] = row["qa_failures"]; ep["length_s"] = row["length_s"]
        out.append(row)
    (d / "episodes.json").write_text(json.dumps({"series": series, "episodes": ep_all}, indent=1, ensure_ascii=False) + "\n")
    return {"series": series, "made": out, "continuity": series_continuity(series)}


def _series_research(d, b, ep):
    """write an episode's research_log.md from its brief and the series' gate reviews, and carry the gate verdict to
    its ledger only when the review is of exactly these facts (series/<id>/gate.json, keyed by episode, with the
    hash of the facts reviewed); a changed fact needs a new review"""
    from . import series as SR
    from . import research
    g = _json(d / "gate.json", {"reviews": {}})["reviews"].get(str(ep["n"]))
    fd = FILMS / ep["name"]; h = SR.facts_hash(ep["brief"])
    current = bool(g and g.get("facts_hash") == h)
    (fd / "research_log.md").write_text(SR.research_log(b, ep, g if current else None))
    hist = [x for x in _json(d / "gate.json", {}).get("history", []) if x["episode"] == ep["n"]]
    if research.ledger(fd) == []:   # the episode's review rounds, oldest first, so its ledger shows how it was cleared
        for x in hist[:-1] if current else hist:
            research.add(fd, "fact_gate", x["verdict"], f"series gate review {x['at']} by {x['reviewer']} (of an earlier text)" + (": " + "; ".join(x["issues"]) if x["issues"] else ""))
    if current:
        research.add(fd, "fact_gate", g["verdict"], f"series gate review {g.get('at')} by {g.get('reviewer')}: " + ("; ".join(f"{i.get('fact')}: {i.get('problem')}" for i in g.get("issues", [])) or "no issues")[:600])
    return {"gate": g["verdict"] if current else ("stale: facts changed since the review" if g else "not reviewed")}


@command("series.gate", series=("string", "series id"), review=("string", "path to the fresh fact-gate reviewer's report: a JSON list [{episode, verdict, sources, issues, counter_evidence}]"),
         reviewer=("string", "who reviewed (e.g. 'fresh fact_gate agent')"), at=("string", "date of the review (YYYY-MM-DD)"))
def series_gate(series, review, reviewer, at):
    """Record a fresh fact-gate reviewer's verdicts on a series' episodes (WP-28) in series/<id>/gate.json, each tied
    to the hash of the facts reviewed, and carry them to the episodes already made (research_log.md and ledger).
    The reviewer is not the builder: give it the episodes' facts and sources, not the builder's conclusions."""
    from . import series as SR
    d = _series(series); b = SR.load(d); rp = (ROOT / review).resolve() if not Path(review).is_absolute() else Path(review)
    rows = json.loads(rp.read_text()); eps = {e["n"]: e for e in _json(d / "episodes.json")["episodes"]}
    gate = _json(d / "gate.json", {"note": "WP-28: fact-gate reviews per episode (series.gate), tied to the facts reviewed", "reviews": {}})
    out = []
    for r in rows:
        ep = eps.get(int(r["episode"]))
        if not ep or r.get("verdict") not in ("cleared", "blocked"):
            raise ValueError(f"bad review row: {str(r)[:120]}")
        gate["reviews"][str(ep["n"])] = {**{k: r.get(k) for k in ("verdict", "sources", "issues", "counter_evidence")}, "reviewer": reviewer, "at": at,
                                         "facts_hash": SR.facts_hash(ep["brief"])}
        gate.setdefault("history", []).append({"episode": ep["n"], "verdict": r["verdict"], "reviewer": reviewer, "at": at,
                                               "issues": [f"{i.get('fact')}: {i.get('problem')}" for i in r.get("issues", []) if not str(i.get("problem", "")).startswith("(Non-blocking)")]})
        out.append({"episode": ep["n"], "verdict": r["verdict"], "carried_to_film": (FILMS / ep["name"] / "shots.json").exists()})
    (d / "gate.json").write_text(json.dumps(gate, indent=1, ensure_ascii=False) + "\n")
    for o in out:   # after gate.json is written: _series_research reads it
        if o["carried_to_film"]:
            _series_research(d, b, eps[o["episode"]])
    return {"series": series, "reviews": out}


@command("series.continuity", series=("string", "series id"))
def series_continuity(series):
    """Continuity across a series (WP-28, E16), read from the episodes' films: each role's puppet and voice, the
    persisting props (on screen with their owner from the episode they appear in until they are lost, never before),
    the running gags on their cadence, nobody speaking of a fact before the episode they learn it and the learner not
    asking again about what they learnt, and every episode's length within the band."""
    from . import series as SR
    d = _series(series); b = SR.load(d); films = []
    for e in _json(d / "episodes.json")["episodes"]:
        f = FILMS / e["name"]
        if (f / "script.json").exists():
            films.append((e["n"], _json(f / "script.json"), _json(f / "shots.json"), e.get("length_s")))
    probs = SR.check(b, films)
    return {"series": series, "episodes_checked": len(films), "ok": not probs, "problems": probs}


@command("teach.tutorial", name=("string", "film"))
def teach_tutorial(name):
    """Teaching mode (WP-28): a film's pipeline as a step-by-step tutorial (build/tutorial/index.md and images): the
    brief, the script, each character's model sheet, the voice, the acting, a frame of every shot, and the exact
    commands that made each step, so a learner can repeat it on their own character."""
    d = _film(name); s = _shots(name); sc = _json(d / "script.json", {}); tm = _json(d / "timing.json", {})
    td = d / "build" / "tutorial"; shutil.rmtree(td, ignore_errors=True); td.mkdir(parents=True)
    md = [f"# Making “{s.get('title', name)}”, step by step", "", "Every step below is one command; run them in order on your own film.", ""]
    md += ["## 1. The brief", "", (d / "brief.md").read_text().strip() if (d / "brief.md").exists() else "(no brief)", ""]
    fmt = sc.get("format")
    md += ["## 2. The storyboard", "", f"`python -m dbe film.from_template '{{\"name\": \"{name}\", \"format\": \"{fmt}\", \"brief\": {{...}}}}'`" if fmt else "Write script.json and shots.json.", "",
           *[f"- **{l.get('speaker', '')}:** {l['text']}" for l in sc.get("lines", [])], ""]
    md += ["## 3. The cast", ""]
    for p in sorted({c["puppet"] for sh in s["shots"] for c in sh.get("cast", [])}):
        img = td / (Path(p).name.split(".")[0] + ".sheet.png")
        try:
            puppet_sheet(p, str(img.relative_to(ROOT))); md += [f"![{Path(p).name}]({img.name})", ""]
        except Exception as e:
            md += [f"(model sheet of {p} not made: {str(e)[:60]})", ""]
        md += [f"`python -m dbe puppet.sheet '{{\"path\": \"{p}\"}}'`", ""]
    md += ["## 4. The voice", "", "`python -m dbe voice.build '{\"name\": \"" + name + "\"}'`", "",
           *[f"- {l['id']}: {l['start']:.2f} to {l['end']:.2f} s, {len(l.get('words') or [])} words" for l in tm.get("lines", [])], ""]
    md += ["## 5. The acting", "", "`python -m dbe acting.plan '{\"name\": \"" + name + "\"}'` (gestures from the voice), then optional directions in plain words with `acting.direct`.", ""]
    md += ["## 6. The render", "", "`python -m dbe film.render '{\"name\": \"" + name + "\"}'`", ""]
    final = d / "build" / "final.mp4"
    for sh in s["shots"]:
        t = (sh["start"] + sh["end"]) / 2; img = td / f"{sh['id']}.png"
        if final.exists():
            subprocess.run(["ffmpeg", "-v", "error", "-y", "-ss", f"{t:.2f}", "-i", str(final), "-frames:v", "1", "-vf", "scale=360:-2", str(img)])
            md += [f"![shot {sh['id']}]({img.name})", f"Shot {sh['id']}: {sh.get('set')} set, {len(sh.get('cast', []))} character(s), {sh['start']:.1f} to {sh['end']:.1f} s.", ""]
    md += ["## 7. Check and post", "", "`qa.run`, `film.package`, `cover.make`, `post.queue`; afterwards `analytics.checklist`.", ""]
    (td / "index.md").write_text("\n".join(md) + "\n")
    return {"tutorial": str((td / "index.md").relative_to(ROOT)), "images": sorted(p.name for p in td.glob("*.png"))}


# ---------------- library economics and creator packages (WP-29) ----------------
def _catalogue(include_cuts=False):
    """every film in films/ (scratch copies left out; derived cuts left out unless asked)"""
    return sorted(p.name for p in FILMS.iterdir() if ((p / "shots.json").exists() or (p / "scene.js").exists() and (p / "script.json").exists())
                  and not p.name.startswith("zz-") and (include_cuts or "--" not in p.name))


@command("usage.report", films=("array", "films (default: the whole catalogue)", None), rates=("object", "optional royalty rates per second: {\"owner\": {name: rate}, \"kind\": {puppet|clip|set|prop|icon|voice: rate}, \"currency\": \"USD\"}", None),
         include_cuts=("boolean", "count derived cuts (films/<name>--16x9 ...) as films of their own", False))
def usage_report(films=None, rates=None, include_cuts=False):
    """Screen time per asset (WP-29, E15), from each film's shots.json: every puppet, clip, set, prop, overlay icon
    and voice in seconds, with the films it is in, its owner and licence (puppets from the cast library, clip packs
    from their author, voices from the registry), totals by owner, and with rates what each owner is owed. Writes
    out/usage/usage.json and usage.csv. Films whose times cannot be resolved are listed with the reason."""
    from . import usage as U
    lib = U.Library(ROOT); names = films or _catalogue(include_cuts); ok, skipped = [], []
    for n in names:
        try:
            ok.append((n, _shots(n) if (FILMS / n / "shots.json").exists() else None, _json(FILMS / n / "script.json", {}), _json(FILMS / n / "timing.json", {})))
        except Exception as e:
            skipped.append({"film": n, "why": str(e)[:160]})
    r = U.report(lib, ok, rates)
    od = ROOT / "out" / "usage"; od.mkdir(parents=True, exist_ok=True)
    r = {"films": len(names), "covered": [n for n, *_ in ok], "planned": [n for n, _, _, tm in ok if tm.get("draft")], "skipped": skipped, **r}
    (od / "usage.json").write_text(json.dumps(r, indent=1, ensure_ascii=False)); (od / "usage.csv").write_text(U.csv(r["assets"]))
    unreg = [a["id"] for a in r["assets"] if a["kind"] == "puppet" and not a.get("registered")]
    return {"films": r["films"], "covered": len(ok), "planned": r["planned"], "skipped": skipped, "assets": len(r["assets"]),
            "by_kind": {k: sum(1 for a in r["assets"] if a["kind"] == k) for k in ("puppet", "clip", "set", "prop", "icon", "voice", "boil", "scene")},
            "owners": [{k: o[k] for k in ("owner", "seconds", "assets")} for o in r["owners"]], "unregistered_puppets": unreg,
            "payouts": (r["payouts"] or {}).get("by_owner"), "report": "out/usage/usage.json", "csv": "out/usage/usage.csv"}


@command("pack.make", kind=("string", "rig | loops | boil"), id=("string", "pack id (lower-case, hyphens)"), name=("string", "pack name"),
         version=("string", "pack version, e.g. 1.0.0"), author=("string", "who made it (credited and paid by the usage report)"),
         license=("string", "an SPDX id (CC-BY-4.0, CC0-1.0...) or LicenseRef-owner for a creator's own terms"),
         source=("string", "rig: a cast id or .puppet.json path; loops: a cast id or .puppet.json whose own clips (or a template, e.g. humanoid) the clips come from; boil: a film whose first boiled shot gives the settings", ""),
         clips=("array", "loops: the clip names to pack", None), boil=("object", "boil: the settings {fps, frames, amount, freq} (instead of source)", None),
         description=("string", "what it is", ""), contact=("string", "how to reach the creator", ""),
         royalty=("object", "optional terms {per_second, currency}: the usage report pays them for screen time", None))
def pack_make(kind, id, name, version, author, license, source="", clips=None, boil=None, description="", contact="", royalty=None):
    """Package a creator's rig template, loop pack or boil preset (WP-29) as out/packs/<id>-<version>.dbpack: the
    payload with its sha256s, the author, licence, royalty terms and what it needs (template, puppet format), ready to
    install into another project with pack.install."""
    from . import packs as PK
    if license not in OPEN_LICENSES and not license.startswith("LicenseRef-"):
        raise ValueError(f"licence: an open SPDX id ({', '.join(sorted(OPEN_LICENSES))}) or LicenseRef-<terms>")
    cast = {e["id"]: e for e in _json(ROOT / "cast" / "index.json", {"puppets": []})["puppets"]}
    path_of = lambda s_: cast[s_]["path"] if s_ in cast else s_
    meta = {"id": id, "name": name, "version": version, "author": author, "license": license, **({"description": description} if description else {}),
            **({"contact": contact} if contact else {}), **({"royalty": royalty} if royalty else {})}
    if kind == "rig":
        pp = path_of(source); pup = _json(ROOT / pp)
        if not pup:
            raise FileNotFoundError(f"no puppet {source}")
        missing = [i for i in puppet_lint(pp)["issues"] if i["level"] == "missing"]
        if missing:
            raise ValueError(f"the rig is incomplete: {missing[:3]}")
        meta["requires"] = {"template": pup["template"], "puppet_format": pup.get("version")}
        payload = {f"{id}.puppet.json": pup}
    elif kind == "loops":
        if not clips:
            raise ValueError("name the clips to pack")
        if (ROOT / "puppet" / "clips" / f"{source}.json").exists():
            tpl, have = source, _json(ROOT / "puppet" / "clips" / f"{source}.json")["clips"]
        else:
            pup = _json(ROOT / path_of(source)); tpl, have = pup["template"], pup.get("clips") or {}
        miss = [c for c in clips if c not in have]
        if miss:
            raise ValueError(f"no clips {miss} in {source}")
        meta["requires"] = {"template": tpl}
        payload = {"clips.json": {"template": tpl, "clips": {c: {k: v for k, v in have[c].items() if k != "pack"} for c in clips}}}
    elif kind == "boil":
        b = boil or next(((sh.get("style") or {}).get("boil") for sh in _shots(source, resolve=False)["shots"] if (sh.get("style") or {}).get("boil")), None)
        if not b:
            raise ValueError("give boil settings, or a film with a boiled shot")
        payload = {"boil.json": {k: b[k] for k in PK.BOIL_KEYS if k in b}}
    else:
        raise ValueError(f"kind is one of {PK.KINDS}")
    out, pk = PK.make(ROOT / "out" / "packs", kind, meta, payload)
    return {"pack": str(out.relative_to(ROOT)), "kind": kind, "files": [f["path"] for f in pk["files"]], "requires": pk.get("requires")}


@command("pack.install", pack=("string", "path to a .dbpack"), project=("string", "the Doodleberry project to install into (default: this one)", ""))
def pack_install(pack, project=""):
    """Install a creator pack (WP-29) into a project: a rig into cast/packs/ and the cast library (linted with that
    project's own loader against its template), a loop pack into the template's clip library (every renderer and the
    bake read it), a boil preset into presets/boil/. Hashes are checked; clip names already taken are refused."""
    from . import packs as PK
    pp = Path(pack) if Path(pack).is_absolute() else ROOT / pack
    return PK.install(Path(project).resolve() if project else ROOT, pp)


@command("boil.apply", name=("string", "film"), preset=("string", "an installed boil preset id (presets/boil/<id>.json)"), shots=("array", "shot ids (default: every shot)", None))
def boil_apply(name, preset, shots=None):
    """Put a boil preset on a film's shots (WP-29): style.boil gets the preset's settings and style.boil_preset its id,
    so the usage report counts the preset's screen time for its author."""
    pr = _json(ROOT / "presets" / "boil" / f"{preset}.json")
    if not pr:
        raise FileNotFoundError(f"no boil preset {preset} (pack.install one)")
    d = _film(name); sj = _json(d / "shots.json"); done = []
    for sh in sj["shots"]:
        if shots is None or sh["id"] in shots:
            st = sh.setdefault("style", {}); st["boil"] = {k: pr[k] for k in ("fps", "frames", "amount", "freq") if k in pr}; st["boil_preset"] = preset; done.append(sh["id"])
    (d / "shots.json").write_text(json.dumps(sj, indent=1, ensure_ascii=False))
    return {"film": name, "preset": preset, "shots": done}


@command("font.sheet", id=("string", "font id (out/fonts/<id>/)"), chars=("string", "the characters to collect (default: A-Z, a-z, 0-9 and punctuation)", ""),
         cols=("integer", "boxes per row", 10), title=("string", "heading printed on the sheet", "Handwriting sheet"))
def font_sheet(id, chars="", cols=10, title="Handwriting sheet"):
    """A printable handwriting sheet (WP-29): one box per character with its label, a baseline and an x-height line in
    a light blue that drops out of the scan, and corner marks for registration (A4, 300 dpi: sheet.png, sheet.pdf and
    sheet.json, the layout font.from_samples reads)."""
    from . import handfont as HF
    od = ROOT / "out" / "fonts" / id; od.mkdir(parents=True, exist_ok=True)
    L = HF.sheet(chars or HF.DEFAULT_CHARS, od / "sheet.png", title, cols)
    return {"sheet": str((od / "sheet.png").relative_to(ROOT)), "pdf": str((od / "sheet.pdf").relative_to(ROOT)), "boxes": len(L["cells"])}


@command("font.from_samples", id=("string", "font id (its sheet is out/fonts/<id>/sheet.json)"), scan=("string", "the filled sheet, scanned or photographed (PNG or JPEG)"),
         family=("string", "font family name"), designer=("string", "whose handwriting it is (credited in the font's name table)"),
         license=("string", "the licence the artist gives the font (e.g. OFL-1.1 or LicenseRef-owner)", "LicenseRef-owner"))
def font_from_samples(id, scan, family, designer, license="LicenseRef-owner"):
    """A handwriting font from an artist's filled sheet (WP-29): the page is registered by its corner marks, each box's
    ink is kept (the guides drop out) and traced with potrace into outlines, placed on the box's baseline at the
    font's x-height, and built into an OpenType font with fontTools (out/fonts/<id>/<family>.otf) with a preview."""
    from . import handfont as HF
    od = ROOT / "out" / "fonts" / id; L = _json(od / "sheet.json")
    if not L:
        raise FileNotFoundError(f"no sheet for {id}: run font.sheet first")
    pot = ROOT / "out" / "vendor-build" / "potrace" / "bin" / "potrace"
    if not pot.exists():
        vendor_build("potrace")
    sp = Path(scan) if Path(scan).is_absolute() else ROOT / scan
    page = HF.read_scan(sp, L); Image_ = __import__("PIL.Image", fromlist=["Image"]); Image_.fromarray(page).save(od / "registered.png")
    rows = []
    for c in L["cells"]:
        ink, org = HF.cell_ink(page, c); rows.append((c["char"], ink, org, c["baseline"], c["xheight"]))
    out = od / f"{family.replace(' ', '')}.otf"
    rep = HF.build(rows, out, family, designer, pot)
    from PIL import Image, ImageDraw, ImageFont
    f = ImageFont.truetype(str(out), 96); pv = Image.new("RGB", (2000, 420), "white"); dr = ImageDraw.Draw(pv)
    dr.text((40, 30), "The quick brown fox jumps", font=f, fill="black"); dr.text((40, 200), "over the lazy dog? 0123456789", font=f, fill="black")
    pv.save(od / "preview.png")
    (od / "font.json").write_text(json.dumps({"family": family, "designer": designer, "license": license, "file": out.name, "glyphs": rep}, indent=1, ensure_ascii=False))
    empty = [g["char"] for g in rep if g.get("empty")]
    return {"font": str(out.relative_to(ROOT)), "glyphs": len(rep) - len(empty), "empty_boxes": empty, "preview": str((od / "preview.png").relative_to(ROOT)), "license": license}


