@command("film.comic", name=("string", "film"), kind=("string", "comic (six panels to an A4 page) | storybook (a picture and its words on each square page)", "comic"),
         dsf=("number", "frame scale for the panels (1 = the film's pixels)", 1.0))
def film_comic(name, kind="comic", dsf=1.0):
    """A printable comic or storybook from a film's data alone (WP-30): a panel for every voiced line (the player's
    frame at that moment, without its bubbles or captions, cropped around the characters) with the line set by Typst
    as a speech balloon pointing at the speaker's head or a caption for the narrator, and a silent panel for a shot
    with no lines. Writes build/<kind>/<kind>.typ, .pdf and a PNG per page, then reads the PDF back: every line's words
    must be in it, one picture per panel."""
    from . import comic as CM
    from PIL import Image
    import typst, pypdf
    if kind not in ("comic", "storybook"):
        raise ValueError("kind is comic or storybook")
    d = _film(name); s = _shots(name); tm = _json(d / "timing.json", {}); sc = _json(d / "script.json", {})
    if not tm.get("lines") or tm.get("draft"):
        raise ValueError("voice the film first (the panels follow the spoken lines)")
    od = d / "build" / kind; shutil.rmtree(od, ignore_errors=True); (od / "frames").mkdir(parents=True)
    items = CM.panels(s, tm, sc); (od / "times.json").write_text(json.dumps([it["t"] for it in items]))
    url = "file://" + str(_player_page(name)) + "?rastercache=0&captions=0&bubbles=0"
    r = json.loads(_run(["node", "tools/comic_frames.mjs", url, str(od / "times.json"), str(od / "frames"), str(dsf)], timeout=1800)[-1])
    W, H = r["width"], r["height"]; frames = []
    aspect = CM.PANEL_ASPECT
    for i, (it, fr) in enumerate(zip(items, r["frames"])):
        box = CM.crop_box(W, H, fr["heads"], aspect); im = Image.open(fr["png"]).convert("RGB")
        k = im.width / W; im.crop([round(v * k) for v in box]).save(od / f"panel{i:03d}.png"); Path(fr["png"]).unlink()
        frames.append({"png": f"panel{i:03d}.png", "heads": fr["heads"], "crop": box})
    fdir = od / "fonts"; fdir.mkdir(); from fontTools.ttLib import TTFont
    f = TTFont(ROOT / "engine" / "fonts" / "PatrickHand-latin.woff2"); f.flavor = None; f.save(fdir / "PatrickHand.ttf")
    title = s.get("title") or name
    (od / f"{kind}.typ").write_text(CM.typst_source(kind, title, frames, items, "Patrick Hand", W, H))
    pdf = od / f"{kind}.pdf"
    typst.compile(str(od / f"{kind}.typ"), output=str(pdf), font_paths=[str(fdir)], root=str(od))
    typst.compile(str(od / f"{kind}.typ"), output=str(od / "page{p}.png"), font_paths=[str(fdir)], root=str(od), format="png", ppi=110)
    rd = pypdf.PdfReader(str(pdf)); text = " ".join((pg.extract_text() or "") for pg in rd.pages)
    norm = lambda x: re.sub(r"[^\w]+", " ", x.lower().replace("’", "'")).split()
    have = " ".join(norm(text)); missing = [it["line"] for it in items if it.get("text") and " ".join(norm(it["text"])) not in have]
    pics = sum(len(pg.images) for pg in rd.pages)
    shutil.rmtree(fdir, ignore_errors=True)
    return {"kind": kind, "pdf": str(pdf.relative_to(ROOT)), "pages": len(rd.pages), "panels": len(items), "pictures": pics,
            "lines": sum(1 for it in items if it.get("text")), "lines_missing_from_pdf": missing,
            "page_images": sorted(str(p.relative_to(ROOT)) for p in od.glob("page*.png")), "ok": not missing and pics == len(items)}


OPTS = [d for d in (os.environ.get("DBE_OPT"), "/opt", str(Path.home() / ".local" / "opt")) if d]   # where tools/setup.sh puts tools: /opt, or ~/.local/opt without root
GODOT = os.environ.get("DBE_GODOT") or next((p for p in [f"{d}/godot/godot" for d in OPTS] + [shutil.which("godot") or ""] if p and Path(p).exists()), None)


def _godot_render_check(name, od, sid, n, size):
    """Godot itself (headless import, then Movie Maker under Xvfb with software OpenGL) renders the first shot; three
    frames are compared with the player's own frames at the same moments (whole frames: set, shadows and characters)"""
    import numpy as np
    from PIL import Image
    from . import rparity as RP
    W, H = size; mv = od / "movie"; shutil.rmtree(mv, ignore_errors=True); mv.mkdir()
    r1 = subprocess.run([GODOT, "--headless", "--path", str(od), "--import"], capture_output=True, text=True, timeout=900)
    r2 = subprocess.run(["xvfb-run", "-a", "-s", f"-screen 0 {W}x{H}x24", GODOT, "--path", str(od), "--rendering-driver", "opengl3", "--write-movie", str(mv / "f.png"),
                         "--fixed-fps", "30", "--quit-after", str(n), "--resolution", f"{W}x{H}"], capture_output=True, text=True, timeout=1800)
    got = sorted(mv.glob("f*.png"))
    if r2.returncode or len(got) < n:
        return {"ok": False, "error": (r1.stderr + r2.stderr)[-400:], "frames": len(got)}
    pp = _player_page(name); s = _shots(name); sh = next(x for x in s["shots"] if x["id"] == sid); res = []
    for f in (0, n // 2, n - 1):
        ref = od / "check" / f"player_full_{f}.png"; ref.parent.mkdir(exist_ok=True)
        _run(["node", "tools/still.mjs", "file://" + str(pp) + "?rastercache=0&captions=0", str(sh["start"] + f / 30), "1", str(ref)], timeout=600)
        a = np.asarray(Image.open(ref).convert("RGB")).astype(float); b = np.asarray(Image.open(got[f]).convert("RGB").resize((a.shape[1], a.shape[0]))).astype(float)
        res.append({"frame": f, "mean_abs": round(float(np.abs(a - b).mean()), 2), "px_over_32": round(float((np.abs(a - b).max(-1) > 32).mean()), 4), "line_f1": round(RP.line_f1(ref, got[f]), 3)})
    ver = subprocess.run([GODOT, "--version", "--headless"], capture_output=True, text=True).stdout.strip().splitlines()[-1:]
    return {"engine": ver[0] if ver else "?", "frames": len(got), "compare": res, "ok": all(x["mean_abs"] < 4 and x["px_over_32"] < 0.03 and x["line_f1"] >= 0.9 for x in res)}


TCOMPOSER = os.environ.get("DBE_TCOMPOSER") or next((p for p in [f"{d}/opentoonz/bin/tcomposer" for d in OPTS] + [shutil.which("tcomposer") or ""] if p and Path(p).exists()), None)
TOONZ_STUFF = Path(os.environ.get("DBE_TOONZ_STUFF") or next((p for p in [f"{d}/opentoonz/stuff" for d in OPTS] + ["/usr/share/opentoonz/stuff"]   # the last: Fedora's opentoonz-data
                                                                if Path(p).is_dir()), "/opt/opentoonz/stuff"))


def _tcomposer_check(name, sh, od, n, size, skipped):
    """OpenToonz's renderer (tcomposer, under Xvfb: it is a Qt program) renders the scene; three frames are compared
    with the player's drawing of the same characters alone (a scratch copy of the shot without the cut-out cast,
    castonly=1 on a transparent page): coverage IoU of the alpha, and the mean colour difference where both draw"""
    import numpy as np
    from PIL import Image
    W, H = size; rd = od / "render"; shutil.rmtree(rd, ignore_errors=True); rd.mkdir()
    cmd = ["xvfb-run", "-a", TCOMPOSER, str(od / "scene.tnz"), "-o", str(rd / "f.png"), "-range", "1", str(n)]
    if TOONZ_STUFF.exists():
        cmd += ["-TOONZROOT", str(TOONZ_STUFF)]
    lib = Path(TCOMPOSER).resolve().parent.parent / "lib" / "opentoonz"   # its own libraries, wherever it was installed
    env = {**os.environ, "LD_LIBRARY_PATH": ":".join(x for x in (str(lib), os.environ.get("LD_LIBRARY_PATH", "")) if x)}
    r = subprocess.run(cmd, capture_output=True, text=True, timeout=1800, env=env)
    got = sorted(rd.glob("f*.png"))
    if len(got) < n:
        return {"ok": False, "frames": len(got), "error": (r.stdout + r.stderr)[-600:]}
    # the player's own drawing of the exported characters alone
    zz = f"zz-toonz-{name}"; zd = FILMS / zz; shutil.rmtree(zd, ignore_errors=True)
    shutil.copytree(FILMS / name, zd, ignore=shutil.ignore_patterns("build"))
    try:
        s = _json(zd / "shots.json"); drop = {x["cast"] for x in skipped}
        for x in s["shots"]:
            if x["id"] == sh["id"]:
                x["cast"] = [c for c in x["cast"] if (c.get("name") or Path(c["puppet"]).name) not in drop and _json(ROOT / c["puppet"]).get("template") == "level"]
        (zd / "shots.json").write_text(json.dumps(s, indent=1))
        pp = _player_page(zz); res = []
        for f in (0, n // 2, n - 1):
            ref = od / "render" / f"player_{f}.png"
            _run(["node", "tools/still.mjs", "file://" + str(pp) + "?rastercache=0&captions=0&castonly=1", str(sh["start"] + f / 30), "1", str(ref), "transparent"], timeout=600)
            a = np.asarray(Image.open(ref).convert("RGBA")).astype(float)
            b = np.asarray(Image.open(got[f]).convert("RGBA").resize((a.shape[1], a.shape[0]), Image.LANCZOS)).astype(float)
            ma, mb = a[..., 3] > 127, b[..., 3] > 127; both = ma & mb
            iou = float(both.sum() / max(1, (ma | mb).sum()))
            col = float(np.abs(a[..., :3] - b[..., :3])[both].mean()) if both.any() else 255.0
            res.append({"frame": f, "iou": round(iou, 4), "colour": round(col, 2), "player_px": int(ma.sum()), "tcomposer_px": int(mb.sum())})
    finally:
        shutil.rmtree(zd, ignore_errors=True)
    return {"frames": len(got), "size": list(Image.open(got[0]).size), "compare": res, "ok": all(x["iou"] >= 0.95 and x["colour"] <= 12 for x in res)}


@command("export.opentoonz", name=("string", "film"), shot=("string", "shot id"), render=("boolean", "render the scene with OpenToonz's tcomposer, if installed, and compare it with the player", True))
def export_opentoonz(name, shot, render=True):
    """A shot's drawn levels as an OpenToonz 1.8 scene (WP-34): build/opentoonz/<shot>/scene.tnz, a raster level per
    drawn character (one PNG per drawing), the xsheet exposing each frame's drawing as the bake has it, and each
    column's position and scale keyed on every frame. Cut-out characters are not OpenToonz levels and are listed as
    not exported. With render, OpenToonz's own renderer (tcomposer) renders it, and frames are compared with the
    player's drawing of the same characters alone."""
    from . import toonz_export as TZ
    s, sh, bdir, baked = _bake(name, shot); W, H = s.get("size", [1080, 1920]); fps = s.get("fps", 30); n = baked["frames"]
    od = FILMS / name / "build" / "opentoonz" / shot; shutil.rmtree(od, ignore_errors=True); od.mkdir(parents=True)
    levels, columns, skipped = [], [], []
    for ci, c in enumerate(baked["cast"]):
        pz = _json(c["puppet"]); src = next((x for x in sh["cast"] if (ROOT / x["puppet"]).resolve() == Path(c["puppet"]).resolve()), {})
        if pz.get("template") != "level":
            skipped.append({"cast": c.get("name") or Path(c["puppet"]).name, "why": "a cut-out puppet, not an OpenToonz level"}); continue
        lvl = f"L{len(levels) + 1}_{re.sub(r'[^A-Za-z0-9]', '', pz.get('name') or 'level')[:20]}"
        (od / lvl).mkdir(); shapes = pz["swaps"]["level"]["shapes"]; idx = {}
        for k, did in enumerate(sorted(shapes), 1):
            TZ.drawing_png(pz, shapes[did], ROOT).save(od / lvl / f"{lvl}.{k:04d}.png", dpi=(TZ.DPI, TZ.DPI)); idx[did] = k
        levels.append({"id": len(levels) + 1, "name": lvl, "path": f"$scenefolder/{lvl}/{lvl}..png"})
        columns.append({"level": len(levels), **TZ.column_from_bake(c["frames"], pz, (W, H), idx)})
    if not columns:
        raise ValueError(f"shot {shot} has no drawn levels to export (OpenToonz scenes carry frame-by-frame levels)")
    (od / "scene.tnz").write_text(TZ.scene((W, H), n, fps, levels, columns))
    TZ.project(od)
    out = {"scene": str((od / "scene.tnz").relative_to(ROOT)), "levels": [l["name"] for l in levels], "frames": n, "not_exported": skipped}
    if render and TCOMPOSER:
        out["tcomposer"] = _tcomposer_check(name, sh, od, n, (W, H), skipped)
    elif render:
        out["tcomposer"] = "not installed (bash tools/setup.sh opentoonz)"
    return out


SAPIENS = ("sapiens_pose_0.3b.pt2", "https://huggingface.co/facebook/sapiens-pose-0.3b-torchscript/resolve/main/sapiens_0.3b_goliath_best_goliath_AP_573_torchscript.pt2",
           "59ea239bfb217caf76cbeac1836460ef8f9ab5f39aeb22f2577373b62fa25edc")


OPENPOSE = ("openpose_body_pose_model.pth", "https://huggingface.co/lllyasviel/Annotators/resolve/982e7edaec38759d914a963c48c4726685de7d96/body_pose_model.pth",
            "25a948c16078b0f08e236bda51a385d855ef4c153598947c28c0d47ed94bb746")


def _fetched_model(spec):
    """a model file (name, url, sha256) fetched once into the models folder and checked by sha256"""
    import hashlib
    import urllib.request
    from . import actout as AO
    p = AO.MODELS / spec[0]
    if not p.exists():
        AO.MODELS.mkdir(parents=True, exist_ok=True); urllib.request.urlretrieve(spec[1], str(p) + ".part"); Path(str(p) + ".part").rename(p)
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for b in iter(lambda: f.read(1 << 22), b""):
            h.update(b)
    if h.hexdigest() != spec[2]:
        raise ValueError(f"{p} does not match its sha256")
    return p


def _sapiens_model():
    """Sapiens pose 0.3B (Meta, CC BY-NC 4.0, 1.3 GB)"""
    return _fetched_model(SAPIENS)


@command("pose.benchmark", detectors=("array", "mediapipe | rtmpose | yolo11 | sapiens | openpose (default: all)", None), limit=("integer", "images (of the 80)", 80))
def pose_benchmark(detectors=None, limit=80):
    """Pose detectors compared by measured accuracy (WP-12): MediaPipe Pose Landmarker (what act-out uses), RTMPose
    (rtmlib, balanced: YOLOX detector + RTMPose-m, ONNX on the CPU) and Ultralytics YOLO11m-pose, on 80 single-person
    COCO val2017 photos (tests/posebench) scored by COCO's keypoint similarity (OKS) per image; Sapiens 0.3B top-down on
    rtmlib's person boxes; OpenPose (CMU's body model, bottom-up, the PyTorch port in vendor/openpose, four scales).
    Writes out/posebench/result.json."""
    import urllib.request
    from . import posebench as PB
    spec = _json(ROOT / "tests" / "posebench" / "coco-val2017-80.json"); spec["items"] = spec["items"][:limit]
    from . import actout as AO
    img = AO.MODELS.parent / "coco-val2017"; img.mkdir(parents=True, exist_ok=True)
    for it in spec["items"]:
        if not (img / it["file"]).exists():
            urllib.request.urlretrieve(it["url"], img / it["file"])
    od = ROOT / "out" / "posebench"; od.mkdir(parents=True, exist_ok=True); (od / "bench.json").write_text(json.dumps(spec))
    make = {"mediapipe": lambda: PB.mediapipe_detector(AO.model_path("pose")), "rtmpose": lambda: PB.rtmlib_detector("balanced"),
            "yolo11": lambda: PB.yolo_detector(str(AO.MODELS / "yolo11m-pose.pt")),
            "sapiens": lambda: PB.sapiens_detector(_sapiens_model()), "openpose": lambda: PB.openpose_detector(_fetched_model(OPENPOSE))}
    names = detectors or list(make)
    res = PB.run(od / "bench.json", img, {n: make[n] for n in names})
    out = {"images": len(spec["items"]), "results": res, "ranking": sorted([n for n in res if "mean_oks" in res[n]], key=lambda n: -res[n]["mean_oks"])}
    (od / "result.json").write_text(json.dumps(out, indent=1))
    return out


@command("puppet.mirror", puppet=("string", "puppet file"), part=("string", "the part drawn, e.g. arm_L"), to=("string", "the part to make (default: the other side's name)", ""),
         axis=("number", "x of the centre line (default: the middle of the parent's drawing)", None), replace=("boolean", "redraw an existing part from the mirror", False),
         out=("string", "write the puppet here (default: in place)", ""))
def puppet_mirror(puppet, part, to="", axis=None, replace=False, out=""):
    """Mirror tool (WP-18): a part drawn on one side, with what hangs from it, copied to the other side across the
    body's centre line (raster drawings flipped, vector paths reflected, pivots reflected, joint limits swapped)."""
    from . import mirror as MI
    pz, rep = MI.mirror_part(_json(ROOT / puppet), part, to or None, axis, replace)
    dst = ROOT / (out or puppet); dst.parent.mkdir(parents=True, exist_ok=True); dst.write_text(json.dumps(pz))
    return {"puppet": str(dst.relative_to(ROOT)), **rep, "lint": puppet_lint(str(dst.relative_to(ROOT)))["issues"]}


@command("puppet.auto_weights", puppet=("string", "puppet file"), part=("string", "the part carrying the drawing (an image stroke)"),
         chain=("array", "the parts it should bend with, starting with that part, e.g. [thigh_L, shin_L, foot_L]"),
         out=("string", "write the new puppet here (default: beside it, .skinned.puppet.json)", ""), step=("number", "mesh cell size, artboard units", 12))
def puppet_auto_weights(puppet, part, chain, out="", step=12):
    """Automatic vertex weights from bone influence (WP-11): a drawing made in one piece over several parts becomes a
    skinned mesh stroke (format v0.5) that bends at their joints: a grid of triangles over its ink, each vertex weighted
    by its distance to the parts' bones and the weights diffused over the mesh. Renders in the SVG player like any mesh
    stroke (the other exporters skip mesh strokes)."""
    from . import autoweights as AW
    pz = _json(ROOT / puppet); pz, rep = AW.auto_mesh(pz, part, list(chain), step=float(step))
    dst = ROOT / (out or str(Path(puppet).with_suffix("")).replace(".puppet", "") + ".skinned.puppet.json")
    dst.parent.mkdir(parents=True, exist_ok=True); dst.write_text(json.dumps(pz))
    return {"puppet": str(dst.relative_to(ROOT)), "meshes": rep}


@command("film.continuity", name=("string", "film"))
def film_continuity(name):
    """Continuity checks and shot sizes (WP-19) on the baked frames: the 180-degree rule (two characters keep their
    left-right order across a cut), screen direction (a travelling character keeps going the same way), eyelines in
    shot / reverse-shot pairs (each looks towards where the other stands), and each shot's size (ELS, LS, FS, MLS, MS,
    MCU, CU, ECU) from how much of its main character the frame shows. A shot with "cross_line": true crosses on
    purpose. Writes build/continuity.json."""
    from . import continuity as CT
    s = _shots(name); W, H = s.get("size", [1080, 1920]); sums = []
    puppets = {c["puppet"]: _json(ROOT / c["puppet"]) for sh in s["shots"] for c in sh.get("cast", [])}
    for sh in s["shots"]:
        if not sh.get("cast"):
            sums.append({}); continue
        _, _, _, baked = _bake(name, sh["id"])
        sums.append(CT.summary(sh, baked, puppets, (W, H)))
    issues, rows = CT.check(s["shots"], sums, (W, H))
    out = {"film": name, "ok": not issues, "issues": issues, "shots": rows, "sizes": dict(CT.SIZES)}
    (FILMS / name / "build").mkdir(exist_ok=True); (FILMS / name / "build" / "continuity.json").write_text(json.dumps(out, indent=1))
    return out


@command("export.usd", name=("string", "film"), shot=("string", "shot id"), ascii=("boolean", "write .usda (text) rather than .usdc", True))
def export_usd(name, shot, ascii=True):
    """A shot as an OpenUSD stage (WP-42, dbe/usdexport.py): the baked animation every renderer draws, each part an Xform
    sampled every frame (the camera folded in), its drawing as meshes and curves (raster drawings as textured quads),
    swap drawings shown only on their frames, an orthographic camera framing the shot. Written to
    build/shots/<shot>.usda (or .usdc) beside its textures; opens in usdview, Blender, Houdini, Maya or Omniverse.
    Checked with OpenUSD's own compliance checker."""
    from pxr import Usd, UsdValidation
    from . import usdexport as UX
    s, sh, bdir, baked = _bake(name, shot); W, H = s.get("size", [1080, 1920])
    out = bdir / f"{shot}.{'usda' if ascii else 'usdc'}"; out.unlink(missing_ok=True)
    summ = UX.to_usd(baked, (W, H), out)
    # OpenUSD's validation framework, every validator it ships (stage metadata, schema types, shading, ...)
    reg = UsdValidation.ValidationRegistry(); vals = reg.GetOrLoadAllValidators()
    errs = UsdValidation.ValidationContext(vals).Validate(Usd.Stage.Open(str(out)))
    issues = [{"validator": e.GetValidator().GetMetadata().name if e.GetValidator() else "", "type": str(e.GetType()).split(".")[-1], "message": e.GetMessage()[:200]} for e in errs]
    return {"usd": str(out.relative_to(ROOT)), **summ, "validation": {"validators": len(vals), "errors": [i for i in issues if i["type"] == "Error"], "warnings": [i for i in issues if i["type"] != "Error"][:10]}}


@command("export.blend", name=("string", "film"), shot=("string", "shot id"), background=("boolean", "the set's first frame as a background plane", True))
def export_blend(name, shot, background=True):
    """A shot as a Blender project (WP-14): the Grease Pencil scene the grease-pencil renderer builds (every frame a
    keyframe, strokes in z order with their fills and ink, the orthographic camera, EEVEE settings), saved as
    build/shots/<shot>.blend before rendering, with the set's first frame as a background plane. Checked by opening it
    again in Blender and rendering one frame, which must match the renderer's own frame."""
    from . import exporters as X, rparity as RP
    if not BLENDER:
        raise RuntimeError("Blender not found; set DBE_BLENDER (bash tools/setup.sh blender)")
    _require_valid(name)
    s, sh, bdir, baked = _bake(name, shot); W, H = s.get("size", [1080, 1920])
    why = RP.refusal("grease-pencil", sh, [_json(c["puppet"]) for c in baked["cast"]])
    if why:
        raise ValueError(f"shot {shot}: {why}")
    gpj = bdir / f"{shot}.gp.json"; gpj.write_text(json.dumps(X.to_gp_frames(baked, (W, H), toon=(sh.get("style") or {}).get("toon"))))
    bg = str(_bg_png(name, sh, bdir)) if background else "-"
    out = bdir / f"{shot}.blend"; out.unlink(missing_ok=True)
    env = {**os.environ, "DBE_GP_SAVE": str(out), "DBE_GP_SAVE_ONLY": "1"}
    r = subprocess.run([BLENDER, "-b", "--factory-startup", "--gpu-backend", "vulkan", "--python", "dbe/blender_gp.py", "--", str(gpj), str(bdir / f"{shot}_blend_"), bg, "0.5"],
                       cwd=ROOT, env=env, capture_output=True, text=True, timeout=7200)
    if r.returncode or not out.exists():
        raise RuntimeError(f"blender: {(r.stderr or r.stdout)[-400:]}")
    return {"blend": str(out.relative_to(ROOT)), "bytes": out.stat().st_size, "frames": len(baked["cast"][0]["frames"]), "background": bg != "-"}


@command("export.svg", name=("string", "film"), time=("number", "a frame at this film time (seconds)", None),
         start=("number", "or an animated SVG from here", None), end=("number", "to here", None), fps=("integer", "frames per second of the animated SVG", 12))
def export_svg(name, time=None, start=None, end=None, fps=12):
    """A film frame as a standalone SVG, or a stretch of the film as one animated SVG (WP-23): the player's own markup
    with its images and the fonts its text uses embedded (out/svg/<film>/). The animated SVG shows each frame for
    1/fps s and loops (SMIL), ids kept apart per frame, repeated images stored once; it plays in browsers without
    script. Long stretches make large files: it suits stickers and loops, not whole films."""
    od = ROOT / "out" / "svg" / name; od.mkdir(parents=True, exist_ok=True); pp = _player_page(name)
    url = "file://" + str(pp) + "?rastercache=0&captions=0"
    if time is not None:
        o = od / f"frame_{float(time):.3f}.svg"; r = _run(["node", "tools/svg_frame.mjs", url, str(o), "still", str(time)], timeout=600)
    elif start is not None and end is not None:
        o = od / f"anim_{float(start):.2f}-{float(end):.2f}_{fps}fps.svg"; r = _run(["node", "tools/svg_frame.mjs", url, str(o), "anim", str(start), str(end), str(fps)], timeout=3600)
    else:
        raise ValueError("give time, or start and end")
    return {**json.loads(r[-1]), "file": str(o.relative_to(ROOT))}


@command("film.match_cut", name=("string", "film"), shot=("string", "the incoming shot (the cut into it is matched)"))
def film_match_cut(name, shot):
    """A match cut (WP-15): the incoming shot's camera set so its main character lands where the outgoing shot's main
    character was at the cut, at the same size (the box from the head to the feet): zoom = the outgoing height over the
    incoming one, centre and feet aligned. Written as a held camera key at the incoming shot's start in shots.json; a
    zoom under 1 (framing wider than the set) is applied but reported."""
    from . import continuity as CT
    raw = _json(FILMS / name / "shots.json"); s = _shots(name); W, H = s.get("size", [1080, 1920])
    ids = [x["id"] for x in s["shots"]]; i = ids.index(shot)
    if i == 0:
        raise ValueError("the first shot has no cut into it")
    a, b = s["shots"][i - 1], s["shots"][i]
    _, _, _, ba = _bake(name, a["id"])
    def box_a():
        best = None
        for c, k in zip(a["cast"], ba["cast"]):
            fr = k["frames"][-1]; pz = _json(ROOT / c["puppet"]); h = (pz.get("ground", pz["artboard"][1]) - CT.rest_top(pz)) * fr["s"]
            if best is None or h > best[2]:
                best = (fr["x"], fr["y"], h, c.get("name") or pz.get("name"))
        return best
    def place_at(pl, t):
        if isinstance(pl, dict):
            return pl.get("x", W / 2), pl.get("y", H * 0.8), pl.get("s", 1)
        keys = sorted(pl, key=lambda k: k[0]); k0 = keys[0]
        for (t0, v0), (t1, v1) in zip(keys, keys[1:]):
            if t0 <= t <= t1:
                u = (t - t0) / max(1e-9, t1 - t0); return tuple(v0.get(q, 1 if q == "s" else 0) + (v1.get(q, 1 if q == "s" else 0) - v0.get(q, 1 if q == "s" else 0)) * u for q in ("x", "y", "s"))
        v = (k0 if t < k0[0] else keys[-1])[1]; return v.get("x", W / 2), v.get("y", H * 0.8), v.get("s", 1)
    xa, ya, ha, who_a = box_a()
    cands = []
    for c in b.get("cast", []):
        pz = _json(ROOT / c["puppet"]); x, y, sc = place_at(c.get("place") or {}, b["start"]); h = (pz.get("ground", pz["artboard"][1]) - CT.rest_top(pz)) * sc
        cands.append((h, x, y, c.get("name") or pz.get("name")))
    if not cands:
        raise ValueError(f"shot {shot} has no character to match")
    hb, xb, yb, who_b = max(cands)
    z = ha / hb; cx = xb - (xa - W / 2) / z; cy = yb - (ya - H / 2) / z
    rs = next(x for x in raw["shots"] if x["id"] == shot); rs["camera"] = [[rs["start"], [round(cx, 2), round(cy, 2), round(z, 4)]]]; rs.pop("camera_auto", None)
    (FILMS / name / "shots.json").write_text(json.dumps(raw, indent=1))
    return {"shot": shot, "from": a["id"], "outgoing": {"who": who_a, "x": round(xa, 1), "feet": round(ya, 1), "height": round(ha, 1)},
            "incoming": {"who": who_b, "x": round(xb, 1), "feet": round(yb, 1), "height": round(hb, 1)}, "camera": [round(cx, 2), round(cy, 2), round(z, 4)],
            **({"warning": "zoom under 1: the frame shows more than the set was drawn for"} if z < 1 else {})}


@command("export.sprites", puppet=("string", "puppet file"), clips=("array", "clip names (default: every clip in its library)", None),
         fps=("integer", "frames per second of the sheet", 12), scale=("number", "character scale in the frame", 1.0))
def export_sprites(puppet, clips=None, fps=12, scale=1.0):
    """A character's clips as a packed sprite sheet (WP-30): out/sprites/<id>/<id>.png, the atlas in TexturePacker's
    JSON hash layout with an animations map (Phaser, PixiJS, Cocos, Defold, Unity through its TexturePacker importer)
    and a Godot 4 SpriteFrames resource (.tres). Each frame is the character alone, drawn by the player and trimmed;
    the pivot is its ground point."""
    from . import sprites as SP
    from PIL import Image
    pz = _json(ROOT / puppet); lib = _json(ROOT / "puppet" / "clips" / f"{pz.get('template', 'humanoid')}.json", {"clips": {}})["clips"]
    lib = {**lib, **(pz.get("clips") or {})}
    names = clips or list(lib)
    unknown = [c for c in names if c not in lib]
    if unknown:
        raise KeyError(f"no clip {unknown} for this puppet (have {', '.join(lib)})")
    cid = re.sub(r"[^a-z0-9_-]", "-", Path(puppet).name.split(".")[0].lower())
    film = f"zz-sprites-{cid}"; d_ = FILMS / film; shutil.rmtree(d_, ignore_errors=True); d_.mkdir(parents=True)
    out = ROOT / "out" / "sprites" / cid; shutil.rmtree(out, ignore_errors=True); out.mkdir(parents=True)
    try:
        shots, t0 = [], 0.0
        for i, c in enumerate(names):
            dur = float(lib[c].get("duration") or 1.0)
            shots.append({"id": f"s{i + 1}", "renderer": "svg", "set": "plain", "start": round(t0, 3), "end": round(t0 + dur, 3), "bubbles": False,
                          "cast": [{"puppet": puppet, "place": {"x": 540, "y": 1500, "s": scale}, "timeline": {"blink": False, "clips": [{"clip": c, "start": round(t0, 3), "fadeIn": 0}]}}]})
            t0 += dur
        (d_ / "shots.json").write_text(json.dumps({"title": "sprites", "size": [1080, 1920], "fps": 30, "shots": shots}))
        (d_ / "script.json").write_text('{"lines": []}'); (d_ / "timing.json").write_text('{"lines": []}')
        pp = _player_page(film); frames = []
        for i, c in enumerate(names):
            dur = float(lib[c].get("duration") or 1.0); n = max(1, int(round(dur * fps)))
            ts = [f"{k / fps:.4f}" for k in range(n)]
            _run(["node", "tools/stills.mjs", str(pp), f"shot=s{i + 1}&castonly=1&captions=0", str(d_ / f"c{i}")] + ts, timeout=900)
            frames += [(c, k, Image.open(d_ / f"c{i}_{t}.png").convert("RGBA")) for k, t in enumerate(ts)]
        atlas = SP.build(frames, out, cid, (1080, 1920), (540, 1500), fps)
    finally:
        shutil.rmtree(d_, ignore_errors=True)
    return {"sheet": str((out / f"{cid}.png").relative_to(ROOT)), "atlas": str((out / f"{cid}.json").relative_to(ROOT)), "godot": str((out / f"{cid}.tres").relative_to(ROOT)),
            "size": atlas["meta"]["size"], "frames": len(atlas["frames"]), "animations": {k: len(v) for k, v in atlas["animations"].items()}}


@command("export.godot", name=("string", "film"), shots=("array", "shot ids (default: every shot)", None), check=("boolean", "compose three frames from the exported scene and compare them with the player's", True))
def export_godot(name, shots=None, check=True):
    """A film as a Godot 4 project (WP-30): build/godot/ with project.godot, main.tscn (plays the shots in order with
    the sound) and a scene per shot: the set as a plate, every part and swap drawing as a Sprite2D (its drawing as an
    SVG) animated by an AnimationPlayer from the bake (transform, visibility and layer order per frame). Open the
    folder in Godot 4.5. With check, the exported tracks are read back by an independent reader of the .tscn and three
    frames are composed from them and compared with the player's own frame (the characters' coverage, IoU)."""
    from . import godot_export as GX, rparity as RP
    d = _film(name); s = _shots(name); W, H = s.get("size", [1080, 1920])
    od = d / "build" / "godot"; shutil.rmtree(od, ignore_errors=True); (od / "plates").mkdir(parents=True)
    ids = shots or [sh["id"] for sh in s["shots"]]; rows = []
    for sid in ids:
        _, sh, bdir, baked = _bake(name, sid)
        # the set as a video (its drifting life and each character's moving ground shadow, drawn by the player per frame),
        # in Ogg Theora, which Godot plays natively; a still plate only if the video cannot be made
        try:
            sv = _set_video(name, sh, bdir)
            _run(["ffmpeg", "-v", "error", "-y", "-i", str(sv), "-c:v", "libtheora", "-q:v", "9", "-an", str(od / "plates" / f"{sid}.ogv")])
            plate = f"{sid}.ogv"
        except Exception:
            _run(["node", "tools/still.mjs", "file://" + str(_player_page(name)) + f"?bg=1&rastercache=0&captions=0", str(sh["start"]), "1", str(od / "plates" / f"{sid}.png")], timeout=600)
            plate = f"{sid}.png"
        path, nd, nt = GX.shot_scene(baked, (W, H), plate, od, sid)
        rows.append({"shot": sid, "scene": str(path.relative_to(ROOT)), "drawings": nd, "tracks": nt, "frames": baked["frames"]})
    mix = d / "build" / "mix.wav"
    if mix.exists():
        _run(["ffmpeg", "-v", "error", "-y", "-i", str(mix), "-c:a", "libvorbis", "-q:a", "5", str(od / "sound.ogg")])
    GX.project(od, s.get("title") or name, (W, H), ids, mix.exists())
    out = {"project": str(od.relative_to(ROOT)), "shots": rows, "sound": mix.exists(), "opens_in": "Godot 4.5"}
    if check and GODOT and shutil.which("xvfb-run"):   # the real engine: import the project, render the first shot with Movie Maker, compare
        out["godot_render"] = _godot_render_check(name, od, ids[0], next(r["frames"] for r in rows if r["shot"] == ids[0]), (W, H))
    if check:
        sid = ids[0]; sc_ = GX.read_scene(od / "shots" / f"{sid}.tscn"); sh = next(x for x in s["shots"] if x["id"] == sid); n = rows[0]["frames"]
        ious = []
        for f in (0, n // 2, n - 1):
            st = GX.state_at(sc_, f)
            body = "".join(f'<g transform="matrix({" ".join(str(v) for v in nd_["transform"])})">' + re.sub(r"^<svg[^>]*>|</svg>$", "", (od / nd_["texture"]).read_text()) + "</g>"
                           for _, nd_ in sorted(st.items(), key=lambda kv: kv[1]["z"]) if nd_["visible"] and nd_["texture"].endswith(".svg"))   # the drawings (not the set plate)
            comp = od / "check" / f"godot_{f}.html"; comp.parent.mkdir(exist_ok=True)
            comp.write_text(f'<html><body style="margin:0;background:transparent"><svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}">{body}</svg></body></html>')
            _run(["node", "-e", "const {chromium}=require('playwright');(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:%d,height:%d}});await p.goto(process.argv[1]);await p.screenshot({path:process.argv[2],omitBackground:true});await b.close();})()" % (W, H),
                  "file://" + str(comp), str(comp.with_suffix(".png"))], timeout=300)
            t = sh["start"] + f / s.get("fps", 30)
            _run(["node", "tools/still.mjs", "file://" + str(_player_page(name)) + "?rastercache=0&captions=0&bubbles=0&castonly=1", str(t), "1", str(od / "check" / f"player_{f}.png"), "transparent"], timeout=600)
            ga, pl = comp.with_suffix(".png"), od / "check" / f"player_{f}.png"   # judged as renderer parity judges Synfig and Lottie (WP-14)
            ious.append({"silhouette_iou": round(RP.iou(RP.silhouette(pl), RP.silhouette(ga)), 3), "line_f1": round(RP.line_f1(pl, ga), 3), "colour_diff": round(RP.colour_diff(RP.rgba(pl), RP.rgba(ga)), 1)})
        sc_min = min(max(x["silhouette_iou"], x["line_f1"]) for x in ious)
        out["check"] = {"shot": sid, "frames": [0, n // 2, n - 1], "measures": ious, "score": sc_min,
                        "ok": sc_min >= 0.93 and max(x["colour_diff"] for x in ious) <= 24}   # stricter than renderer parity's 0.85
    return out


# ---------------- team roles and permissions (WP-39) ----------------
@command("team.roles")
def team_roles():
    """The roles (team/roles.json): what each may run beyond the read commands, and which commands sign things off."""
    from . import team as TM
    r = TM.roles(); return {"roles": {k: {"about": v.get("about"), "commands": v.get("commands"), "never": v.get("never", []), "approve": v.get("approve", [])} for k, v in r["roles"].items()},
                            "approve": r.get("approve", []), "everyone_reads": TM.READ}


@command("team.people")
def team_people():
    """The people and agent sessions (team/people.json) with their roles, and what is assigned to and locked by each."""
    from . import team as TM
    st = TM.state()
    return {"people": {pid: {**p, "assigned": [t for t, who in st["assignments"].items() if pid in who], "locks": [t for t, l in st["locks"].items() if l["by"] == pid]}
                       for pid, p in TM.people().items()}, "single_user": not TM.people()}


@command("team.whoami")
def team_whoami():
    """Who this session acts as (DBE_AS, or the X-DBE-As header over HTTP) and its role."""
    from . import ACTOR, team as TM
    return ACTOR.get() or TM.actor()


@command("team.add", id=("string", "person or agent-session id"), name=("string", "display name"), roles=("array", "their roles (the first is the default)"),
         kind=("string", "person | agent", "person"))
def team_add(id, name, roles, kind="person"):
    """Add or update a person or an agent session (team/people.json). Each agent session gets its own id and role."""
    from . import team as TM
    known = TM.roles()["roles"]; bad = [r for r in roles if r not in known]
    if bad or not roles:
        raise ValueError(f"unknown roles {bad} (have {', '.join(known)})")
    f = TM.team_dir() / "people.json"; d = _json(f, {"note": "WP-39: people and agent sessions with their roles", "people": {}})
    d["people"][id] = {"name": name, "roles": roles, "kind": kind}; TM.team_dir().mkdir(parents=True, exist_ok=True); f.write_text(json.dumps(d, indent=1) + "\n")
    return {"added": id, **d["people"][id]}


def _team_target(kind, id):
    if kind not in ("film", "character"):
        raise ValueError("kind is film or character")
    if kind == "film":
        _film(id)
    else:
        cast = {e["id"]: e["path"] for e in _json(ROOT / "cast" / "index.json", {"puppets": []})["puppets"]}
        id = cast.get(id, id)
        if not (ROOT / id).exists():
            raise FileNotFoundError(f"no character {id} (a cast id or a .puppet.json path)")
    return f"{kind}:{id}"


@command("team.assign", kind=("string", "film | character"), id=("string", "film name, or a cast id or puppet path"), people=("array", "who it is assigned to"))
def team_assign(kind, id, people):
    """Assign a film or a character to people: only they (and the owner and directors) may then change it."""
    from . import team as TM
    t = _team_target(kind, id); missing = [p for p in people if p not in TM.people()]
    if missing:
        raise ValueError(f"not in team/people.json: {missing}")
    st = TM.state(); st["assignments"][t] = people; TM.save_state(st)
    return {"target": t, "assigned": people}


@command("team.unassign", kind=("string", "film | character"), id=("string", "film name, or a cast id or puppet path"))
def team_unassign(kind, id):
    """Clear a film's or character's assignment."""
    from . import team as TM
    t = _team_target(kind, id); st = TM.state(); st["assignments"].pop(t, None); TM.save_state(st)
    return {"target": t, "assigned": []}


@command("team.lock", kind=("string", "film | character"), id=("string", "film name, or a cast id or puppet path"), why=("string", "what you are doing", ""))
def team_lock(kind, id, why=""):
    """Lock a film or character while you work on it: nobody else may change it until you unlock it."""
    from . import ACTOR, team as TM
    who = ACTOR.get() or TM.actor(); t = _team_target(kind, id); st = TM.state(); lk = st["locks"].get(t)
    if lk and lk["by"] != who["id"]:
        raise PermissionError(f"{t} is already locked by {lk['by']}")
    st["locks"][t] = {"by": who["id"], "at": _now_iso(), "why": why}; TM.save_state(st)
    return {"target": t, "locked_by": who["id"]}


@command("team.unlock", kind=("string", "film | character"), id=("string", "film name, or a cast id or puppet path"))
def team_unlock(kind, id):
    """Unlock a film or character (your own lock; the owner may break anyone's)."""
    from . import ACTOR, team as TM
    who = ACTOR.get() or TM.actor(); t = _team_target(kind, id); st = TM.state(); lk = st["locks"].get(t)
    if lk and lk["by"] != who["id"] and who["role"] != "owner":
        raise PermissionError(f"{t} is locked by {lk['by']}; only they or the owner can unlock it")
    st["locks"].pop(t, None); TM.save_state(st)
    return {"target": t, "unlocked": True, **({"broke_lock_of": lk["by"]} if lk and lk["by"] != who["id"] else {})}


@command("team.audit", who=("string", "only this person or session", ""), target=("string", "only this target (film:<name>, character:<path>)", ""),
         result=("string", "ok | failed | refused", ""), last=("integer", "the most recent n entries", 50))
def team_audit(who="", target="", result="", last=50):
    """The audit log: every change, by whom, in which role, through which door (cli, http, mcp), with its target, and
    every refusal with its reason."""
    from . import team as TM
    f = TM.team_dir() / "audit.jsonl"; rows = [json.loads(l) for l in f.read_text().splitlines() if l.strip()] if f.exists() else []
    rows = [r for r in rows if (not who or r["who"] == who) and (not target or r.get("target") == target) and (not result or r["result"] == result)]
    return {"entries": rows[-last:], "total": len(rows)}


def _now_iso():
    import datetime as dt
    return dt.datetime.now(dt.timezone.utc).isoformat(timespec="seconds")


# ---------------- the director's desk (WP-21) ----------------
@command("desk.say", name=("string", "film"), text=("string", "notes in plain English: line text, timing, camera, set, music, acting, 'show me'"),
         apply=("boolean", "make the changes (false: only say what would be done)", True))
def desk_say(name, text, apply=True):
    """The director's desk (WP-21): plain-English notes on a film, each sentence routed to the command that makes the
    change (dbe/desk.py: a line's words, a shot held or shortened, the camera closer or wider, a shot's set, the
    music's tempo, acting directions, a storyboard and animatic to look at). Every routed command runs as the person
    or agent at the desk, so their role decides what goes through; the first refusal stops the rest. Each exchange
    is kept in films/<name>/desk.json."""
    from . import desk as DK, ACTOR, call as CALL
    d = _film(name)
    film = {"name": name, "script": _json(d / "script.json", {}), "shots": _shots(name, resolve=False), "score": _json(d / "score.json", {})}
    plan = DK.route(text, film); who = ACTOR.get(); as_ = f"{who['id']}:{who['role']}" if who and who["id"] != "local" else None
    ran = []
    if apply:
        for cmd, args in plan["calls"]:
            try:
                res = CALL(cmd, args, as_=as_, via=(who or {}).get("via", "cli"))
                ran.append({"command": cmd, "result": "ok", **({"summary": {k: res[k] for k in list(res)[:3]}} if isinstance(res, dict) else {})})
            except PermissionError as e:
                ran.append({"command": cmd, "result": "refused", "why": str(e)}); break
            except Exception as e:
                ran.append({"command": cmd, "result": "failed", "why": str(e)[:300]}); break
        left = [c for c, _ in plan["calls"][len(ran):]]
    else:
        left = [c for c, _ in plan["calls"]]
    entry = {"at": _now_iso(), "who": (who or {}).get("id", "local"), "role": (who or {}).get("role", "owner"), "said": text,
             "understood": [{k: e[k] for k in ("kind", "what")} for e in plan["edits"]], "not_understood": plan["not_understood"], "ran": ran, "not_run": left, **({"dry_run": True} if not apply else {})}
    log = _json(d / "desk.json", {"note": "WP-21: the director's desk: what was said, understood and run", "exchanges": []}); log["exchanges"].append(entry)
    (d / "desk.json").write_text(json.dumps(log, indent=1, ensure_ascii=False) + "\n")
    out = {**entry, "applied": apply and not left}
    if (d / "build" / "storyboard" / "strip.png").exists():
        out["storyboard"] = str((d / "build" / "storyboard" / "strip.png").relative_to(ROOT))
    if (d / "build" / "animatic.mp4").exists():
        out["animatic"] = str((d / "build" / "animatic.mp4").relative_to(ROOT))
    return out


# ---------------- render farm (WP-38) ----------------
@command("farm.render", name=("string", "film"), workers=("integer", "worker processes (each stands for one machine)", 3),
         pin=("boolean", "pin each worker to its own CPU core, as one machine each (taskset)", True),
         cache=("boolean", "use and fill the shared cache by content hash (out/farm/cache)", True),
         fresh=("boolean", "render every shot again (ignore earlier renders in the film's build)", False),
         assemble=("boolean", "then run film.render to join, mix and check (every shot is fresh by then)", True))
def farm_render(name, workers=3, pin=True, cache=True, fresh=False, assemble=True):
    """Render a film on a farm (WP-38): every shot not already rendered or in the shared cache becomes a task, the
    dearest by render.estimate first; `workers` processes claim tasks from the queue (an atomic rename, so no shot is
    taken twice), render them with one browser each and put them in the cache by content hash; then film.render
    assembles. Returns where each shot came from, each worker's busy time, and the wall time of the shots and of the
    whole run."""
    from . import farm as FM
    import time as _t
    _require_valid(name)
    d = _film(name); s = _shots(name); t0 = _t.time(); rows, tasks = [], []
    est = {x["shot"]: x["seconds"] for x in (render_estimate(name).get("shots") or [])} if workers > 0 else {}
    for sh in s["shots"]:
        mp4 = d / "build" / "shots" / f"{sh['id']}.mp4"; hf = d / "build" / "shots" / f"{sh['id']}.hash"; mp4.parent.mkdir(parents=True, exist_ok=True)
        key = _shot_hash(name, sh, s)
        if fresh:
            mp4.unlink(missing_ok=True); hf.unlink(missing_ok=True)
        if mp4.exists() and hf.exists() and hf.read_text().strip() == key:
            rows.append({"shot": sh["id"], "from": "already rendered"}); continue
        if cache and FM.cache_get(key, mp4):
            hf.write_text(key); rows.append({"shot": sh["id"], "from": "cache"}); continue
        tasks.append({"film": name, "shot": sh["id"], "key": key, "cost": est.get(sh["id"], sh["end"] - sh["start"]), "frames": round((sh["end"] - sh["start"]) * s.get("fps", 30))})
    run = f"{name}-{int(t0)}"; q = FM.make_queue(run, tasks)
    _player_page(name)   # written once before the workers start
    ncpu = os.cpu_count() or 1; procs = []
    env = {**os.environ, "DBE_RENDER_WORKERS": "1", "DBE_FARM_CACHE": "1" if cache else "0"}
    if pin:   # SwiftShader pins its threads to core 0 up whatever the process may use: keep them on the worker's own core
        so = ROOT / "out" / "farm" / "keep_affinity.so"; src = ROOT / "tools" / "farm" / "keep_affinity.c"
        if not so.exists() or so.stat().st_mtime < src.stat().st_mtime:
            so.parent.mkdir(parents=True, exist_ok=True)
            subprocess.run(["cc", "-shared", "-fPIC", "-O2", "-o", str(so), str(src), "-ldl"], check=True, capture_output=True)
        env["LD_PRELOAD"] = " ".join(x for x in (str(so), os.environ.get("LD_PRELOAD", "")) if x)
    for i in range(max(1, workers) if tasks else 0):
        cmd = [PY, "-m", "dbe", "farm.worker", json.dumps({"run": run, "worker": f"w{i + 1}"})]
        procs.append(subprocess.Popen((["taskset", "-c", str(i % ncpu)] if pin else []) + cmd, cwd=ROOT, env=env, stdout=subprocess.DEVNULL, stderr=open(q / f"w{i + 1}.log", "w")))
    FM.wait(procs, q)
    import resource
    peak = round(resource.getrusage(resource.RUSAGE_CHILDREN).ru_maxrss / 1024, 1)   # the largest single process under the farm (MB)
    done, failed = FM.results(q); t_shots = round(_t.time() - t0, 1)
    if failed:
        raise RuntimeError(f"{len(failed)} shots failed on the farm: " + "; ".join(f"{x['shot']}: {x.get('error', '')[:120]}" for x in failed))
    for x in done:
        rows.append({"shot": x["shot"], "from": f"rendered by {x['worker']}", "seconds": x["seconds"], "frames": x["frames"]})
    busy = {}
    for x in done:
        busy[x["worker"]] = round(busy.get(x["worker"], 0) + x["seconds"], 1)
    out = {"film": name, "workers": workers, "pinned": pin, "shots": sorted(rows, key=lambda r: r["shot"]), "worker_busy_s": busy, "shots_wall_s": t_shots,
           "rendered": len(done), "from_cache": sum(1 for r in rows if r["from"] == "cache"), "queue": str(q.relative_to(ROOT)), "peak_rss_mb": peak,
           "one_core_s": round(sum(x["seconds"] for x in done), 1)}   # the same shots one after another on one core
    if assemble:
        r = film_render(name); out["render"] = {"skipped": len(r.get("unchanged") or []), "qa_failures": sorted(k for k, v in (r.get("qa") or {}).items() if v is False)}
    out["total_wall_s"] = round(_t.time() - t0, 1)
    return out


@command("farm.longform", minutes=("number", "length of the synthetic episode", 20), workers=("integer", "farm workers", 3))
def farm_longform(minutes=20, workers=3):
    """The long-form test (WP-38): a synthetic counting dialogue of about `minutes` (zz-longform, never posted) is
    voiced, acted and rendered on the farm, then assembled and checked: its length, shots, frames, the farm's wall
    time against the same shots one after another on one core, the largest process's memory, the cache's size, the
    assembly's time and the QA bar. Hours of CPU: run it in the background."""
    import time as _t
    name = "zz-longform"; shutil.rmtree(FILMS / name, ignore_errors=True); t0 = _t.time()
    n = max(2, round(minutes * 60 / 8.9))   # about 8.9 s per exchange (measured on zz-farm)
    film_from_template(name, "dialogue", _farm_brief(n)); voice_build(name); retime(name); acting_plan(name); t_prep = round(_t.time() - t0, 1)
    r = farm_render(name, workers=workers, fresh=True, cache=True, assemble=False); t_a = _t.time()
    fr = film_render(name); t_asm = round(_t.time() - t_a, 1)
    final = FILMS / name / "build" / "final.mp4"
    dur = float(_run(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", str(final)])[-1])
    cache_mb = round(sum(f.stat().st_size for f in (ROOT / "out" / "farm" / "cache").glob("*")) / 1e6, 1)
    out = {"exchanges": n, "length_s": round(dur, 1), "shots": len(r["shots"]), "frames": sum(x.get("frames", 0) for x in r["shots"]), "prepare_s": t_prep,
           "farm_wall_s": r["shots_wall_s"], "one_core_s": r["one_core_s"], "ratio": round(r["shots_wall_s"] / max(1e-6, r["one_core_s"]), 3),
           "worker_busy_s": r["worker_busy_s"], "peak_rss_mb": r["peak_rss_mb"], "assembly_s": t_asm, "cache_mb": cache_mb,
           "qa_failures": sorted(k for k, v in (fr.get("qa") or {}).items() if v is False), "total_s": round(_t.time() - t0, 1)}
    (ROOT / "out" / "farm" / "longform.json").write_text(json.dumps(out, indent=1))
    return out


@command("farm.worker", run=("string", "farm run (out/farm/runs/<run>)"), worker=("string", "this worker's name"))
def farm_worker(run, worker):
    """A farm worker (WP-38): claims shots from the run's queue until it is empty, renders each (shot.render), puts it
    in the shared cache by its content hash and marks it fresh in its film's build."""
    from . import farm as FM
    import time as _t
    q = FM.FARM / "runs" / run; n = 0
    while True:
        tf = FM.claim(q, worker)
        if tf is None:
            return {"worker": worker, "rendered": n}
        t = json.loads(tf.read_text()); t0 = _t.time()
        try:
            shot_render(t["film"], t["shot"])
            mp4 = FILMS / t["film"] / "build" / "shots" / f"{t['shot']}.mp4"
            (mp4.parent / f"{t['shot']}.hash").write_text(t["key"])
            if os.environ.get("DBE_FARM_CACHE", "1") == "1":
                FM.cache_put(t["key"], mp4)
            FM.finish(q, tf, True, {"worker": worker, "seconds": round(_t.time() - t0, 2)}); n += 1
        except Exception as e:
            FM.finish(q, tf, False, {"worker": worker, "error": str(e)[:400]})


# ---------------- corrections, companions and living films (WP-27) ----------------
@command("film.page", name=("string", "film"))
def film_page(name):
    """The film's page (WP-27): title, the film, what it says, its sources, its credits and its dated corrections log
    ("what we got wrong" apart from updates), as one self-contained HTML file: build/page/index.html."""
    from . import living as LV
    from . import packaging as PK
    d = _film(name); s = _shots(name, resolve=False); t = PK.load(d) if (d / "titles.json").exists() else {"titles": []}
    ch = (t.get("chosen") or {}).get("title"); title = t["titles"][ch]["text"] if ch is not None and t.get("titles") else (s.get("title") or name)
    tm = _json(d / "timing.json", {}); cr = film_credits(name)
    pg = d / "build" / "page"; pg.mkdir(parents=True, exist_ok=True)
    (pg / "index.html").write_text(LV.page(title, "../final.mp4", [l["text"] for l in tm.get("lines", [])], _json(d / "facts.json", {"facts": []}).get("facts", []),
                                           "\n".join(cr["credits"]), LV.load_log(d), s.get("lang", "en")))
    return {"page": str((pg / "index.html").relative_to(ROOT)), "title": title, "corrections": len(LV.load_log(d)["corrections"])}


@command("film.correct", name=("string", "film"), key=("string", "what to change, as film.strings lists it: line:<id>, shot:<id>:overlay:<n>:<field>, titles:<n>, thumb:<n>:top, fact:<id>"),
         to=("string", "the corrected text"), why=("string", "what was wrong (or what changed), in a sentence"), kind=("string", "error | update | clarification", "error"),
         credit=("string", "who reported it, if they agree to be named", ""), render=("boolean", "re-voice and re-render now (else only the data and the log)", True))
def film_correct(name, key, to, why, kind="error", credit="", render=True):
    """One correction, everywhere (WP-27): the text is changed by its key, logged with the date, what it said, why and
    who reported it, and carried to every surface: a line is re-voiced and the film re-rendered (voice, burned-in and
    sidecar captions, the bubbles), a title or thumbnail line updates titles.json and the covers, the credits gain a
    dated corrections section with thanks, the film's page its log, and the posting package is remade. Each surface is
    then read back for the new words."""
    from . import i18n as I
    from . import living as LV
    if kind not in LV.KINDS:
        raise ValueError(f"kind is one of {LV.KINDS}")
    d = _film(name); sh, sc, ti, da = _shots(name, resolve=False), _json(d / "script.json"), _json(d / "titles.json", {}), _json(d / "data.json", {})
    if key.startswith("fact:"):
        facts = _json(d / "facts.json", {"facts": []}); fid = key.split(":")[1]; fld = key.split(":")[2] if key.count(":") > 1 else "claim"
        f = next((x for x in facts["facts"] if x.get("id") == fid), None)
        if not f:
            raise ValueError(f"no fact {fid}")
        was = f.get(fld); f[fld] = to; (d / "facts.json").write_text(json.dumps(facts, indent=1, ensure_ascii=False))
    else:
        src = {x["key"]: x["text"] for x in I.extract(sh, sc, ti, da)}
        if key not in src:
            raise ValueError(f"no {key} in {name} (film.strings lists the keys)")
        was = src[key]
        bad = I.check_bindings(was, to)
        if bad:
            raise ValueError(f"the correction changes data bindings {bad}: correct the data (film.data) instead")
        sh2, sc2, ti2, da2, *_ = I.apply(sh, sc, ti, da, {key: to}, sc.get("lang") or "en", keep_rest=True)
        for f_, o in (("shots.json", sh2), ("script.json", sc2), ("titles.json", ti2), ("data.json", da2)):
            if (d / f_).exists() and o != _json(d / f_):
                (d / f_).write_text(json.dumps(o, indent=1, ensure_ascii=False))
    entry = LV.add(d, {"date": _today().isoformat(), "kind": kind, "key": key, "from": was, "to": to, "why": why, **({"credit": credit} if credit else {})})
    surfaces = {}
    if render:
        if key.startswith("line:"):
            voice_build(name); retime(name); surfaces["voice"] = True
        r = film_render(name); surfaces["render"] = {k: v for k, v in (r.get("qa") or {}).items() if v is False} or "all checks pass"
        cap = (d / "build" / "captions.srt").read_text() if (d / "build" / "captions.srt").exists() else ""
        if key.startswith("line:") and _json(_film(name) / "shots.json").get("captions", True) is not False:
            surfaces["captions"] = all(w.lower() in cap.lower() for w in re.findall(r"[\w']+", to)[:6])
        if key.startswith(("titles:", "thumb:")):
            try:
                cover_make(name); surfaces["covers"] = True
            except Exception as e:
                surfaces["covers"] = f"not remade: {str(e)[:80]}"
        try:
            film_package(name); surfaces["package"] = True
        except Exception as e:
            surfaces["package"] = f"not remade: {str(e)[:80]}"
        if key.startswith(("line:", "shot:")):   # the words on screen, read back (bubbles, overlays, captions)
            tc = film_text_check(name); hit = [x for x in tc["items"] if any(w.lower() in x["text"].lower() for w in re.findall(r"[\w']{4,}", to)[:3])]
            surfaces["on_screen"] = bool(hit) and all(x["ok"] for x in hit) if hit else "not shown on screen"
    cr = film_credits(name); surfaces["credits"] = any(why in l for l in cr["credits"])
    pg = film_page(name); html_ = (ROOT / pg["page"]).read_text(); surfaces["page"] = __import__("html").escape(why) in html_
    if key.startswith("titles:"):
        surfaces["title"] = any(t["text"] == to for t in _json(d / "titles.json", {}).get("titles", []))
    entry["surfaces"] = surfaces
    lg = LV.load_log(d); lg["corrections"][-1]["surfaces"] = surfaces; LV.log_path(d).write_text(json.dumps(lg, indent=1, ensure_ascii=False) + "\n")
    return entry


@command("film.companion", name=("string", "film"), run=("boolean", "run the guide and check every number", True))
def film_companion(name, run=True):
    """A runnable companion guide (WP-27): build/companion/ holds the film's analysis (scripts, sources, cached source
    files), numbers.json (every number the film shows or says: each data binding in its lines and on screen and every
    value of its charts, with where it appears) and guide.py (and guide.md), which re-runs the analysis in a scratch
    folder, checks each cached source against its recorded sha256, and prints every number beside the number it gets.
    With run, the guide is run and every number must come back the same."""
    from . import living as LV
    d = _film(name)
    if not (d / "analysis").exists():
        raise FileNotFoundError(f"{name} has no analysis/ (only data films have companion guides)")
    nums = LV.numbers_in(_json(d / "data.json", {}), _json(d / "script.json", {}), _shots(name, resolve=False))
    cd = LV.write_companion(d, _shots(name, resolve=False).get("title") or name, nums)
    out = {"dir": str(cd.relative_to(ROOT)), "numbers": len(nums)}
    if run:
        r = subprocess.run([PY, "guide.py"], cwd=cd, capture_output=True, text=True, timeout=1800)
        j = json.loads(r.stdout) if r.returncode == 0 else {"error": r.stderr[-500:]}
        out.update({"all_reproduced": j.get("all_reproduced"), "sources": j.get("sources"), "different": [x for x in j.get("numbers", []) if not x["same"]], **({"error": j["error"]} if "error" in j else {})})
    return out


@command("film.living", name=("string", "film"), render=("boolean", "re-voice and re-render what changed", True))
def film_living(name, render=True):
    """A living film (WP-27, E12): its sources fetched again and its analysis re-run (film.data refresh); when a number
    the film uses has changed, the lines that say it are re-voiced, the shots that show it re-rendered, and the change
    logged as a dated update in the corrections log (on the page and in the credits)."""
    from . import living as LV
    d = _film(name); before = _json(d / "data.json", {})
    nums0 = {(n["where"], n["path"]): n["value"] for n in LV.numbers_in(before, _json(d / "script.json", {}), _shots(name, resolve=False))}
    r = film_data(name, refresh=True, revoice=render, render=render)
    after = _json(d / "data.json", {})
    nums1 = {(n["where"], n["path"]): n["value"] for n in LV.numbers_in(after, _json(d / "script.json", {}), _shots(name, resolve=False))}
    changed = [{"where": w, "path": p_, "was": v, "now": nums1.get((w, p_))} for (w, p_), v in nums0.items() if nums1.get((w, p_)) != v]
    if changed:
        LV.add(d, {"date": _today().isoformat(), "kind": "update", "key": "data", "from": {c["path"]: c["was"] for c in changed}, "to": {c["path"]: c["now"] for c in changed},
                   "why": "the source data changed: " + ", ".join(sorted({c["path"] for c in changed}))})
        film_page(name)
    return {"numbers_changed": changed, "shots": r.get("shots_to_rerender"), "lines": r.get("lines_to_revoice"), "rendered": r.get("rendered")}


@command("plan.intake", text=("string", "the myth or question, in the sender's words"), by=("string", "who sent it (a name to credit, or empty for anonymous)", ""),
         where=("string", "how it came (a comment link, a form)", ""), field=("string", "the channel field it belongs to (default: left for research)", ""), channel=CH_ARG)
def plan_intake(text, by="", where="", field="", channel=""):
    """Send-a-myth (WP-27): a viewer's myth or question goes into the idea bank as an evergreen myth-vs-data idea
    waiting for research (status intake: it has no sources yet, so plan.schedule leaves it until research fills it
    in), credited to the sender if they gave a name; one the bank already holds is not added twice."""
    from . import planner as PL
    t = " ".join(text.split())
    if not 8 <= len(t) <= 400:
        raise ValueError("a myth is a sentence (8 to 400 characters)")
    ch = PL.channel(channel); bank = _plan_bank(channel)
    probe = {"title": t[:90], "hook": t, "angle": ""}
    # a viewer's sentence is short, so it is matched against each idea's title only (against hooks and angles a few
    # common words, "store" and "water", made a camel's hump the same idea as a chain of lakes)
    dup = next((i for i in bank["ideas"] if PL.same_topic(probe, {"title": i["title"]}, threshold=0.6)), None)
    if dup:
        dup.setdefault("asked_by", []).append({"by": by or "anonymous", "on": _today().isoformat(), **({"where": where} if where else {})}); _plan_save("ideas.json", bank, channel)
        return {"added": False, "same_as": dup["id"], "title": dup["title"], "asked_by": len(dup["asked_by"])}
    n = max([int(re.sub(r"\D", "", i["id"]) or 0) for i in bank["ideas"]] + [0]) + 1
    idea = {"id": f"I{n:03d}", "title": t[:90], "sweep": "evergreen", "field": field if field in ch["fields"] else None, "hook": t, "angle": "", "why_now": "a viewer asked",
            "sources": [], "research_leads": ["check the claim against primary sources before anything is written"], "cautions": ["the sender's words are a lead, not a fact"],
            "format": "myth_vs_data", "status": "intake", "asked_by": [{"by": by or "anonymous", "on": _today().isoformat(), **({"where": where} if where else {})}]}
    bank["ideas"].append(idea); _plan_save("ideas.json", bank, channel)
    return {"added": True, "idea": idea["id"], "status": "intake"}


@command("catalogue.rebrand", brand=("string", "brand kit id (brand/<id>.json) to move to"), films=("array", "films to re-make (default: every film of the channel's brand)", None),
         render=("boolean", "re-render and re-make covers and packages", True), channel=CH_ARG)
def catalogue_rebrand(brand, films=None, render=True, channel=""):
    """Rebrand the catalogue (WP-27, E30): the channel takes the new brand kit and every film that inherits it is
    re-rendered (the graph re-makes only what the brand touches), with its covers and posting package remade; returns
    each film's QA and what was re-made."""
    from . import planner as PL
    ch = PL.channel(channel); bf = ROOT / "brand" / f"{brand}.json"
    if not bf.exists():
        raise FileNotFoundError(f"no brand kit brand/{brand}.json")
    old = ch.get("brand"); ch["brand"] = brand; chf = PL.chan_dir(channel) / "channel.json"
    cur = _json(chf, {}); cur["brand"] = brand; chf.write_text(json.dumps(cur, indent=1, ensure_ascii=False) + "\n")
    films = films or [f.name for f in sorted(FILMS.iterdir()) if (f / "shots.json").exists() and "--" not in f.name and not f.name.startswith("zz-")
                      and _json(f / "shots.json", {}).get("brand") in (True, old, brand)]
    out = []
    for f in films:
        sj = _json(FILMS / f / "shots.json")
        if sj.get("brand") != brand:   # from the house kit (true) or the channel's old kit to the new one
            sj["brand"] = brand; (FILMS / f / "shots.json").write_text(json.dumps(sj, indent=1, ensure_ascii=False))
        row = {"film": f}
        if render:
            r = film_render(f); row["rendered"] = [x["shot"] for x in r.get("rendered", [])]; row["qa_failures"] = [k for k, v in (r.get("qa") or {}).items() if v is False]
            for step in (cover_make, film_package):
                try:
                    step(f); row[step.__name__] = True
                except Exception as e:
                    row[step.__name__] = str(e)[:80]
        out.append(row)
    return {"from": old, "to": brand, "films": out}


# ---------------- provenance, disclosure and consent (WP-26) ----------------
def _keys():
    from . import production as PR
    from . import provenance as PV
    return PV.ensure_keys(PR.reg_dir() / "keys")


def _recipe(name, sample=12):
    """what a film was made from (E14): its data files' hashes, the engine files' hashes, the commit, and its frame
    keys (all of them hashed, and a sample by frame) so a re-make can be checked against what was signed"""
    import hashlib
    from . import provenance as PV
    d = _film(name); s = _shots(name); fps = s.get("fps", 30)
    files = {f: PV.sha256(d / f) for f in ("shots.json", "script.json", "timing.json", "data.json", "facts.json", "score.json", "sound.json") if (d / f).exists()}
    eng = {f: PV.sha256(ROOT / f) for f in ENGINE_FILES if (ROOT / f).exists()}
    head = subprocess.run(["git", "rev-parse", "HEAD"], cwd=ROOT, capture_output=True, text=True).stdout.strip()
    fk = (_json(d / "build" / "frame_keys.json", {}) or {}).get("keys") or []
    trans = _json(d / "build" / "transitions.json", [])
    shots = s["shots"]; starts = []; acc = 0
    for x in shots:
        starts.append(acc); acc += int(round((x["end"] - x["start"]) * fps))
    blocked = set()
    for tr in trans:   # frames inside a transition hold two shots: not sampled
        i = next(j for j, x in enumerate(shots) if x["id"] == tr["shot"]); c = starts[i]
        blocked |= set(range(c - tr["before"], c + tr["after"]))
    cand = [i for i in range(len(fk)) if i not in blocked]
    pick = sorted({cand[int(round(k * (len(cand) - 1) / max(1, sample - 1)))] for k in range(sample)}) if cand else []
    return {"version": 1, "fps": fps, "files": files, "engine": eng, "commit": head or None,
            "frames": len(fk), "frame_keys_sha256": hashlib.sha256("\n".join(fk).encode()).hexdigest() if fk else None, "frame_sample": {str(i): fk[i] for i in pick}}


def _film_made_with(name):
    reg = _voice_registry(); store = _consent_store(); prov = film_provenance(name)
    from . import provenance as PV
    script = _json(FILMS / name / "script.json", {})
    voices = sorted({v.get("voice") for v in (script.get("speakers") or {}).values()} | ({script["voice"]} if script.get("voice") else set()) - {None})
    vs = []
    for v in voices:
        r = reg.get(v, {}); ok, why = PV.voice_basis(v, reg, store)
        vs.append({"voice": v, "synthetic": r.get("kind") not in ("recording",), "status": r.get("status"), "license": r.get("license"), "consent": why})
    models = [{"name": m.get("model") or m.get("name"), "touches": "picture", "output": m.get("output")} for m in prov.get("models", [])] if isinstance(prov, dict) else []
    return {"voices": vs, "models": models, "posting_flags": (prov or {}).get("flags", []) if isinstance(prov, dict) else []}


@command("film.disclosure", name=("string", "film"), realistic=("boolean", "the film shows realistic people, places or events (not drawn characters)", False))
def film_disclosure(name, realistic=False):
    """Each platform's AI-disclosure setting for a film (WP-26): on or off, whether the platform requires it and why,
    and the caption line saying what is synthetic (dbe/disclosure.json, read from each platform's help page)."""
    from . import provenance as PV
    mw = _film_made_with(name)
    return PV.disclosure(_json(ROOT / "dbe" / "disclosure.json"), mw["voices"], mw["models"], realistic)


@command("film.sign", name=("string", "film"), files=("array", "build files to sign (default: final.mp4 and, if made, final_ad.mp4)", None),
         timestamp=("string", "a timestamp authority URL (RFC 3161), optional", ""))
def film_sign(name, files=None, timestamp=""):
    """Content credentials for a film's finals (WP-26): a C2PA manifest (created by Doodleberry, digital source type,
    title and channel, the voices and models with their licence and consent basis, the AI-disclosure text, a
    do-not-train request, and the film's recipe: data and engine hashes and frame keys) signed with the studio's
    certificate into each file, then read back with c2patool, the reference tool, trusting the studio's root.
    Writes build/provenance.json and build/trust_anchors.pem (the root, for anyone verifying)."""
    import shutil as _sh
    from . import provenance as PV
    d = _film(name); s = _shots(name, resolve=False); keys = _keys()
    files = files or [f for f in ("final.mp4", "final_ad.mp4") if (d / "build" / f).exists()]
    if not files:
        raise FileNotFoundError(f"{name} has no finals to sign: render it first")
    mw = _film_made_with(name); disc = PV.disclosure(_json(ROOT / "dbe" / "disclosure.json"), mw["voices"], mw["models"])
    recipe = _recipe(name); ai = bool(disc["reasons"])
    chan = (_json(d / "script.json", {}).get("channel") or "Doodleberry")
    man = PV.manifest(s.get("title") or name, chan, {k: mw[k] for k in ("voices", "models")}, {"reasons": disc["reasons"], "caption": next(iter(disc["platforms"].values()))["caption"]}, recipe, ai)
    _sh.copy(keys["root"], d / "build" / "trust_anchors.pem")
    out = {"film": name, "signed": [], "ai_shaped": ai}
    for f in files:
        src = d / "build" / f; tmp = src.with_suffix(".signing.mp4")
        before = PV.sha256(src); PV.sign(src, tmp, man, keys, timestamp or None); tmp.replace(src)
        v = PV.verify(src, d / "build" / "trust_anchors.pem") if PV.C2PATOOL.exists() else {"state": "c2patool not installed", "failures": []}
        out["signed"].append({"file": f, "sha256_unsigned": before, "sha256": PV.sha256(src), "verify": v})
    (d / "build" / "provenance.json").write_text(json.dumps({**out, "manifest": man}, indent=1, ensure_ascii=False))
    out["ok"] = all(x["verify"].get("state") in ("Trusted", "Valid") and not x["verify"].get("failures") for x in out["signed"])
    return out


@command("film.verify", name=("string", "film"), path=("string", "a signed file (default: the film's build/final.mp4)", ""), frames=("boolean", "re-make the signed sample frames and compare their keys", True))
def film_verify(name, path="", frames=True):
    """Check a signed film (WP-26, E14): its content credentials with c2patool (trusting the studio's root), and its
    recipe against the film as it is now: which data and engine files differ from what was signed, and, re-making the
    signed sample frames in the player, whether each frame's key still matches."""
    from . import provenance as PV
    d = _film(name); f = Path(path) if path else d / "build" / "final.mp4"
    trust = d / "build" / "trust_anchors.pem"
    c = PV.verify(f, trust if trust.exists() else None)
    st, _ = PV.read(f)
    act = st.get("manifests", {}).get(st.get("active_manifest"), {})
    rec = next((a["data"] for a in act.get("assertions", []) if a.get("label") == "org.doodleberry.recipe"), None)
    if not rec:
        return {"c2pa": c, "recipe": "none signed"}
    now = _recipe(name, sample=0)
    changed = sorted([k for k, v in rec["files"].items() if now["files"].get(k) != v]) + sorted([f"engine {k}" for k, v in rec["engine"].items() if now["engine"].get(k) != v])
    out = {"c2pa": c, "recipe": {"commit": rec.get("commit"), "changed_since": changed, "frame_keys_same": now["frame_keys_sha256"] == rec.get("frame_keys_sha256")}}
    if frames and rec.get("frame_sample"):
        out["frames"] = _remake_keys(name, {int(k): v for k, v in rec["frame_sample"].items()})
    out["ok"] = c.get("state") in ("Trusted", "Valid") and not c.get("failures") and not changed and (not frames or out["frames"]["matching"] == out["frames"]["checked"])
    return out


def _remake_keys(name, sample):
    """the signed sample frames re-made in the player: each film frame's key, as _frame_keys composes it"""
    import hashlib
    d = _film(name); s = _shots(name); fps = s.get("fps", 30); page = _player_page(name); acc = 0; where = {}
    for x in s["shots"]:
        n = int(round((x["end"] - x["start"]) * fps))
        for fr in sample:
            if acc <= fr < acc + n:
                where.setdefault(x["id"], []).append((fr, fr - acc))
        acc += n
    ev = []
    ass = d / "build" / "captions.ass"
    if ass.exists():
        hms = lambda v: (lambda h, m, s_: int(h) * 3600 + int(m) * 60 + float(s_))(*v.split(":"))
        ev = [(hms(l.split(",", 9)[1]), hms(l.split(",", 9)[2]), l) for l in ass.read_text().splitlines() if l.startswith("Dialogue:")]
    post = json.dumps(s.get("post"), sort_keys=True); rows = []
    for sid, frs in where.items():
        r = json.loads(_run(["node", "tools/frame_keys.mjs", "file://" + str(page) + f"?shot={sid}", ",".join(str(j) for _, j in frs)], timeout=600)[-1])
        for fr, j in frs:
            k = f"{sid}:{r['plate']}:{r['keys'][str(j)]}"; t = fr / fps; cap = "\n".join(e[2] for e in ev if e[0] <= t < e[1])
            got = hashlib.sha1(f"{k}#{cap}#{post}".encode()).hexdigest()[:16]
            rows.append({"frame": fr, "shot": sid, "match": got == sample[fr]})
    return {"checked": len(rows), "matching": sum(r["match"] for r in rows), "frames": rows}


@command("consent.add", kind=("string", "voice | likeness"), subject=("string", "the person"), scope=("object", "what it covers: {commercial: bool, platforms: [...], uses: text}", None),
         granted_on=("string", "YYYY-MM-DD"), expires=("string", "YYYY-MM-DD, or empty for no end", ""), evidence=("string", "the signed form (a file kept off git): its sha256 is recorded", ""),
         recorded_by=("string", "who recorded it"), id=("string", "record id (default: made from the subject and date)", ""))
def consent_add(kind, subject, granted_on, recorded_by, scope=None, expires="", evidence="", id=""):
    """Record a person's consent (WP-26): to their voice being cloned or used, or their likeness being drawn, for the
    uses in scope, from a date, until a date or revoked. The signed form stays off git; its hash is the record's
    evidence. A voice made from a person points at its record ("consent" in voices/registry.json); a puppet that
    depicts a person, in meta.likeness."""
    from . import provenance as PV
    if kind not in ("voice", "likeness"):
        raise ValueError("kind is voice or likeness")
    root = Path(os.environ.get("DBE_CONSENT_ROOT") or ROOT); st = _consent_store()
    rid = id or re.sub(r"[^a-z0-9]+", "-", f"{kind}-{subject}-{granted_on}".lower()).strip("-")
    if any(r["id"] == rid for r in st["records"]):
        raise ValueError(f"{rid} exists")
    rec = {"id": rid, "kind": kind, "subject": subject, "scope": scope or {"commercial": False}, "granted_on": granted_on, "expires": expires or None,
           "revoked": None, "evidence_sha256": PV.sha256(_inside(evidence, True)) if evidence else None, "recorded_by": recorded_by, "recorded_on": _today().isoformat()}
    st["records"].append(rec); (root / "consent").mkdir(exist_ok=True)
    (root / "consent" / "records.json").write_text(json.dumps(st, indent=1, ensure_ascii=False) + "\n")
    return rec


@command("consent.revoke", id=("string", "record id"), on=("string", "YYYY-MM-DD (default today)", ""), reason=("string", "why", ""))
def consent_revoke(id, on="", reason=""):
    """Revoke a consent record (WP-26): from that day the voice or likeness is refused for new renders."""
    root = Path(os.environ.get("DBE_CONSENT_ROOT") or ROOT); st = _consent_store()
    rec = next((r for r in st["records"] if r["id"] == id), None)
    if not rec:
        raise ValueError(f"no consent record {id}")
    rec["revoked"] = on or _today().isoformat(); rec["revoked_reason"] = reason
    (root / "consent" / "records.json").write_text(json.dumps(st, indent=1, ensure_ascii=False) + "\n")
    return rec


@command("consent.check", name=("string", "film"))
def consent_check(name):
    """The consent basis of every voice and likeness a film uses (WP-26)."""
    rows = [{"what": w, "ok": ok, "why": why} for w, ok, why in consent_gate(name)]
    return {"film": name, "ok": all(r["ok"] for r in rows), "rows": rows}


# ---------------- analytics (WP-31) ----------------
def _an(channel=""):
    from . import analytics as AN
    from . import planner as PL
    d = PL.chan_dir(channel); return AN, d, AN.load(d), AN.posts_from_calendars(d)


def _an_mark(st, matched, synthetic):
    """real and simulated numbers never mix in one post"""
    for pid in set(matched):
        if st["posts"][pid].get("synthetic", synthetic) != synthetic:
            raise ValueError(f"{pid} holds {'simulated' if not synthetic else 'measured'} numbers already; keep rehearsals in a scratch plan (DBE_PLAN)")
        st["posts"][pid]["synthetic"] = synthetic


@command("analytics.import", path=("string", "an export file (CSV from YouTube Studio, TikTok Studio, Instagram insights; or canonical JSON)"),
         platform=("string", "youtube | tiktok | instagram | facebook | x | linkedin"), as_of=("string", "when the export was taken (ISO date-time; default now)", ""),
         kind=("string", "totals (one row per post) | geography (rows by country) | retention (one post's curve)", "totals"),
         post=("string", "for a retention export: the post (date-platform, e.g. 2027-01-04-youtube)", ""),
         duration_s=("number", "for a retention export in % of the video: its length (default: the film's)", 0),
         columns=("object", "extra header -> canonical name (views, likes, comments, shares, saves, subs, avg_view_s, avg_pct, stayed_pct, revenue, url, title, ...)", None),
         synthetic=("boolean", "the numbers are simulated (rehearsals and tests): the posts are marked and never teach a real plan", False), channel=CH_ARG)
def analytics_import(path, platform, as_of="", kind="totals", post="", duration_s=0, columns=None, synthetic=False, channel=""):
    """Read a platform's export into the channel's analytics (WP-31): each row matched to a posted calendar row by its
    link, the video id in its link, or its title, and added as a dated snapshot (earlier reads are kept), or a
    country breakdown, or a retention curve. Unknown headers and unmatched rows are reported, never guessed."""
    import datetime as _dt
    AN, d, st, posts = _an(channel)
    f = _inside(path, True) if not Path(path).is_absolute() else Path(path)
    as_of = as_of or _dt.datetime.now().isoformat(timespec="seconds")
    if f.suffix == ".json":
        j = json.loads(f.read_text()); rows, unknown = j.get("rows", j if isinstance(j, list) else []), []
    else:
        rows, unknown = AN.read_export(f.read_text(encoding="utf-8-sig"), columns)
    if kind == "retention":
        if post not in posts:
            raise ValueError(f"no posted row {post!r} (posts: {', '.join(sorted(posts)[:8])}...)")
        fl = posts[post].get("film"); dur = duration_s or (float(_run(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0",
                                                                        str(FILMS / fl / "build" / "final.mp4")])[-1]) if fl and (FILMS / fl / "build" / "final.mp4").exists() else 0)
        n = AN.add_retention(st, posts, post, rows, dur); AN.save(d, st)
        return {"post": post, "points": n, "unknown_headers": unknown}
    matched, unmatched = AN.ingest(st, posts, rows, platform, as_of, kind)
    _an_mark(st, matched, synthetic)
    AN.save(d, st)
    return {"matched": len(matched), "posts": sorted(set(matched)), "unmatched": unmatched, "unknown_headers": unknown, "as_of": as_of}


@command("analytics.youtube_api", start=("string", "first day (YYYY-MM-DD)"), end=("string", "last day (YYYY-MM-DD)"), as_of=("string", "the read's time (default now)", ""),
         channel=CH_ARG)
def analytics_youtube_api(start, end, as_of="", channel=""):
    """Read this channel's posted YouTube videos from the YouTube Analytics API (WP-31): views, likes, comments,
    shares, subscribers gained, average view duration and percentage, estimated revenue, per video. Needs the owner's
    OAuth access token in the production registry (connectors.json: {"youtube_analytics": {"access_token": ...}});
    without it, export from YouTube Studio and use analytics.import."""
    import datetime as _dt, urllib.parse, urllib.request
    from . import production as PR
    AN, d, st, posts = _an(channel)
    cfg = (_json(PR.reg_dir() / "connectors.json", {}) or {}).get("youtube_analytics") or {}
    if not cfg.get("access_token"):
        raise PermissionError("no YouTube Analytics credentials (production registry connectors.json: youtube_analytics.access_token); export from YouTube Studio and use analytics.import")
    ids = {}
    for pid, p in posts.items():
        m = re.search(r"(?:v=|youtu\.be/|shorts/)([\w-]{6,})", p.get("url") or "")
        if p["platform"] == "youtube" and m:
            ids[m.group(1)] = pid
    if not ids:
        return {"matched": 0, "note": "no posted YouTube rows with a video id in their link"}
    metrics = "views,likes,comments,shares,subscribersGained,averageViewDuration,averageViewPercentage,estimatedRevenue"
    q = urllib.parse.urlencode({"ids": "channel==MINE", "startDate": start, "endDate": end, "metrics": metrics, "dimensions": "video", "filters": "video==" + ",".join(ids)})
    base = os.environ.get("DBE_YT_ANALYTICS_URL") or cfg.get("base_url") or "https://youtubeanalytics.googleapis.com/v2/reports"
    req = urllib.request.Request(f"{base}?{q}", headers={"Authorization": f"Bearer {cfg['access_token']}"})
    j = json.loads(urllib.request.urlopen(req, timeout=30).read())
    names = {"video": "video_id", "subscribersGained": "subs", "averageViewDuration": "avg_view_s", "averageViewPercentage": "avg_pct", "estimatedRevenue": "revenue"}
    cols = [names.get(c["name"], c["name"]) for c in j.get("columnHeaders", [])]
    rows = [dict(zip(cols, r)) for r in j.get("rows", [])]
    for r in rows:
        r["url"] = (posts.get(ids.get(r.get("video_id"))) or {}).get("url")
    matched, unmatched = AN.ingest(st, posts, rows, "youtube", as_of or _dt.datetime.now().isoformat(timespec="seconds"), source="youtube-analytics-api")
    _an_mark(st, matched, False)
    AN.save(d, st)
    return {"matched": len(matched), "unmatched": unmatched}


@command("analytics.checklist", post=("string", "post id: date-platform (e.g. 2027-01-04-youtube); empty: every post that is 48 hours old or less behind", ""), channel=CH_ARG)
def analytics_checklist(post="", channel=""):
    """The 48-hour checklist (WP-31): each post's reads at 1, 24 and 48 hours, and every check judged against this
    channel (views against its median at the same age, the share that stayed, the hook's hold at 3 s, percentage viewed,
    shares, saves, comments and subscribers per thousand views, click-through), with the action each points to."""
    AN, d, st, posts = _an(channel)
    ids = [post] if post else sorted(st["posts"])
    if post and post not in st["posts"]:
        raise ValueError(f"no numbers for {post} yet (analytics.import)")
    return {"posts": [AN.checklist(st, i) for i in ids]}


@command("analytics.retention", post=("string", "post id (date-platform)"), channel=CH_ARG)
def analytics_retention(post, channel=""):
    """A post's retention curve laid over its film (WP-31): per shot and per line, the percent of viewers lost, per
    second, and against the curve's own smooth decay, with the three places that lose the most beyond it (the hook's
    hold at 3 s too)."""
    AN, d, st, posts = _an(channel)
    p = st["posts"].get(post) or {}
    if not p.get("retention"):
        raise ValueError(f"no retention curve for {post} (analytics.import kind=retention)")
    fl = p.get("film")
    if not fl or not (FILMS / fl).exists():
        raise ValueError(f"{post} has no film here to map onto")
    s = _shots(fl); tm = _cut_timing(s, _json(FILMS / fl / "timing.json", {}))
    return {"post": post, "film": fl, **AN.retention_map(p, s["shots"], tm.get("lines", []))}


@command("analytics.lessons", channel=CH_ARG)
def analytics_lessons(channel=""):
    """What retention says for the next films (WP-31, E11): every post with a retention curve and a film here, laid
    over its lines, pooled: the hook's hold at 3 s by format, and whether faster lines lose viewers faster (with the
    pace above which they do, when the evidence is clear)."""
    AN, d, st, posts = _an(channel); maps = []
    for pid, p in st["posts"].items():
        fl = p.get("film")
        if not p.get("retention") or not fl or not (FILMS / fl).exists():
            continue
        tm = _cut_timing(_shots(fl), _json(FILMS / fl / "timing.json", {})); m = AN.retention_map(p, _shots(fl)["shots"], tm.get("lines", []))
        wps = {l["id"]: len(l.get("words") or l.get("text", "").split()) / max(0.3, l["end"] - l["start"]) for l in tm.get("lines", [])}
        for l in m.get("lines", []):
            l["wps"] = round(wps.get(l["what"].split(":")[0], 0), 2)
        maps.append({**m, "format": p.get("format"), "post": pid})
    return {"posts": len(maps), **AN.lessons(maps)}


@command("analytics.hooks", variants=("object", "variant name -> post id (the first is the control), e.g. {\"A\": \"2027-01-04-youtube\", \"B\": \"2027-01-05-youtube\"}"),
         metric=("string", "hold_3s (retention at 3 s) | stayed (share that stayed to watch)", "hold_3s"), channel=CH_ARG)
def analytics_hooks(variants, metric="hold_3s", channel=""):
    """Hook variants compared (WP-31, E11): the films' alternative openings (variants.hooks) posted as separate posts,
    their hook hold compared as proportions of each post's viewers with Beta posteriors; a variant wins when it beats
    the control with probability 0.95 or more, else the test is undecided and says so."""
    AN, d, st, posts = _an(channel)
    for n, pid in variants.items():
        if pid not in st["posts"]:
            raise ValueError(f"no numbers for {pid}")
    return AN.compare_hooks(st, variants, metric)


@command("analytics.poll", film=("string", "film"), platform=("string", "youtube (community), x, instagram (story), linkedin, facebook"), counts=("array", "votes per option, once the poll has closed", None))
def analytics_poll(film, platform, counts=None):
    """An audience poll between a film's true titles (WP-31): the titles of titles.json whose checks passed, as many
    as the platform's poll holds and short enough for its options. With the votes, the most preferred option and its
    probability of being so (Dirichlet posterior); at 0.9 or more it becomes the film's chosen title."""
    from . import analytics as AN
    d = _film(film); t = _json(d / "titles.json", {"titles": []}); pl = AN.make_poll(t, platform)
    if "error" in pl or counts is None:
        return pl
    if len(counts) != len(pl["options"]):
        raise ValueError(f"{len(pl['options'])} options, {len(counts)} counts")
    r = AN.poll_result(pl["options"], counts)
    if r["winner"]:
        i = next(k for k, x in enumerate(t["titles"]) if x["text"] == r["winner"])
        t.setdefault("chosen", {})["title"] = i; t.setdefault("polls", []).append({"platform": platform, **r})
        (d / "titles.json").write_text(json.dumps(t, indent=1, ensure_ascii=False))
    return {**pl, **r}


@command("analytics.effects", quarters=("array", "quarters to learn from (default all)", None), synthetic=("boolean", "use simulated numbers (rehearsals only)", False), channel=CH_ARG)
def analytics_effects(quarters=None, synthetic=False, channel=""):
    """What performed (WP-31): each posted row's performance (log2 of its 48-hour views over the platform's median,
    averaged over platforms) and the effect of each field, sweep, format, local or not, and calendar role, shrunk
    toward zero by three pseudo-posts."""
    AN, d, st, posts = _an(channel)
    rows = AN.perf(st, synthetic=synthetic, quarters=quarters)
    return {"rows": rows, "effects": dict(sorted(AN.effects(rows).items(), key=lambda kv: -abs(kv[1]["effect"]))), "posts": len(rows)}


@command("plan.rerank", quarter=("string", "the quarter to plan, e.g. 2027-Q2"), learn_from=("array", "quarters whose measured posts teach it (default: every earlier one)", None),
         planned_on=("string", "the day the plan is made (default today)", ""), synthetic=("boolean", "learn from simulated numbers (rehearsals only)", False), channel=CH_ARG)
def plan_rerank(quarter, learn_from=None, planned_on="", synthetic=False, channel=""):
    """A plan that re-ranks itself (WP-31): every idea in the bank is scored from what performed (analytics.effects:
    its field, sweep, format and local effects; 3 is neutral), the quarter is planned with those scores and also as it
    would have been without them, and each row says why it holds what it holds: unchanged, moved (another idea took its
    slot and the rules placed it elsewhere), or entered the quarter, with the measured reasons for its score; the ideas
    that left the quarter are listed with theirs. The rules (dated hooks, the series, quotas, spacing) are the same as plan.schedule's
    and plan.check checks the result."""
    import copy, datetime as _dt
    from . import planner as PL
    AN, d, st, posts = _an(channel)
    learn = learn_from or sorted({p.get("quarter") for p in st["posts"].values() if p.get("quarter") and p["quarter"] < quarter})
    rows = AN.perf(st, synthetic=synthetic, quarters=learn); eff = AN.effects(rows)
    if not rows:
        raise ValueError(f"no measured posts in {learn or 'any quarter'} to learn from (analytics.import)")
    ch = PL.channel(channel); bank = _plan_bank(channel); po = _dt.date.fromisoformat(planned_on) if planned_on else _dt.date.today()
    old = _json(d / f"{quarter}.json")
    if old and any(r.get("film") for r in old["rows"]):
        raise ValueError(f"{quarter} already has briefed rows; edit it rather than re-planning")
    for i in bank["ideas"]:
        if i["status"] == "planned" and i.get("quarter") == quarter:
            i["status"] = "idea"
    base = copy.deepcopy(bank)
    for i in base["ideas"]:
        i["score"] = i.get("score_base", i.get("score", 3))
    before = {r["date"]: r for r in PL.schedule(quarter, base, ch, po)}
    why = {}
    for i in bank["ideas"]:
        i.setdefault("score_base", i.get("score", 3))
        sc, parts = AN.score_idea(i, eff, base=i["score_base"]); i["score"] = sc; why[i["id"]] = (sc, parts)
        i["score_why"] = AN.explain(parts)
    new = PL.schedule(quarter, bank, ch, po)
    sc_of = {i["id"]: i.get("score", 3) for i in bank["ideas"]}; base_of = {i["id"]: i["score_base"] for i in bank["ideas"]}
    title_of = {i["id"]: i["title"] for i in bank["ideas"]}
    was_at = {r["idea"]: d_ for d_, r in before.items() if r and r.get("idea")}
    now_ids = {r["idea"] for r in new if r.get("idea")}
    changed = moved = 0
    for r in new:
        if not r.get("idea"):
            continue
        reasons = AN.explain(why[r["idea"]][1])
        if before.get(r["date"], {}) and before[r["date"]].get("idea") == r["idea"]:
            r["why"] = f"unchanged (score {sc_of[r['idea']]}: {reasons})"
        elif r["idea"] in was_at:
            moved += 1
            r["why"] = f"moved from {was_at[r['idea']]}: the slot it had went to another idea, the rules placed it here (score {sc_of[r['idea']]})"
            r["moved_from"] = was_at[r["idea"]]
        else:
            changed += 1
            r["why"] = f"entered the quarter: score {sc_of[r['idea']]} (it was {base_of[r['idea']]}): {reasons}"
    left = [{"idea": i, "title": title_of[i], "score": sc_of[i], "was": base_of[i], "why": AN.explain(why[i][1]), "date": was_at[i]}
            for i in was_at if i not in now_ids]
    used = {r["idea"] for r in new if r.get("idea")}
    for i in bank["ideas"]:
        if i["id"] in used:
            i["status"] = "planned"; i["quarter"] = quarter
    top = sorted(eff.values(), key=lambda e: -abs(e["effect"]))[:8]
    cal = {"quarter": quarter, "planned_on": po.isoformat(), "channel": ch["name"], "channel_id": ch["id"], "rules": ch["rules"], "rows": new,
           "rerank": {"learned_from": learn, "posts": len(rows), "synthetic": synthetic, "rows_changed": changed, "rows_moved": moved, "left": left,
                      "effects": [{k: e[k] for k in ("feature", "value", "n", "mean", "effect")} for e in top]}}
    _plan_save(f"{quarter}.json", cal, channel); _plan_save("ideas.json", bank, channel)
    return {"quarter": quarter, "learned_from": learn, "posts": len(rows), "rows": len([r for r in new if r.get("idea")]), "rows_changed": changed, "rows_moved": moved,
            "left": left[:20],
            "effects": cal["rerank"]["effects"], "why": [{"date": r["date"], "why": r.get("why")} for r in new if r.get("idea")][:60], "check": PL.check(cal, bank, ch)}


@command("analytics.business", synthetic=("boolean", "simulated numbers (rehearsals only)", False), channel=CH_ARG)
def analytics_business(synthetic=False, channel=""):
    """The business dashboard (WP-31): revenue and views by platform and by country, revenue per thousand views,
    revenue by month, the films that earn most, and the catalogue's value (the last month's revenue carried two years
    forward with the channel's own decay). The Studio page /business shows it."""
    AN, d, st, posts = _an(channel)
    return AN.business(st, synthetic=synthetic)


@command("plan.cross", quarter=("string", "e.g. 2027-Q1"), same_week=("boolean", "flag two channels posting the same subject in one week", True))
def plan_cross(quarter, same_week=True):
    """Every channel's quarter side by side, week by week (WP-32): posts per channel, and (when same_week) the weeks in
    which two channels post on the same subject (the planner's topic guard across channels)."""
    import datetime as _dt
    from . import planner as PL
    weeks, chans, rows_by = {}, [], {}
    for cid in PL.channel_ids():
        cal = _json(PL.chan_dir(cid) / f"{quarter}.json")
        if not cal:
            continue
        chans.append(cid); ideas = {i["id"]: i for i in _plan_bank(cid)["ideas"]}
        for r in cal["rows"]:
            if not r.get("idea"):
                continue
            d = _dt.date.fromisoformat(r["date"]); wk = (d - _dt.timedelta(days=d.weekday())).isoformat()
            weeks.setdefault(wk, {}).setdefault(cid, []).append({"date": r["date"], "title": r["title"], "field": r.get("field")})
            rows_by.setdefault(wk, []).append((cid, ideas.get(r["idea"], {"title": r["title"]})))
    clashes = []
    if same_week:
        for wk, xs in sorted(rows_by.items()):
            for i, (ca, a) in enumerate(xs):
                for cb, b in xs[i + 1:]:
                    if ca != cb and PL.same_topic(a, b):
                        clashes.append({"week_of": wk, "a": [ca, a["title"]], "b": [cb, b["title"]]})
    return {"quarter": quarter, "channels": chans, "weeks": [{"week_of": k, **v} for k, v in sorted(weeks.items())], "clashes": clashes, "ok": not clashes}


# ---------------- storyboard strip and animatic (plan 3.2) ----------------
def _board_frames(name):
    """one representative moment per shot: a moment into its first line (the picture as it speaks), else its middle"""
    d = _film(name); res = _shots(name); tm = _json(d / "timing.json", {}); sc = _json(d / "script.json", {})
    dirs = {l["id"]: l.get("direction") for l in sc.get("lines", []) if l.get("direction")}
    rows = []
    for sh in res["shots"]:
        ls = [l for l in tm.get("lines", []) if sh["start"] - 0.01 <= l["start"] < sh["end"]]
        t = (ls[0]["start"] + min(1.0, (ls[0]["end"] - ls[0]["start"]) / 2)) if ls else (sh["start"] + sh["end"]) / 2
        rows.append({"shot": sh["id"], "t": round(min(t, sh["end"] - 0.05), 3), "start": sh["start"], "end": sh["end"], "set": sh.get("set", "plain"),
                     "cast": [c.get("speaker") or Path(c["puppet"]).stem.split(".")[0] for c in sh.get("cast") or []],
                     "lines": [f"{l.get('speaker', '')}: {l['text']}" for l in ls],
                     "notes": [x for x in [sh.get("direction"), sh.get("notes")] + [dirs.get(l["id"]) for l in ls] if x]})
    return rows


@command("film.storyboard", name=("string", "film"), width=("integer", "still width in px", 360))
def film_storyboard(name, width=360):
    """Storyboard (plan 3.2): one still per shot from the player (a moment into its first line, else its middle),
    with notes (shot, times, set, cast, its lines, directions). Writes build/storyboard/strip.png (all shots in a grid)
    and build/storyboard/contact.pdf (six shots a page, notes beside each), plus the stills."""
    from PIL import Image, ImageDraw, ImageFont
    d = _film(name); out = d / "build" / "storyboard"; shutil.rmtree(out, ignore_errors=True); out.mkdir(parents=True)
    rows = _board_frames(name); page = _player_page(name)
    _run(["node", "tools/board_stills.mjs", str(page), str(out), str(width), *[str(r["t"]) for r in rows]], timeout=900)
    font = lambda n, bold=False: ImageFont.truetype(str(ROOT / "engine" / "fonts" / "Fredoka.ttf"), n)
    def wrap(txt, f, w, draw):
        lines, cur = [], ""
        for word in str(txt).split():
            if draw.textlength((cur + " " + word).strip(), font=f) > w and cur:
                lines.append(cur); cur = word
            else:
                cur = (cur + " " + word).strip()
        return lines + ([cur] if cur else [])
    stills = []
    for i, r in enumerate(rows):
        im = Image.open(out / f"still_{i}.png").convert("RGB"); h = round(width * im.height / im.width)
        im = im.resize((width, h), Image.LANCZOS); im.save(out / f"{r['shot']}.png"); (out / f"still_{i}.png").unlink(); stills.append(im)
    # strip: a grid with a caption block under each still
    cols = min(len(rows), 6); cap = 150; pad = 16; h = stills[0].height
    strip = Image.new("RGB", (pad + cols * (width + pad), pad + -(-len(rows) // cols) * (h + cap + pad)), "#f4f1ea"); dr = ImageDraw.Draw(strip)
    for i, (r, im) in enumerate(zip(rows, stills)):
        x, y = pad + (i % cols) * (width + pad), pad + (i // cols) * (h + cap + pad)
        strip.paste(im, (x, y)); dr.rectangle([x, y, x + width - 1, y + h - 1], outline="#24160e", width=2)
        dr.text((x, y + h + 8), f"{r['shot']}  {r['start']:.1f}-{r['end']:.1f} s  ·  {r['set']}", font=font(17), fill="#24160e")
        ty = y + h + 34
        for ln in (wrap(" / ".join(r["lines"]) or "(no lines)", font(14), width, dr))[:5]:
            dr.text((x, ty), ln, font=font(14), fill="#5a4a3a"); ty += 18
    strip.save(out / "strip.png", optimize=True)
    # contact PDF: A4 portrait at 100 dpi, six shots per page, notes beside each still
    W, H = 827, 1169; per = 3; pages = []
    title = _shots(name, resolve=False).get("title", name)
    for p0 in range(0, len(rows), per):
        pg = Image.new("RGB", (W, H), "white"); dr = ImageDraw.Draw(pg)
        dr.text((40, 30), f"{title} · storyboard · page {p0 // per + 1}", font=font(22), fill="#24160e")
        for j, (r, im) in enumerate(zip(rows[p0:p0 + per], stills[p0:p0 + per])):
            y = 80 + j * 360; th = 340; tw = round(th * im.width / im.height); pg.paste(im.resize((tw, th), Image.LANCZOS), (40, y))
            dr.rectangle([40, y, 40 + tw - 1, y + th - 1], outline="#24160e", width=2); x = 40 + tw + 24; ty = y
            dr.text((x, ty), f"{r['shot']}   {r['start']:.2f} - {r['end']:.2f} s   ({r['end'] - r['start']:.1f} s)", font=font(18), fill="#24160e"); ty += 28
            dr.text((x, ty), f"set: {r['set']}   cast: {', '.join(r['cast']) or '-'}", font=font(14), fill="#5a4a3a"); ty += 26
            for ln in [*r["lines"], *[f"direction: {n}" for n in r["notes"]]]:
                for wl in wrap(ln, font(14), W - x - 40, dr):
                    if ty < y + th - 18:
                        dr.text((x, ty), wl, font=font(14), fill="#24160e" if not ln.startswith("direction") else "#7a5cc4"); ty += 19
                ty += 6
        pages.append(pg)
    pages[0].save(out / "contact.pdf", save_all=True, append_images=pages[1:], resolution=100)
    return {"strip": str((out / "strip.png").relative_to(ROOT)), "pdf": str((out / "contact.pdf").relative_to(ROOT)), "shots": len(rows), "pages": len(pages),
            "stills": [str((out / f"{r['shot']}.png").relative_to(ROOT)) for r in rows]}


@command("film.animatic", name=("string", "film"))
def film_animatic(name):
    """Animatic (plan 3.2): the storyboard stills held for their shots' lengths over the film's sound (the mix if
    rendered, else the voice), as build/animatic.mp4. Seconds to make; use it to judge pacing before a render."""
    d = _film(name); sb = d / "build" / "storyboard"; rows = _board_frames(name)
    if not all((sb / f"{r['shot']}.png").exists() for r in rows):
        film_storyboard(name)
    lst = d / "build" / "animatic.txt"
    lst.write_text("".join(f"file '{(sb / (r['shot'] + '.png')).resolve()}'\nduration {r['end'] - r['start']:.3f}\n" for r in rows) + f"file '{(sb / (rows[-1]['shot'] + '.png')).resolve()}'\n")
    audio = next((p for p in (d / "build" / "mix.wav", d / "build" / "voice.wav") if p.exists()), None)
    out = d / "build" / "animatic.mp4"; total = rows[-1]["end"]
    _run(["ffmpeg", "-v", "error", "-y", "-f", "concat", "-safe", "0", "-i", str(lst), *(["-i", str(audio)] if audio else []),
          "-vf", "scale=trunc(iw/2)*2:trunc(ih/2)*2,fps=30,format=yuv420p", "-c:v", "libx264", "-crf", "20", *(["-c:a", "aac", "-b:a", "160k"] if audio else []),
          "-t", f"{total:.3f}", "-movflags", "+faststart", str(out)])
    return {"animatic": str(out.relative_to(ROOT)), "length_s": round(total, 2), "sound": audio.name if audio else None}


# ---------------- format templates (plan 2.15) ----------------
@command("storyboard.check", name=("string", "film"))
def storyboard_check(name):
    """The cold-open and reading-time rules on a storyboard, before or after voicing (with slots the timing is known
    before any voice): a character in frame one and the first words by 1.5 s; every sign, title or bubble up for
    words / 3 + 1 s; captions at most 3.2 words/s. Also lists facts still waiting for a source (the research gate)."""
    from . import layout_qa as LQ
    d = _film(name); res = _shots(name); tm = _json(d / "timing.json", {})
    co = LQ.cold_open(res["shots"], tm, res.get("size", [1080, 1920])); rd = LQ.reading_time(res["shots"], tm, captions=res.get("captions", True))
    facts = _json(d / "facts.json", {"facts": []}).get("facts", [])
    style, cfg = LQ.config_for(res)   # the film's style thresholds (WP-04)
    checks = {k: v for k, v in LQ.judge({"cold_open": co, "reading": rd}, cfg)["checks"].items() if k in ("cold_open", "reading_time")}
    return {"ok": all(checks.values()), "checks": checks, "style": style, "cold_open": co, "reading": rd,
            "facts_need_sources": [f["id"] for f in facts if not f.get("source")]}


@command("film.from_template", name=("string", "new film"), format=("string", "myth_vs_data | explainer | dialogue | wonder_story | we_reran_it | anniversary | series"),
         brief=("object", "the brief: the fields the format needs (see dbe/formats.py), optional cast {role: id}, lines {beat: text}, facts, data"))
def film_from_template(name, format, brief):
    """Format templates (plan 2.15): build a storyboard from a format and a brief: script with narration slots
    (135 wpm, draft timing so it can be checked and cut before voicing), shots (one per scene, line-relative), kit
    signs held long enough to read, prediction prompts with a silent count before reveals, facts (gated until
    sourced), data for charts, edit.json for a series; then run storyboard.check."""
    from . import formats as FM
    if not re.match(r"^[a-z0-9][a-z0-9_-]*$", name):
        raise ValueError("film name: lowercase letters, digits, - and _")
    d = FILMS / name
    if d.exists() and (d / "script.json").exists():
        raise FileExistsError(f"films/{name} exists")
    lines, shots, facts, edit = FM.storyboard(format, brief)
    d.mkdir(parents=True, exist_ok=True)
    voices = {"ravi": "kokoro:am_michael", "momo": "kokoro:af_heart", "priya": "kokoro:af_bella", **(brief.get("voices") or {})}
    spk = {l["speaker"] for l in lines}
    script = {"title": brief.get("title", name), "format": format,
              "speakers": {k: ({"voice": voices.get(k, "kokoro:af_sarah"), **({"fx": {"pitch": 1.2, "formant": 1.08, "range": 1.25}} if k == "momo" else {})}) for k in sorted(spk)},
              "lead_in_s": 0.6, "gap_s": 0.45, "lines": lines}
    (d / "script.json").write_text(json.dumps(script, indent=1, ensure_ascii=False))
    (d / "shots.json").write_text(json.dumps({"title": brief.get("title", name), "size": [1080, 1920], "fps": 30, "captions": True,
                                              **({"brand": brief["brand"]} if brief.get("brand") else {}), "shots": shots}, indent=1, ensure_ascii=False))
    (d / "facts.json").write_text(json.dumps({"facts": facts}, indent=1, ensure_ascii=False))
    (d / "score.json").write_text(json.dumps({"length_s": 30, "bpm": 96, "offset_s": 0, "sections": [{"kind": "main", "from_beat": 0, "to_beat": 64, "chords": ["F", "Am", "Dm", "C"], "end_chord": "F"}]}, indent=1))
    if brief.get("data"):
        (d / "data.json").write_text(json.dumps(brief["data"], indent=1, ensure_ascii=False))
    if edit:
        (d / "edit.json").write_text(json.dumps(edit, indent=1))
    if brief.get("draft"):
        script["draft"] = brief["draft"]; (d / "script.json").write_text(json.dumps(script, indent=1, ensure_ascii=False))
    about = (f"Format: {format} ({FM.TEMPLATES.get(format, {}).get('about', 'series of parts')}).\n\n"
             + "\n".join(f"- {k}: {v}" for k, v in brief.items() if isinstance(v, (str, int, float))) + "\n")
    if (d / "brief.md").exists():   # a planner brief stays; the storyboard's fields are added under it
        with open(d / "brief.md", "a") as fh:
            fh.write(f"\n## Storyboard (film.from_template)\n{about}")
    else:
        (d / "brief.md").write_text(f"# {brief.get('title', name)}\n\n{about}")
    sl = script_slots(name)
    chk = storyboard_check(name)
    return {"film": f"films/{name}", "lines": len(lines), "shots": [s_["id"] for s_ in shots], "length_s": sl["length_s"], "storyboard": chk,
            "next": ["voice.build", "acting.plan", "acting.direct (optional)", "film.render"] + (["research: source the facts"] if chk["facts_need_sources"] else [])}


@command("film.heal", name=("string", "film"), rounds=("integer", "most render-and-repair rounds", 3),
         revoice=("boolean", "allow re-voicing slower when captions flow too fast", False))
def film_heal(name, rounds=3, revoice=False):
    """Self-healing (plans 2.9, 2.18): render, read every failure (QA bar, layout checks including advisory ones,
    visual lint errors), apply the known repair for each to shots.json (frozen stretches, text outside the safe area
    or too small, short reading time, bare frames, heads cut by the frame, bubbles over faces; slower voice with
    revoice), re-render what changed and repeat until the film passes or nothing more can be repaired. Keeps the
    original as build/shots.before_heal.json and returns the log of every failure and edit."""
    from . import heal as HL
    d = _film(name); raw0 = _json(d / "shots.json")
    (d / "build").mkdir(exist_ok=True)
    if not (d / "build" / "shots.before_heal.json").exists():
        (d / "build" / "shots.before_heal.json").write_text(json.dumps(raw0, indent=1, ensure_ascii=False))
    log, tried = [], {}
    for rnd in range(1, rounds + 2):
        film_render(name); dirty = False
        rep = _json(d / "build" / "qa.json", {}); lint = _json(d / "build" / "lint.json", {})
        fails = HL.failures(rep, lint)
        if not fails or rnd > rounds:
            break
        res = _shots(name); size = res.get("size", [1080, 1920])
        reps = HL.diagnose(rep, lint, res, size, _json(d / "script.json", {}) if revoice else None)
        # a repair that did not help is undone and not tried again (frame fill: scaling the cast up must cut the bare
        # share by at least 3 points, else the shot needs new content, not a bigger character)
        ff = ((rep.get("layout") or {}).get("frame_fill") or {}).get("per_shot_mean") or {}
        for (sid, kind), (before, saved) in list(tried.items()):
            if kind == "grow" and saved is not None and ff.get(sid, 0) > before - 0.03:   # (None: already undone)
                cur = _json(d / "shots.json")
                for sh_ in cur["shots"]:
                    if sh_["id"] == sid:
                        sh_["cast"] = saved
                (d / "shots.json").write_text(json.dumps(cur, indent=1, ensure_ascii=False))
                log.append({"round": rnd, "undone": f"cast scale-up in {sid}: bare ground {before:.0%} -> {ff.get(sid, 0):.0%}, not enough to keep"})
                dirty = True
                tried[(sid, kind)] = (before, None)
        reps = [r for r in reps if not (r["edit"][0] == "grow" and ((r["shot"], "grow") in tried or rnd >= rounds))]   # needs a round left to measure it
        for r in reps:
            if r["edit"][0] == "grow":
                sh_ = next(x for x in _json(d / "shots.json")["shots"] if x["id"] == r["shot"])
                tried[(r["shot"], "grow")] = (ff.get(r["shot"], 1), json.loads(json.dumps(sh_.get("cast"))))
        if not reps:
            break
        new, slow = HL.apply(_json(d / "shots.json"), reps, res, size)
        log.append({"round": rnd, "failing": fails, "repairs": [{k: r[k] for k in ("check", "shot", "what")} for r in reps]})
        (d / "shots.json").write_text(json.dumps(new, indent=1, ensure_ascii=False))
        if slow:
            # anchor hard shot times to their lines first, so the picture follows the slower voice
            old = {l["id"]: l for l in _json(d / "timing.json", {}).get("lines", [])}; cur = _json(d / "shots.json"); resd = {x["id"]: x for x in res["shots"]}
            for sh in cur["shots"]:
                for key, lk, edge in (("start", "start_line", "start"), ("end", "end_line", "end")):
                    ln = old.get(sh.get(lk))
                    if ln and isinstance(sh.get(key), (int, float)) and not (key == "start" and sh[key] == 0):
                        off = round(resd[sh["id"]][key] - ln[edge], 3)
                        sh[key] = f"{ln['id']}.{edge}{'+' if off >= 0 else '-'}{abs(off)}"
            (d / "shots.json").write_text(json.dumps(cur, indent=1, ensure_ascii=False))
            log[-1]["repairs"].append({"check": "reading_time", "shot": "*", "what": "hard shot times anchored to their lines before re-voicing"})
            sc = _json(d / "script.json"); sc["length_scale"] = round(sc.get("length_scale", 1.0) * slow, 3)
            (d / "script.json").write_text(json.dumps(sc, indent=1, ensure_ascii=False))
            voice_build(name)
            if any(c.get("speaker") for sh in new["shots"] for c in sh.get("cast", [])):
                acting_plan(name)
    if dirty:   # an undo came after the last render
        film_render(name); rep = _json(d / "build" / "qa.json", {}); lint = _json(d / "build" / "lint.json", {})
    still = HL.failures(rep, lint)
    return {"passes": not still, "rounds": log, "still_failing": {f: HL.HINTS.get(f, "no automatic repair yet") for f in still}}


@command("lipsync.check", name=("string", "film"))
def lipsync_check(name):
    """Lip-sync cross-check (plan 2.2): each speaker's viseme track against their own voice (first-formant energy of
    build/voice.wav inside their lines): best lag in frames and correlation; with DBE_RHUBARB set, also agreement with
    Rhubarb Lip Sync's reading of the same audio and text. Fails beyond +-2 frames or below 0.2 correlation."""
    _film(name)
    return json.loads(subprocess.run(
        [PY, "dbe/lipsync_qa.py", f"films/{name}"], cwd=ROOT, capture_output=True, text=True, check=True).stdout)


@command("film.lint", name=("string", "film"), step=("integer", "sample every Nth frame", 3))
def film_lint(name, step=3):
    """Visual lint (plan 2.8): play the film in the player and flag picture problems with frame ranges. Heads cut by
    the frame (error), speech bubbles over faces (error), hands leaving the frame or feet cropped in a wide shot,
    faces under the caption band, arms locked straight by an unreachable IK target, props through someone else's
    head (warn), and silhouettes tangent to the frame edge or to each other (info). Writes build/lint.json."""
    d = _film(name)
    if not (d / "shots.json").exists():
        return {"error": "film.lint needs a shots.json film"}
    page = _player_page(name)
    r = subprocess.run(["node", "tools/lint.mjs", str(page), str(int(step))], cwd=ROOT, capture_output=True, text=True, timeout=1800)
    if r.returncode != 0 or not r.stdout.strip():
        return {"error": (r.stderr or r.stdout)[-800:]}
    issues = json.loads(r.stdout.strip().splitlines()[-1])
    summary = {lv: sum(1 for i in issues if i.get("level") == lv) for lv in ("error", "warn", "info")}
    (d / "build" / "lint.json").write_text(json.dumps({"summary": summary, "issues": issues}, indent=1))
    return {"summary": summary, "issues": issues}


# ---------------- reach ----------------
def _web_page(name, ui, extra=""):
    """the player page made self-contained (scripts and the font inlined) with a UI script, plus audio.ogg"""
    import base64
    d = _film(name); html = _player_page(name).read_text()
    out_dir = d / "build" / ("web" if ui == "web_ui.js" else "interactive"); out_dir.mkdir(parents=True, exist_ok=True)
    html = html.replace('<script src="../../../dbe/player/player.js"></script>',
                        f'<script src="../../../dbe/player/player.js"></script>{extra}<script src="../../../dbe/player/{ui}"></script>')
    for src in re.findall(r'<script src="\.\./\.\./\.\./([^"]+)"></script>', html):
        code = (ROOT / src).read_text().replace("</script", "<\\/script")
        html = html.replace(f'<script src="../../../{src}"></script>', f"<script>/* {src} */\n{code}\n</script>")
    font = base64.b64encode((ROOT / "engine" / "fonts" / "Fredoka.ttf").read_bytes()).decode()
    html = html.replace("url('../../../engine/fonts/Fredoka.ttf')", f"url(data:font/ttf;base64,{font})")
    # the other fonts (handwriting, mono, the world's scripts) are copied beside the page, so the folder can be
    # hosted anywhere (the page's relative links point into the repository and do not resolve from build/<kind>/)
    (out_dir / "fonts").mkdir(exist_ok=True)
    for ref in sorted(set(re.findall(r"url\('\.\./\.\./\.\./(engine/fonts/[^']+)'\)", html))):
        f = (ROOT / ref).resolve()
        if f.exists():
            shutil.copy(f, out_dir / "fonts" / f.name); html = html.replace(f"url('../../../{ref}')", f"url('fonts/{f.name}')")
    mix = d / "build" / "mix.wav"
    if mix.exists():
        _run(["ffmpeg", "-v", "error", "-y", "-i", str(mix), "-c:a", "libopus", "-b:a", "96k", str(out_dir / "audio.ogg")])
    html = html.replace("</body>", f'<audio id="aud" src="{"audio.ogg" if mix.exists() else ""}" preload="auto"></audio></body>')
    (out_dir / "index.html").write_text(html)
    return out_dir, html, mix.exists()


@command("export.web", name=("string", "film"))
def export_web(name):
    """Export a self-contained interactive web player (play, scrub, frame step) that renders the film live in the
    browser: build/web/index.html with scripts and font inlined, plus audio.ogg (Opus). Host the folder anywhere."""
    out_dir, html, aud = _web_page(name, "web_ui.js")
    return {"path": str((out_dir / "index.html").relative_to(ROOT)), "bytes": len(html), "audio": aud,
            "note": "fonts and scripts are inlined; Fredoka is under the SIL OFL (engine/fonts/OFL.txt)"}


def _interactive_data(name):
    """chapters, the timed transcript with each line's source, question pauses and sources, from the film's data"""
    d = _film(name); s = _shots(name); tm = _json(d / "timing.json", {}); sc = _json(d / "script.json", {}); fd = _json(d / "facts.json", {"facts": []})
    srcs = fd.get("sources") or {}
    def src_of(f):
        x = f.get("source") or srcs.get(f.get("src")) or {}
        return {"url": x.get("url"), "title": x.get("title")} if isinstance(x, dict) and x.get("url") else None
    facts = {f.get("id"): src_of(f) for f in fd.get("facts", [])}
    names = {k: (v or {}).get("name") or k.capitalize() for k, v in (sc.get("speakers") or {}).items()}
    cite = {l["id"]: ([l["fact"]] if isinstance(l.get("fact"), str) else (l.get("fact") or [])) for l in sc.get("lines", [])}
    lines = []
    for l in tm.get("lines", []):
        src = next((facts[f] for f in cite.get(l["id"], []) if facts.get(f)), None)
        lines.append({"id": l["id"], "name": names.get(l.get("speaker"), (l.get("speaker") or "Narrator").capitalize()), "speaker": l.get("speaker"),
                      "start": l["start"], "end": l["end"], "words": [{"text": w["text"], "start": w["start"]} for w in l.get("words") or []] or [{"text": l["text"], "start": l["start"]}],
                      **({"source": src} if src else {})})
    pauses = [{"t": round(a["end"] + 0.15, 3), "question": " ".join(w["text"] for w in a["words"]), "line": a["id"]}
              for a, b in zip(lines, lines[1:]) if a["words"][-1]["text"].rstrip().endswith("?") and b["speaker"] != a["speaker"]]
    chapters = []
    for i, sh in enumerate(s["shots"]):
        first = next((l for l in lines if sh["start"] <= l["start"] < sh["end"]), None)
        chapters.append({"start": sh["start"], "end": sh["end"], "title": (" ".join(w["text"] for w in first["words"])[:48] if first else f"Shot {i + 1}")})
    seen, sources = set(), []
    for f in facts.values():
        if f and f["url"] not in seen:
            seen.add(f["url"]); sources.append(f)
    # WP-30 branching: shots.json "branches": [{"after": shot, "prompt", "choices": [{"label", "shots": [ids]}], "then": shot}];
    # the film is rendered whole (every branch, in order); the page plays one path through it
    sid = {sh["id"]: sh for sh in s["shots"]}; branches = []
    for bi, br in enumerate(s.get("branches") or []):
        for k in ("after", "then"):
            if br.get(k) not in sid:
                raise ValueError(f"branch {bi + 1}: no shot {br.get(k)!r} for {k!r}")
        chs = []
        for c in br.get("choices", []):
            ids = c.get("shots") or []
            if not ids or any(i not in sid for i in ids):
                raise ValueError(f"branch {bi + 1}: choice {c.get('label')!r} names unknown shots {ids}")
            chs.append({"label": c.get("label") or ids[0], "start": sid[ids[0]]["start"], "end": sid[ids[-1]]["end"]})
        if len(chs) < 2:
            raise ValueError(f"branch {bi + 1}: a branch needs at least two choices")
        branches.append({"at": sid[br["after"]]["end"], "prompt": br.get("prompt") or "What next?", "choices": chs, "then": sid[br["then"]]["start"]})
    return {"title": s.get("title") or name, "chapters": chapters, "lines": lines, "pauses": pauses, "sources": sources, "branches": branches}


@command("export.interactive", name=("string", "film"))
def export_interactive(name):
    """An interactive web film from the film's data alone (WP-30): the player draws it live, beside chapters (one per
    shot), the transcript synced word by word (tap a line to hear it), a pause after every question so the viewer
    can guess before the answer, and the source of each line that states a fact. build/interactive/index.html with
    everything inlined, plus audio.ogg; then it is opened in Chromium and driven (a tap on a line, a question's
    pause, the sources) to check it works."""
    D = _interactive_data(name)
    out_dir, html, aud = _web_page(name, "interactive.js", f"<script>window.INTERACTIVE={json.dumps(D, ensure_ascii=False).replace('</', '<\\/')};</script>")
    r = subprocess.run(["node", "tools/interactive_check.mjs", "file://" + str(out_dir / "index.html")], cwd=ROOT, capture_output=True, text=True, timeout=300)
    chk = json.loads(r.stdout.strip().splitlines()[-1]) if r.returncode == 0 and r.stdout.strip() else {"error": r.stderr[-400:]}
    return {"path": str((out_dir / "index.html").relative_to(ROOT)), "bytes": len(html), "audio": aud, "chapters": len(D["chapters"]), "lines": len(D["lines"]),
            "questions": len(D["pauses"]), "sources": len(D["sources"]), "branches": len(D["branches"]), "check": chk}


def ensure_voice(vid):
    """a Piper voice's model in the voices folder, fetched from its registry URL if missing and checked (sha256 when
    recorded, else the catalogue's md5) (WP-25)"""
    import hashlib, urllib.request
    if str(vid).startswith("kokoro:"):
        return "kokoro"
    r = _voice_registry().get(vid) or {}; f = Path(VOICES) / f"{vid}.onnx"
    if f.exists():
        return "present"
    if not r.get("url") and vid in _voice_registry():   # a registered Piper voice without its own URL: the piper-voices catalogue's
        cat = Path(VOICES) / "piper-voices.json"            # path and md5 (rhasspy/piper-voices voices.json)
        base = "https://huggingface.co/rhasspy/piper-voices/resolve/main/"
        if not cat.exists():
            cat.parent.mkdir(parents=True, exist_ok=True); urllib.request.urlretrieve(base + "voices.json", cat)
        ent = json.loads(cat.read_text()).get(vid)
        if ent:
            onnx = next((k for k in ent["files"] if k.endswith(f"{vid}.onnx")), None)
            if onnx:
                r = {**r, "url": base + onnx, "md5": ent["files"][onnx].get("md5_digest")}
    if not r.get("url"):
        raise FileNotFoundError(f"voice {vid} is not in {VOICES} and has no download URL in voices/registry.json or the piper-voices catalogue")
    f.parent.mkdir(parents=True, exist_ok=True)
    for suffix in ("", ".json"):
        urllib.request.urlretrieve(r["url"] + suffix, str(f) + suffix)
    b = f.read_bytes()
    if (r.get("sha256") and hashlib.sha256(b).hexdigest() != r["sha256"]) or (not r.get("sha256") and r.get("md5") and hashlib.md5(b).hexdigest() != r["md5"]):
        f.unlink(); raise RuntimeError(f"voice {vid}: checksum mismatch, removed")
    return "fetched"


WORLD_LANGS = ["en", "zh", "hi", "es", "fr", "ar", "bn", "pt", "ru", "ur", "id", "de", "ja", "sw", "mr", "te", "tr", "ta", "vi", "ko", "fa", "it", "th",
               "gu", "pl", "uk", "kn", "ml", "pa", "my", "si", "he", "nl", "el", "ms", "fil", "ha", "yo", "am", "ne"]   # by speakers, broadly; plus Sinhala


@command("locales.list", langs=("array", "language tags (default: forty widely spoken languages)", None))
def locales_list(langs=None):
    """What each language has here (WP-25): its writing system and direction (CLDR), whether its font is bundled for
    the picture and installed for captions, whether OCR can read it back, and the best voice that speaks it with
    its licence status (clean voices ship; others are flagged at posting). A language with no voice can still ship
    with translated text and captions."""
    from . import i18n as I
    reg = _voice_registry(); tess = set(subprocess.run(["tesseract", "--list-langs"], capture_output=True, text=True).stdout.split()) if shutil.which("tesseract") else set()
    fams = set(subprocess.run(["fc-list", ":", "family"], capture_output=True, text=True).stdout.replace(",", "\n").split("\n"))
    scripts = {x["script"]: x for x in _json(ROOT / "engine" / "fonts" / "scripts.json")["scripts"]}; rows = []
    for t in langs or WORLD_LANGS:
        try:
            L = I.language(t)
        except Exception as e:
            rows.append({"lang": t, "error": str(e)[:80]}); continue
        sc = scripts.get(L["script"]); v = (I.voices_for(t, reg) or [None])[0]
        rows.append({"lang": t, "name": L["name"], "native": L["native"], "dir": L["dir"], "script": L["script"],
                     "font": "Fredoka" if not sc else (sc["family"] + ("" if sc.get("files") else " (installed)")),
                     "caption_font": L["caption_font"] in fams or L["caption_font"] == "Fredoka", "ocr": all(x in tess for x in L["ocr"].split("+")),
                     "voice": v["voice"] if v else None, "voice_status": v["status"] if v else None})
    ready = [r["lang"] for r in rows if r.get("voice_status") == "clean" and r.get("caption_font")]
    return {"languages": rows, "voiced_and_clean": ready, "text_only": [r["lang"] for r in rows if not r.get("voice")]}


@command("film.strings", name=("string", "film"), lang=("string", "a language tag: also write films/<name>/i18n/<lang>.json, a translator's template (kept if it exists)", ""))
def film_strings(name, lang=""):
    """Every string a viewer reads or hears in a film, by key (WP-25): spoken lines, every overlay's text fields, the
    set's words (the classroom board), extra bubbles, chart labels drawn from data.json, the title, brief and posting
    titles. With a language, a template films/<name>/i18n/<lang>.json holds the source texts and an empty
    translation for each, ready for a translator (keep every {{...}} binding)."""
    from . import i18n as I
    d = _film(name); rows = I.extract(_shots(name, resolve=False), _json(d / "script.json"), _json(d / "titles.json", {}), _json(d / "data.json", {}))
    out = {"film": name, "strings": rows, "count": len(rows)}
    if lang:
        f = d / "i18n" / f"{lang}.json"
        if not f.exists():
            f.parent.mkdir(exist_ok=True)
            f.write_text(json.dumps({"lang": lang, "source": {r["key"]: r["text"] for r in rows}, "strings": {r["key"]: "" for r in rows}, "voices": {}, "swaps": {}}, indent=1, ensure_ascii=False))
        out["template"] = str(f.relative_to(ROOT))
    return out


@command("film.translate", name=("string", "film"), lang=("string", "language tag (es, si, ta, ar, hi, fr, ...)"),
         refresh=("boolean", "draft again the machine strings nobody has reviewed or edited", False))
def film_translate(name, lang, refresh=False):
    """Machine-translation drafts (WP-25): every string of the film without a translation in i18n/<lang>.json is
    drafted by NLLB-200 (Meta's distilled 600M, converted to CTranslate2 here, CC BY-NC 4.0), its {{...}} bindings
    kept. Strings a person wrote are never touched. The file records the drafts; film.localize lists those nobody has
    reviewed and records the model in the version's provenance, so the posting gate flags it."""
    from . import i18n as I, translate as TR
    d = _film(name); rows = I.extract(_shots(name, resolve=False), _json(d / "script.json"), _json(d / "titles.json", {}), _json(d / "data.json", {}))
    return {"film": name, "lang": lang, **TR.draft(d / "i18n" / f"{lang}.json", {r["key"]: r["text"] for r in rows}, lang, refresh)}


@command("film.localize", name=("string", "film"), lang=("string", "language tag, e.g. ar, si, es, ja, pt-BR"),
         voice=("string", "one voice for every speaker (default: films/<name>/i18n/<lang>.json \"voices\", else the best voice for the language)", ""),
         lines=("object", "line id -> translated text (older form; strings takes every key)", None), strings=("object", "key -> translation, as film.strings lists them", None),
         renderer=("string", "optional: render every shot with this renderer (e.g. svg for a fast draft)", ""), render=("boolean", "voice and render it (else only write the version's files)", True))
def film_localize(name, lang, voice="", lines=None, strings=None, renderer="", render=True):
    """A language version of a film (WP-25): every string translated (films/<name>/i18n/<lang>.json, merged with
    `strings` and `lines`; a translation must keep every {{...}} data binding; month and weekday names in charts come
    from the locale), speakers re-voiced (a voice that is not clean is allowed here and flagged at posting), numbers in
    the locale's format, right-to-left layout for right-to-left languages, the locale's gesture rules applied (the
    i18n file can turn a rule off with "rules_off") and its review flags listed, the i18n file's "swaps" applied
    (props by id, sets by name, clips), then voiced, re-timed (shots follow the new words) and rendered, and the
    on-screen text read back by OCR (film.text_check). The version is films/<name>-<lang>."""
    from . import i18n as I
    src = _film(name); dst = FILMS / f"{name}-{lang}"; lang_info = I.language(lang)
    spec = _json(src / "i18n" / f"{lang}.json", {}) if (src / "i18n" / f"{lang}.json").exists() else {}
    tr = {k: v for k, v in (spec.get("strings") or {}).items() if v}
    from . import translate as _TR   # WP-25: machine drafts nobody has reviewed are listed, and the model recorded
    machine_unreviewed = _TR.unreviewed(spec) if spec.get("machine") else []
    tr.update({f"line:{k}": v for k, v in (lines or {}).items()}); tr.update(strings or {})
    sh0, sc0 = _shots(name, resolve=False), _json(src / "script.json")
    shots, script, titles, data, missing, bad, auto = I.apply(sh0, sc0, _json(src / "titles.json", {}), _json(src / "data.json", {}), tr, lang)
    if bad:
        raise ValueError(f"translations change data bindings: {bad}")
    if missing:
        raise ValueError(f"{len(missing)} string(s) not translated: {missing[:12]} (film.strings lists them; write them to i18n/{lang}.json)")
    if data:   # other data values that are month or weekday names (a "best month") follow the locale too
        mo = I._months(lang)
        def walk(o):
            if isinstance(o, dict):
                return {k: (walk(v) if not k.startswith("_") else v) for k, v in o.items()}
            if isinstance(o, list):
                return [walk(v) for v in o]
            return mo.get(o, o) if isinstance(o, str) else o
        data = walk(data)
    # voices
    reg = _voice_registry(); by_spk = spec.get("voices") or {}
    best = (I.voices_for(lang, reg) or [{}])[0].get("voice")
    if not (voice or by_spk or best):
        raise ValueError(f"no voice speaks {lang_info['name']} here (voices.list; bash tools/setup.sh voices)")
    for spk, cfg in (script.get("speakers") or {}).items():
        cfg["voice"] = by_spk.get(spk) or voice or best
    if not script.get("speakers"):
        script["voice"] = voice or best
    used = {c["voice"] for c in (script.get("speakers") or {}).values()} or {script.get("voice")}
    flags = [{"voice": v, "status": reg.get(v, {}).get("status", "unknown"), "license": reg.get(v, {}).get("license")} for v in used if reg.get(v, {}).get("status") != "clean"]
    if flags:
        script["allow_restricted_voices"] = True   # allowed in-house; the posting gate flags it for the owner
    for v in used:
        ensure_voice(v)
    # digits: Latin unless the i18n file asks for the language's own ("digits": "native"), the same on screen and in words
    locale = spec.get("locale") or (lang if spec.get("digits") == "native" else f"{lang}-u-nu-latn")
    script["lang"] = lang; script["locale"] = locale
    shots.update({"lang": lang, "dir": lang_info["dir"], "locale": locale})
    # the describer writes English and translates it into the version's language (WP-24/25: film.describe)
    # swaps and the locale's rules
    sw = spec.get("swaps") or {}; swapped = []
    for sh in shots["shots"]:
        if sh.get("set") in (sw.get("sets") or {}):
            swapped.append({"shot": sh["id"], "set": [sh["set"], sw["sets"][sh["set"]]]}); sh["set"] = sw["sets"][sh["set"]]
        for pr in sh.get("props") or []:
            if pr.get("id") in (sw.get("props") or {}):
                pr.update(sw["props"][pr["id"]]); swapped.append({"shot": sh["id"], "prop": pr["id"]})
        for c in sh.get("cast", []):
            for cl in (c.get("timeline") or {}).get("clips", []):
                if cl.get("clip") in (sw.get("clips") or {}):
                    swapped.append({"shot": sh["id"], "clip": [cl["clip"], sw["clips"][cl["clip"]]]}); cl["clip"] = sw["clips"][cl["clip"]]
    shots, rule_changes = I.apply_rules(shots, lang, off=spec.get("rules_off") or ())
    review = I.review_flags(shots, script, lang)
    if renderer:
        for sh in shots["shots"]:
            sh["renderer"] = renderer
    if dst.exists():
        shutil.rmtree(dst)
    shutil.copytree(src, dst, ignore=shutil.ignore_patterns("build", "timing.json", "i18n"))
    (dst / "build").mkdir(exist_ok=True)
    for f, obj in (("script.json", script), ("shots.json", shots), ("titles.json", titles), ("data.json", data)):
        if obj or (src / f).exists():
            (dst / f).write_text(json.dumps(obj, indent=1, ensure_ascii=False))
    if spec.get("machine") and set(spec["machine"].get("keys") or []) & set(tr):   # machine strings shaped this version: record the model
        pv = _json(dst / "provenance.json", {}) or {}
        pv["models"] = [m for m in pv.get("models", []) if m.get("name") != spec["machine"]["model"]] + [
            {"name": spec["machine"]["model"], "license": spec["machine"]["license"], "output": f"machine-drafted strings ({len(spec['machine']['keys'])}; not yet reviewed: {len(machine_unreviewed)})"}]
        (dst / "provenance.json").write_text(json.dumps(pv, indent=1))
    if machine_unreviewed:
        review = list(review) + [{"rule": "machine_translation", "why": f"{len(machine_unreviewed)} string(s) are machine drafts nobody has reviewed: list them in i18n/{lang}.json \"reviewed\" once checked", "keys": machine_unreviewed[:20]}]
    out = {"film": dst.name, "language": lang_info, "voices": sorted(used), "voice_flags": flags, "auto_translated": auto, "swaps": swapped,
           "rules_applied": rule_changes, "review_flags": review}
    if not render:
        return out
    v = voice_build(dst.name)
    retime(dst.name)   # shot times are written against line ids, so they follow the new words
    r = film_render(dst.name)
    tc = film_text_check(dst.name)
    try:   # WP-25: the version's own covers, lettered in its writing system (right to left where it reads so)
        cv = cover_make(dst.name); covers = {"made": cv["covers"]}
    except (ValueError, FileNotFoundError) as e:
        covers = {"not_made": str(e)[:200]}
    return {**out, "duration": v.get("duration"), "qa": r.get("qa"), "final": r.get("final"), "text_check": {k: tc[k] for k in ("ok", "checked", "passed", "worst")}, "covers": covers}


def _norm_text(t):
    import unicodedata
    t = unicodedata.normalize("NFC", t or "").lower()
    t = re.sub("[\u064b-\u065f\u0670\u0640]", "", t)   # Arabic short vowels and tatweel: OCR drops them
    t = t.translate(str.maketrans("\u0623\u0625\u0622\u0671\u0649\u0629", "\u0627\u0627\u0627\u0627\u064a\u0647"))   # Arabic letter variants OCR confuses (hamza seats, alif maqsura, ta marbuta)
    return re.sub(r"[\s\W_]+", "", t)


def _partial(expected, got):
    """how well the expected text appears somewhere in what was read: the best window's similarity"""
    import difflib
    e, g = expected, got
    if not e:
        return 1.0
    if len(g) <= len(e):
        return difflib.SequenceMatcher(None, e, g).ratio()
    best = 0.0
    for i in range(0, len(g) - len(e) + 1):
        r = difflib.SequenceMatcher(None, e, g[i:i + len(e)]).ratio()
        if r > best:
            best = r
            if r == 1.0:
                break
    return best


def _word_score(expected, got, reverse=False):
    """the share of the expected words found among the words read (each at least 75% alike), in any order: OCR may put
    a number on either side of right-to-left words; reverse=True looks for each word written backwards"""
    import difflib
    ew = [w for w in (_norm_text(x) for x in (expected or "").split()) if w]; gw = [w for w in (_norm_text(x) for x in (got or "").split()) if w]
    if any(len(w) >= 3 for w in ew):   # one- and two-letter words ("في", "a") are too small for OCR to be evidence either way
        ew = [w for w in ew if len(w) >= 3]
    if not ew:
        return 1.0
    hit = 0.0
    for w in ew:
        w = w[::-1] if reverse and len(w) > 1 else w
        best = max((difflib.SequenceMatcher(None, w, g).ratio() for g in gw), default=0.0)
        hit += 1.0 if best >= 0.75 else 0.0
    return hit / len(ew)


@command("film.text_check", name=("string", "film"), min_score=("number", "least similarity of what OCR reads to what should be there (0-1)", 0.7))
def film_text_check(name, min_score=0.7):
    """On-screen text read back from the rendered film (WP-25): for every string drawn on screen (overlays, the set's
    words, bubbles when the film shows them), a frame where it is fully shown is read by Tesseract in that string's
    writing system, and its words must be found there (at least min_score of them, each read at least 75% alike, in any
    order, after removing punctuation and Arabic short vowels). Words drawn backwards (a right-to-left string reversed
    letter by letter, unshaped) read closer to their reverse and are reported as reversed; missing glyphs (boxes) read
    as nothing."""
    from . import i18n as I
    from .captions import script_of
    d = _film(name); s = _shots(name); final = d / "build" / "final.mp4"; tm = _json(d / "timing.json", {})
    if not final.exists():
        raise FileNotFoundError(f"{name} has no build/final.mp4")
    items = []
    for sh in s["shots"]:
        t0, t1 = sh["start"], sh["end"]
        for kind in ("overlays", "underlays"):
            for o in sh.get(kind) or []:
                if o.get("type") in ("console", "draw", "face", "water", "roots", "section", "paper") and not o.get("text"):
                    continue
                st = o.get("start"); st = t0 if st is None or (isinstance(st, (int, float)) and st < 0) else max(t0, st)
                en = o.get("end", t1) if not isinstance(o.get("end"), str) else t1; en = min(t1, en if en is not None else t1)
                at = min(en - 0.1, st + 0.9)
                for f in ("text", "title", "body", "label"):
                    v = o.get(f); v = " ".join(v) if isinstance(v, list) else v
                    if isinstance(v, str) and v.strip() and o.get("type") != "bars" or (f == "title" and o.get("type") == "bars" and v):
                        items.append({"shot": sh["id"], "what": f"{o.get('type')} {f}", "text": v, "t": round(at, 3),
                                      **({"band": [o["y"] - 1.6 * o["size"], o["y"] + 0.9 * o["size"]]} if o.get("type") == "title" and isinstance(o.get("y"), (int, float)) and o.get("size") else {})})
        for b in (sh.get("set_opts") or {}).get("board") or []:
            items.append({"shot": sh["id"], "what": "board", "text": b, "t": round((t0 + t1) / 2, 3)})
        if sh.get("bubbles"):
            bub = {ln["id"]: ln.get("bubble") for ln in _json(d / "script.json", {}).get("lines", [])}
            for l in tm.get("lines", []):
                if t0 <= l["end"] - 0.05 <= t1:
                    items.append({"shot": sh["id"], "what": f"bubble {l['id']}", "text": (bub.get(l["id"]) or l["text"]).replace("\n", " "), "t": round(l["end"] - 0.08, 3),
                                  "alt": [round(x, 3) for x in (l["end"] - 0.3, (l["start"] + l["end"]) / 2) if x > l["start"] + 0.2]})
    if s.get("captions", True):   # burned-in captions: the first chunk of each line, while its second word is spoken
        for l in tm.get("lines", []):
            ws = l.get("words") or []
            if len(ws) >= 2:
                items.append({"shot": None, "what": f"caption {l['id']}", "text": " ".join(w["text"] for w in ws[:3]), "t": round(ws[1]["start"] + 0.05, 3), "band": "captions",
                              "alt": [round(w["start"] + 0.05, 3) for w in ws[2:3]] + [round(ws[1]["start"] + 0.25, 3)]})
    import numpy as np
    from PIL import Image, ImageFilter
    tmp = d / "build" / "text_check"; shutil.rmtree(tmp, ignore_errors=True); tmp.mkdir(parents=True)
    rows = []
    def read_at(k, it, at, lang):
        """the best reading of one item in the frame at `at`: (forward score, reversed score, text)"""
        col = tmp / f"t{k:03d}c.png"
        _run(["ffmpeg", "-v", "error", "-y", "-ss", f"{at:.3f}", "-i", str(final), "-frames:v", "1", "-vf", "scale=iw*2:-1:flags=lanczos", str(col)])
        im = np.asarray(Image.open(col).convert("RGB")).astype(float)
        if it.get("band") == "captions":   # captions sit in a band above the bottom: read that band alone
            Hh = im.shape[0]; im = im[int(Hh * 0.62):int(Hh * 0.93)]
        elif isinstance(it.get("band"), list):   # a title: the band around its own line (frame px; the frame is read at twice the size)
            y0, y1 = max(0, int(it["band"][0] * 2)), int(it["band"][1] * 2); im = im[y0:y1] if y1 - y0 > 40 else im
        mx, mn = im.max(2), im.min(2)
        views = {"gray": Image.fromarray(im.mean(2).astype(np.uint8)), "neg": Image.fromarray((255 - im.mean(2)).astype(np.uint8)),
                 "colour": Image.fromarray(np.where(((mx - mn) / (mx + 1e-6) > 0.45) & (mx > 110), 0, 255).astype(np.uint8)).filter(ImageFilter.MedianFilter(3)),   # coloured lettering alone
                 "bright": Image.fromarray(np.where((im[..., 0] > 200) & (im[..., 1] > 170), 0, 255).astype(np.uint8)).filter(ImageFilter.MedianFilter(3))}   # white or yellow fills of outlined letters
        for vk, vim in views.items():
            vim.save(tmp / f"t{k:03d}{vk}.png")
        best = (-1.0, 0.0, "")
        for vk, psm, lg in (("gray", "11", lang), ("gray", "6", lang), ("neg", "11", lang), ("colour", "11", lang), ("colour", "11", lang.replace("+eng", "")),
                            ("bright", "6", lang.replace("+eng", "")), ("bright", "11", lang)):
            r = subprocess.run(["tesseract", str(tmp / f"t{k:03d}{vk}.png"), "stdout", "-l", lg, "--psm", psm], capture_output=True, text=True)
            f_ = _word_score(it["text"], r.stdout)
            if f_ > best[0]:
                best = (f_, _word_score(it["text"], r.stdout, reverse=True), r.stdout)
        return best

    for k, it in enumerate(items):
        sc = script_of(it["text"]); lang = (sc["ocr"] if sc else "eng") + ("+eng" if sc else "")
        # a frame or two later in the same showing too: a voice's timing moves a little between renders, and one
        # frame can catch a bubble or caption on its way in or out
        best, read_t = (-1.0, 0.0, ""), it["t"]
        for at in [it["t"]] + list(it.get("alt") or []):
            got = read_at(k, it, at, lang)
            if got[0] > best[0]:
                best, read_t = got, at
            if best[0] >= min_score and best[0] >= best[1]:
                break
        it = {x: v for x, v in it.items() if x != "alt"} | ({"read_at": read_t} if read_t != it["t"] else {})
        fwd, rev = best[0], best[1]
        rows.append({**it, "ocr_lang": lang, "score": round(fwd, 3), "reversed_score": round(rev, 3), "ok": fwd >= min_score and fwd >= rev,
                     **({"problem": "reads reversed"} if rev > fwd and rev >= min_score else {})})
    shutil.rmtree(tmp, ignore_errors=True)
    ok = all(r["ok"] for r in rows)
    rep = {"film": name, "checked": len(rows), "passed": sum(r["ok"] for r in rows), "worst": min((r["score"] for r in rows), default=None), "ok": ok, "items": rows}
    (d / "build" / "text_check.json").write_text(json.dumps(rep, indent=1, ensure_ascii=False))
    return rep


@command("film.retime", name=("string", "film"))
def retime(name):
    """Re-derive shot start/end from line references (start_line/end_line in shots.json) after a voice change."""
    s = _shots(name, resolve=False); t = _json(FILMS / name / "timing.json", {})
    L = {l["id"]: l for l in t.get("lines", [])}
    for sh in s["shots"]:
        if "start_line" in sh and sh["start_line"] in L:
            sh["start"] = round(L[sh["start_line"]]["start"] - sh.get("lead", 0.2), 3) if sh is not s["shots"][0] else 0
    for a, b in zip(s["shots"], s["shots"][1:]):
        a["end"] = b["start"]
    last = s["shots"][-1]
    if "end_line" in last and last["end_line"] in L:
        last["end"] = round(L[last["end_line"]]["end"] + last.get("tail", 1.5), 3)
    (FILMS / name / "shots.json").write_text(json.dumps(s, indent=1))
    return {"shots": [(sh["id"], sh["start"], sh["end"]) for sh in s["shots"]]}


@command("variants.hooks", name=("string", "film"))
def variants_hooks(name):
    """Render each hook variant (shots.json "hooks": {id: shot}) as an alternative opening, joined to the rest of the film."""
    d = _film(name); s = _shots(name, resolve=False)
    outs = []
    for hid, hook in (s.get("hooks") or {}).items():
        first = dict(s["shots"][0]); first.update(hook); first["id"] = f"hook_{hid}"
        s2 = dict(s); s2["shots"] = [first] + s["shots"][1:]
        (d / "shots.json").write_text(json.dumps(s2, indent=1))
        try:
            shot_render(name, first["id"])
        finally:
            (d / "shots.json").write_text(json.dumps(s, indent=1))
        lst = d / "build" / "shots" / f"hook_{hid}.txt"
        lst.write_text(f"file '{(d / 'build' / 'shots' / (first['id'] + '.mp4')).resolve()}'\n" + "".join(f"file '{(d / 'build' / 'shots' / (sh['id'] + '.mp4')).resolve()}'\n" for sh in s["shots"][1:]))
        out = d / "build" / f"variant_{hid}.mp4"
        _run(["ffmpeg", "-v", "error", "-y", "-f", "concat", "-safe", "0", "-i", str(lst), "-i", str(d / "build" / "mix.wav"), "-map", "0:v", "-map", "1:a", "-c:v", "libx264", "-crf", "18", "-pix_fmt", "yuv420p", "-c:a", "aac", "-shortest", str(out)])
        outs.append(str(out.relative_to(ROOT)))
    return {"variants": outs}


# ---------------- tests ----------------

def _doodle_click_test(snap, meas):
    """WP-18 click-to-mask: with each limb of the cat left out of the spec, one tap on its stroke (two thirds of the
    way out) must cut it again (IoU with the automatic cut >= 0.7, pivot within 22 px of where it was drawn), and the
    puppet cut from it must record SAM 2.1 in its provenance"""
    import math
    import numpy as np
    from PIL import Image, ImageDraw
    from . import autorig as AR
    bad, got = [], {}
    _, truth = AR.synthetic_doodle("cat")
    info = AR.prepare(ROOT / "out" / "doodletest" / "cat_photo.png", ROOT / "out" / "doodletest" / "cat_click_probe.png")
    k, (ox, oy) = info["scale"], info["crop"][:2]
    spec = snap["spec"]; W, H = snap["size"]
    ink = AR._ink().extract(str(ROOT / snap["photo"])) > 0.35; iy, ix = np.nonzero(ink)
    def mask(poly):
        m = Image.new("L", (W, H), 0); ImageDraw.Draw(m).polygon([tuple(q) for q in poly], fill=255); return np.asarray(m) > 0
    last = None
    for part in ("arm_L", "arm_R", "tail"):
        auto = spec["parts"][part]; am = mask(auto["poly"]); pv = auto["pivot"]
        sel = am[iy, ix]; px, py = ix[sel], iy[sel]; d = np.hypot(px - pv[0], py - pv[1]); j = int(np.argmin(abs(d - 0.66 * d.max())))
        sp = {**spec, "parts": {q: v for q, v in spec["parts"].items() if q != part}}
        r = doodle_click(snap["id"], part, [[int(px[j]), int(py[j])]], sp); bm = mask(r["poly"])
        t = [(truth[part][0] - ox) * k, (truth[part][1] - oy) * k]
        got[part] = {"iou_with_auto_cut": round(float((am & bm).sum() / (am | bm).sum()), 3), "pivot_error_px": round(math.dist(r["pivot"], t) / k, 1),
                     "model_iou": r["iou"], "seconds": r["seconds"]}
        if got[part]["iou_with_auto_cut"] < 0.7 or got[part]["pivot_error_px"] > 22:
            bad.append(f"click {part}: {got[part]}")
        last = r
    c = doodle_cut(snap["id"], last["spec"]); pz = _json(ROOT / c["puppet"])
    got["provenance"] = [a["name"] for a in (pz.get("meta") or {}).get("assists", [])]
    if "tail" not in pz["parts"] or "sam21_tiny" not in got["provenance"]:
        bad.append(f"click cut: parts {sorted(pz['parts'])}, provenance {got['provenance']}")
    doodle_cut(snap["id"], {q: v for q, v in spec.items()})   # back to the automatic cuts
    meas["click"] = got
    return bad


def _doodle_page_test(work, meas):
    """WP-18: a page with two doodles becomes two puppets, and one gains pupils and a three-quarter view through
    drawing requests alone (drawings made on the ghost guides, as a person would)"""
    import math, shutil
    import numpy as np
    from PIL import Image, ImageDraw
    from scipy import ndimage
    from . import autorig as AR, drawreq as RQ
    bad = []
    im, _ = AR.synthetic_page(); im.save(work / "page.png")
    for d in DOODLES.glob("page-*"):
        shutil.rmtree(d)
    pg = doodle_page(str((work / "page.png").relative_to(ROOT)), ["Nib", "Miso"])
    for d in pg["doodles"]:   # a clean queue for each
        shutil.rmtree(DOODLES / d["id"]); shutil.rmtree(ROOT / "out" / "requests" / d["id"], ignore_errors=True)
    pg = doodle_page(str((work / "page.png").relative_to(ROOT)), ["Nib", "Miso"])
    parts = [sorted(_json(ROOT / d["puppet"])["parts"]) for d in pg["doodles"]]
    meas["page"] = {"doodles": pg["count"], "parts": parts}
    if pg["count"] != 2 or not {"head", "arm_L", "arm_R"} <= set(parts[0]) or not {"head", "arm_L", "arm_R", "tail"} <= set(parts[1]):
        return [f"page: {meas['page']}"]
    rel = pg["doodles"][1]["puppet"]; pz = _json(ROOT / rel); W, H = map(int, pz["artboard"])
    q = drawing_requests(rel)
    rq = {r.get("swap") or r.get("view"): r for r in q["requests"] if r["status"] == "open"}
    if "pupils" not in rq or "three_quarter" not in rq or not all((ROOT / rq[k].get("ghost", "")).is_file() for k in ("pupils", "three_quarter")):
        return [f"page: pupils and three-quarter requests with ghosts, got {sorted(rq)}"]
    ink = (20, 20, 20, 255)
    eyes = RQ._alpha_art(pz, pz["swaps"]["eyes"]["shapes"]["open"][0]) > 0.35
    lab, _ = ndimage.label(ndimage.binary_fill_holes(eyes))
    dr = Image.new("RGBA", (W, H), (0, 0, 0, 0)); g = ImageDraw.Draw(dr)
    for sl in ndimage.find_objects(lab):   # a dot in each eye
        cy, cx = (sl[0].start + sl[0].stop) / 2, (sl[1].start + sl[1].stop) / 2; r = (sl[1].stop - sl[1].start) * 0.18
        g.ellipse([cx - r, cy - r, cx + r, cy + r], fill=ink)
    dr.save(work / "pupils.png")
    hb = RQ._part_box(pz, "head"); cx = (hb[0] + hb[2]) / 2; rx = ry = (hb[2] - hb[0]) / 2 * 0.86; hy = hb[3] - ry - 6; ox = rx * 0.15
    dr = Image.new("RGBA", (W, H), (0, 0, 0, 0)); g = ImageDraw.Draw(dr)   # the head turned right: wider on the far side, ears moved over
    g.line([(cx + ox + rx * math.cos(a) * (1.06 if math.cos(a) > 0 else 0.9), hy + ry * math.sin(a)) for a in (2 * math.pi * i / 90 for i in range(91))], fill=ink, width=5, joint="curve")
    for ex, sc in ((cx + ox - rx * 0.35, 0.8), (cx + ox + rx * 0.62, 1.0)):
        top = hy - ry * 0.92; g.line([(ex - 18 * sc, top + 8), (ex - 4 * sc, top - 40 * sc), (ex + 18 * sc, top + 4)], fill=ink, width=5, joint="curve")
    dr.save(work / "turn.png")
    got = {}
    for k, f in (("pupils", "pupils.png"), ("three_quarter", "turn.png")):
        r = drawing_fulfil(rel, rq[k]["id"], str((work / f).relative_to(ROOT))); got[k] = {"verified": r["verified"], "now_free": r["now_free"]}
    meas["page"]["fulfil"] = got
    if not got["pupils"]["verified"] or "glance / look at" not in got["pupils"]["now_free"] or not got["three_quarter"]["verified"] or "turn (three-quarter)" not in got["three_quarter"]["now_free"]:
        bad.append(f"page fulfil: {got}")
    # the rig moves: pupils follow the look, the turned view redraws the head and slides the face
    pz = _json(ROOT / rel); hip = pz["parts"]["hip"]["pivot"]; poses = [{}, {"look": [-1, 0]}, {"look": [1, 0]}, {"view": "three_quarter"}]
    spec = {"size": [W * len(poses), H], "bg": "#ffffff", "items": [{"puppet": rel, "x": hip[0] + i * W, "y": pz["ground"], "s": 1, "pose": {"blink": 0, **ps}} for i, ps in enumerate(poses)]}
    (work / "page_poses.json").write_text(json.dumps(spec)); _run(["node", "tools/pose_still.mjs", str(work / "page_poses.json"), str(work / "page_poses.png")], timeout=300)
    a = np.asarray(Image.open(work / "page_poses.png").convert("L")).astype(int) < 128
    tiles = [a[:, i * W:(i + 1) * W] for i in range(len(poses))]
    xs = lambda t: float(np.nonzero(t[int(hb[1]):int(hb[3]), int(hb[0]):int(hb[2])])[1].mean())
    eye_rows = slice(int(min(np.nonzero(eyes)[0])), int(max(np.nonzero(eyes)[0])) + 1)
    L_, R_ = tiles[1][eye_rows], tiles[2][eye_rows]   # where the ink differs between looking left and right: the pupils
    meas["page"]["moves"] = {"pupils_dx": round(float(np.nonzero(R_ & ~L_)[1].mean() - np.nonzero(L_ & ~R_)[1].mean()), 1), "movable": pz["swaps"]["pupils"]["movable"],
                             "turn_head_dx": round(xs(tiles[3]) - xs(tiles[0]), 1), "turn_changed_px": int((tiles[3] != tiles[0]).sum())}
    if meas["page"]["moves"]["pupils_dx"] < pz["swaps"]["pupils"]["movable"] or meas["page"]["moves"]["turn_head_dx"] < 4 or (tiles[3][int(hb[3]) + 40:] != tiles[0][int(hb[3]) + 40:]).sum() > 50:
        bad.append(f"page poses: {meas['page']['moves']}")   # (below the head nothing changes with the view)
    # chains over ghosts (WP-18): the tail traced over its ghost becomes a chain of parts that bends without gaps
    q = drawing_requests(rel)
    ch = next((r for r in q["requests"] if r.get("kind") == "chain" and r["status"] == "open"), None)
    if not ch or not (ROOT / ch.get("ghost", "")).is_file():
        bad.append(f"chain request with a ghost: {[(r.get('need'), r['status']) for r in q['requests']]}")
    else:
        pz = _json(ROOT / rel); x0_, y0_ = pz["parts"]["tail"]["pivot"]; bx = ch["box"]
        reach = 0.8 * (bx[2] - x0_)   # a wavy tail drawn over the ghost, from where the old one meets the body out to the right
        pts = [(x0_ + reach * t_, y0_ - 0.25 * reach * t_ + 22 * math.sin(2 * math.pi * 1.2 * t_)) for t_ in np.linspace(0, 1, 60)]
        dr = Image.new("RGBA", (W, H), (0, 0, 0, 0)); ImageDraw.Draw(dr).line(pts, fill=ink, width=5, joint="curve"); dr.save(work / "chain.png")
        drawn = np.asarray(dr)[..., 3] > 128
        r = drawing_fulfil(rel, ch["id"], str((work / "chain.png").relative_to(ROOT)))
        pz = _json(ROOT / rel); chain = (pz.get("chains") or {}).get("tail") or {}
        poses = [{}, {"angles": {k: 28 for k in chain.get("parts", [])[1:]}}, {"angles": {k: -28 for k in chain.get("parts", [])[1:]}}]
        spec = {"size": [W * len(poses), H], "bg": "#ffffff", "flush": True, "items": [{"puppet": rel, "x": hip[0] + i * W, "y": pz["ground"], "s": 1, "pose": {"blink": 0, **ps}} for i, ps in enumerate(poses)]}
        (work / "chain_poses.json").write_text(json.dumps(spec)); _run(["node", "tools/pose_still.mjs", str(work / "chain_poses.json"), str(work / "chain_poses.png")], timeout=300)
        a = np.asarray(Image.open(work / "chain_poses.png").convert("L")).astype(int) < 128
        ct = [a[:, i * W:(i + 1) * W] for i in range(len(poses))]
        only = {**pz, "swaps": {}, "parts": {k: {**v, "strokes": v["strokes"] if k in chain.get("parts", []) else []} for k, v in pz["parts"].items()}}   # the tail alone
        (work / "chain_only.puppet.json").write_text(json.dumps(only)); spec["items"] = [{**it, "puppet": str((work / "chain_only.puppet.json").relative_to(ROOT))} for it in spec["items"]]
        (work / "chain_only.json").write_text(json.dumps(spec)); _run(["node", "tools/pose_still.mjs", str(work / "chain_only.json"), str(work / "chain_only.png")], timeout=300)
        a2 = np.asarray(Image.open(work / "chain_only.png").convert("L")).astype(int) < 128
        comps = [int(ndimage.label(a2[:, i * W:(i + 1) * W], np.ones((3, 3)))[1]) for i in range(len(poses))]
        iou = float((ct[0] & drawn).sum() / max(1, drawn.sum()))   # the chain at rest draws what was drawn
        pivs = [pz["parts"][k]["pivot"] for k in chain.get("parts", [])]
        meas["page"]["chain"] = {"verified": r["verified"], "now_free": r["now_free"], "parts": chain.get("parts"), "pivots": pivs, "tip": chain.get("tip"),
                                 "rest_covers_drawn": round(iou, 3), "tail_pieces_rest_bent_up_bent_down": comps,
                                 "bent_changed_px": [int((ct[i] != ct[0]).sum()) for i in (1, 2)]}
        c = meas["page"]["chain"]
        if not c["verified"] or "tail / chain" not in c["now_free"] or len(c["parts"] or []) != RQ.CHAIN_N or c["rest_covers_drawn"] < 0.95 \
                or comps != [1, 1, 1] or min(c["bent_changed_px"]) < 300 or len({tuple(map(round, q_)) for q_ in pivs}) != RQ.CHAIN_N:
            bad.append(f"chain: {c}")
    # the phone page: the same photo gives two doodles to pick from, and the picked one's requests to draw
    import socket, subprocess, time
    for d in DOODLES.glob("page-*"):
        shutil.rmtree(d)
    port = 8798
    srv = subprocess.Popen([sys.executable, "-m", "dbe", "serve", str(port)], cwd=ROOT, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    try:
        for _ in range(50):
            with socket.socket() as s_:
                if s_.connect_ex(("127.0.0.1", port)) == 0:
                    break
            time.sleep(0.2)
        r = subprocess.run(["node", "tools/doodle_page_check.mjs", str(port), str(work / "page.png")], cwd=ROOT, capture_output=True, text=True, timeout=900)
        out = json.loads(r.stdout.strip().splitlines()[-1]) if r.stdout.strip() else {"error": r.stderr[-400:]}
    finally:
        srv.terminate(); srv.wait(timeout=20)
    meas["page"]["phone_page"] = out
    tap = out.get("tapped") or {}
    if out.get("errors") or out.get("error") or len(out.get("chips", [])) != 2 or "tail" not in out.get("parts", []) or not out.get("pupils") or not out.get("turn") \
            or "arm_L" in out.get("without_arm", ["arm_L"]) or "arm_L" not in tap.get("parts", []) or tap.get("iou", 0) < 0.5:
        bad.append(f"phone page: {out}")
    ed = out.get("edited") or {}   # polygon editing: one vertex fewer, one more, the dragged one where it was let go
    saved = (_json(DOODLES / ed["id"] / "spec.json")["parts"].get("tail") or {}).get("poly") if ed.get("id") and (DOODLES / ed["id"] / "spec.json").exists() else None
    meas["page"]["poly_edit"] = {k: ed.get(k) for k in ("n0", "n1", "n2", "moved_to", "wanted", "strokes_changed")} | {"saved_matches": saved == ed.get("poly")}
    if not ed or ed["n1"] != ed["n0"] - 1 or ed["n2"] != ed["n0"] or max(abs(a - b) for a, b in zip(ed["moved_to"], ed["wanted"])) > 2 \
            or saved != ed.get("poly") or not ed.get("strokes_changed"):
        bad.append(f"polygon edit: {meas['page']['poly_edit']}")
    return bad


def _guarded(fn):
    """a test that cannot run here because an optional library, module or program is missing is reported as skipped,
    and any other exception as that test's failure, so one test never stops the rest of the suite"""
    import functools
    import traceback

    @functools.wraps(fn)
    def run(*a, **k):
        try:
            return fn(*a, **k)
        except ModuleNotFoundError as e:
            return [], {"skipped": f"needs the Python module {e.name} (python -m dbe engine.doctor)"}
        except OSError as e:
            msg = str(e)
            if "cannot open shared object file" in msg or (isinstance(e, FileNotFoundError) and e.filename and "/" not in str(e.filename)):
                return [], {"skipped": f"needs {e.filename or msg.split(':')[0]} ({msg[:200]}; python -m dbe engine.doctor)"}
            return [f"crashed: {type(e).__name__}: {msg[:300]}"], {"traceback": traceback.format_exc()[-1500:]}
        except Exception as e:   # noqa: BLE001  (reported as this test's failure)
            return [f"crashed: {type(e).__name__}: {str(e)[:300]}"], {"traceback": traceback.format_exc()[-1500:]}
    return run


@command("test", update=("boolean", "rewrite the golden frames instead of comparing", False),
         film=("string", "only cases for this film", ""))
def test_golden(update=False, film=""):
    """Golden-frame regression test: render key frames of benchmark films (SVG player) and compare with tests/golden.
    Frames are pure functions of time, so any difference is a real change."""
    import tempfile
    import numpy as np
    from PIL import Image
    spec = _json(ROOT / "tests" / "golden.json")
    tol = spec.get("tolerance", {"mean_abs": 1.5, "pixels_over_32": 0.004})
    results, failed = [], 0
    tmp = Path(tempfile.mkdtemp(prefix="golden_"))
    for case in spec.get("poses", []):  # loader-level cases: puppets in given poses (bends, controls, views)
        if film and film != "poses":
            continue
        img = tmp / (Path(case).stem + ".png")
        _run(["node", "tools/pose_still.mjs", str(ROOT / case), str(img)], timeout=300)
        g = ROOT / "tests" / "golden" / "poses" / img.name; g.parent.mkdir(parents=True, exist_ok=True)
        im = Image.open(img).convert("RGB"); im = im.resize((450, round(450 * im.height / im.width)), Image.LANCZOS)
        if update or not g.exists():
            im.save(g, optimize=True); results.append({"frame": str(g.relative_to(ROOT)), "status": "written"}); continue
        a = np.asarray(im, np.float32); b = np.asarray(Image.open(g).convert("RGB"), np.float32)
        d = np.abs(a - b); mean, over = float(d.mean()), float((d.max(-1) > 32).mean()); ok = mean <= tol["mean_abs"] and over <= tol["pixels_over_32"]
        failed += 0 if ok else 1
        results.append({"frame": str(g.relative_to(ROOT)), "status": "ok" if ok else "FAIL", "mean_abs": round(mean, 3), "pixels_over_32": round(over, 5)})
    if not film or film == "review":   # review room (plan 3.4): notes read right, the critic measures right
        from . import review as RV
        notes = {"raise the arm earlier": "earlier", "Ravi's nod should be bigger": "bigger", "make the wave a bit slower": "slower",
                 "hold the shrug longer": "longer", "lose the point": "remove", "the jump starts too late": "earlier", "this feels off": None}
        bad = [(t, RV.interpret(t, ["ravi"])["verb"], v) for t, v in notes.items() if RV.interpret(t, ["ravi"])["verb"] != v]
        rise = lambda t0: [[i / 30, 100.0, 500.0 - (200.0 if i / 30 >= t0 else 0.0)] for i in range(90)]
        ok_early, _, _, _ = RV.verify({"verb": "earlier"}, 0.33, rise(1.5), rise(1.17))
        ok_wrong, _, _, _ = RV.verify({"verb": "earlier"}, 0.33, rise(1.5), rise(1.5))
        if not ok_early or ok_wrong:
            bad.append(("critic earlier", ok_early, ok_wrong))
        failed += 1 if bad else 0
        results.append({"review": "notes and critic", "status": "FAIL" if bad else "ok", **({"cases": bad} if bad else {})})
    if not film or film == "actout":   # Act it out (plan 3.5): synthetic takes come back as the clips that made them
        from . import actout as AO
        bad, meas = AO.self_test(_json(ROOT / "cast" / "generated" / "ravi.puppet.json"), _json(ROOT / "puppet" / "clips" / "humanoid.json")["clips"])
        failed += 1 if bad else 0
        results.append({"actout": "retarget round trips", "status": "FAIL" if bad else "ok", "measured": meas, **({"cases": bad} if bad else {})})
    if not film or film == "layout":   # layout QA per style and the AI-look lint (WP-04)
        from . import layout_qa as LQ
        bad, meas = LQ.self_test(ROOT / "out" / "layouttest")
        failed += 1 if bad else 0
