@command("sound.edit", name=("string", "film"), edits=("array", "cue edits: move, gain, replace, trim, delete, add (see dbe/sound.py)", None),
         music=("array", "music swaps [{start, end, kind}]", None), append=("boolean", "add to the film's edits instead of replacing them", True))
def sound_edit(name, edits=None, music=None, append=True):
    """Record a sound designer's edits in films/<name>/sound.json (WP-40): cue edits matched by type and nearest time,
    and music swaps over a span (cut on the beat grid). Times given in seconds are stored against the nearest line
    ("got.end-0.360"), so the edits follow the words through re-voicing. They apply every time the mix is made;
    sound.remix hears them."""
    from . import sound as SD
    d = _film(name)
    ed = _json(d / "sound.json", {}) or {}
    for m in music or []:
        if m.get("kind") not in SD.KINDS:
            raise ValueError(f"music kind must be one of {', '.join(SD.KINDS)}")
    tm = _json(d / "timing.json", {}) or {}
    rel = lambda o, keys: {k: (SD.line_relative(float(v), tm) if k in keys and isinstance(v, (int, float)) else v) for k, v in o.items()}
    ed["edits"] = (ed.get("edits", []) if append else []) + [rel(e, ("t", "to")) for e in edits or []]   # written against the lines
    ed["music"] = (ed.get("music", []) if append else []) + [rel(m, ("start", "end")) for m in music or []]
    (d / "sound.json").write_text(json.dumps(ed, indent=1) + "\n")
    return {"edits": len(ed["edits"]), "music": len(ed["music"])}


@command("sound.remix", name=("string", "film"))
def sound_remix(name):
    """Make the mix again with the sound edits (WP-40), without rendering a frame: cues derived again, sound.json
    applied, engine/audio.py, then the mix muxed with the existing picture into build/final.mp4. Measures each moved
    cue (its onset in the effects stem against the frame it was moved to) and each music swap (the music stem's level
    in the span before and after)."""
    import time
    from . import sound as SD
    d = _film(name); s = _shots(name); b = d / "build"
    fps = s.get("fps", 30)
    if not (b / "picture.mp4").exists():
        raise FileNotFoundError("render the film first (film.render)")
    before = {k: (b / "stems" / f"{k}.wav").read_bytes() if (b / "stems" / f"{k}.wav").exists() else None for k in ("music",)}
    t0 = time.time()
    total = _mix_inputs(name, s)
    _run([PY, "engine/audio.py", f"films/{name}"])
    pic = next(p for p in (b / "picture_cap.mp4", b / "picture_post.mp4", b / "picture.mp4") if p.exists() and (p.name != "picture_cap.mp4" or s.get("captions") is not False))
    M = _json(ROOT / "dbe" / "profiles.json")["master"]
    _run(["ffmpeg", "-v", "error", "-y", "-i", str(pic), "-i", str(b / "mix.wav"), "-map", "0:v", "-map", "1:a", "-c:v", "copy",
          "-c:a", M["acodec"], "-ar", str(M["ar"]), "-b:a", M["ab"], "-af", "apad", "-t", f"{total:.3f}",
          *(["-movflags", "+faststart"] if M.get("faststart") else []), str(b / "final.mp4")])
    secs = round(time.time() - t0, 1)
    ed = SD.resolve(_json(d / "sound.json", {}) or {}, _json(d / "timing.json", {}))
    rep = (_json(b / "sound_report.json", {}) or {}).get("edits", [])
    checks = []
    for e, r in zip(ed.get("edits", []), rep):
        if e.get("op") == "move" and r.get("ok"):
            on = SD.onset(b / "stems" / "sfx.wav", float(e["to"]))
            checks.append({"cue": e["type"], "from": e["t"], "to": e["to"], "onset": on, "frame_error": None if on is None else round(abs(on - float(e["to"])) * fps, 2),
                           "old_place_level_db": SD.energy(b / "stems" / "sfx.wav", float(e["t"]) - 0.02, float(e["t"]) + 0.12)})
    music = []
    for m in ed.get("music", []):
        music.append({"span": [m["start"], m["end"]], "kind": m["kind"], "music_level_db": SD.energy(b / "stems" / "music.wav", m["start"], m["end"]),
                      "transient_level_db": SD.energy(b / "stems" / "music.wav", m["start"], m["end"], band=(4000, 12000))})
    qa = qa_run(name)
    return {"seconds": secs, "final": str((b / "final.mp4").relative_to(ROOT)), "edits": rep, "moved": checks, "music": music, "qa": qa.get("checks")}


@command("sound.audacity", name=("string", "film"))
def sound_audacity(name):
    """Open the sound in Audacity for deeper edits (WP-40): build/audacity/project.lof imports the stems at their
    offsets, cues.txt and music.txt import as label tracks (File > Import > Labels)."""
    from . import sound as SD
    lanes = sound_lanes(name)
    b = FILMS / name / "build"
    files = SD.audacity(b / "audacity", [b / "stems" / f"{k}.wav" for k in lanes["stems"]], lanes["cues"], lanes["sections"])
    return {"files": [str(Path(f).relative_to(ROOT)) for f in files]}




def _boards_test():
    """WP-18 boards: Pip's mouth chart, expressions and turnaround render (with the onion ghost drawn in each close-up),
    its side view is on model, and a copy whose side view stands 40 units taller at the hips is listed as off model"""
    import numpy as np
    from PIL import Image
    bad, meas = [], {}
    work = ROOT / "out" / "boardtest"; work.mkdir(parents=True, exist_ok=True)
    for kind in ("mouth", "expressions", "turnaround"):
        r = puppet_board("puppet/examples/pip.puppet.json", kind, f"out/boardtest/pip.{kind}.png")
        im = np.asarray(Image.open(ROOT / r["board"]).convert("RGB")).astype(int); ghost = 0
        if kind == "mouth":   # the onion: the same chart with the closed mouth left empty differs where the ghost was drawn
            q = _json(ROOT / "puppet/examples/pip.puppet.json"); q["swaps"]["mouth"]["shapes"]["closed"] = []
            (work / "pip_noclosed.puppet.json").write_text(json.dumps(q))
            r2 = puppet_board("out/boardtest/pip_noclosed.puppet.json", "mouth", "out/boardtest/pip_noclosed.mouth.png")
            ghost = int((np.abs(im - np.asarray(Image.open(ROOT / r2["board"]).convert("RGB")).astype(int)).max(axis=2) > 24).sum())
        meas[kind] = {"size": list(im.shape[1::-1]), **({"ghost_px": ghost} if kind == "mouth" else {}), **({"off_model": r["off_model"]} if kind == "turnaround" else {}),
                      **({"shapes": len(r["shapes"])} if kind == "mouth" else {})}
        if kind == "mouth" and (len(r["shapes"]) < 8 or ghost < 200):
            bad.append(f"mouth chart: {meas[kind]}")
        if kind == "turnaround" and r["off_model"]:
            bad.append(f"turnaround: Pip's side view is listed off model: {r['off_model']}")
    p = _json(ROOT / "puppet/examples/pip.puppet.json")
    hip = p["parts"]["hip"]["pivot"]
    p.setdefault("views", {}).setdefault("side", {}).setdefault("parts", {})["hip"] = {**p["views"]["side"].get("parts", {}).get("hip", {}), "pivot": [hip[0], hip[1] - 40]}
    (work / "pip_off.puppet.json").write_text(json.dumps(p))
    r = puppet_board("out/boardtest/pip_off.puppet.json", "turnaround", "out/boardtest/pip_off.turnaround.png")
    meas["seeded_off_model"] = r["off_model"]
    if not any(o["view"] == "side" and o["landmark"] == "hips" for o in r["off_model"]):
        bad.append(f"turnaround: a side view 40 units taller at the hips was not caught: {r['off_model']}")
    return bad, meas


def _stepped_test():
    """WP-15: nib-hello's set (a paper page with grain) is the same on every frame, so the player offers it as a plate;
    three frames drawn without it, laid over the plate, must match the frames drawn whole (within 2 levels)"""
    import numpy as np
    from PIL import Image
    bad, meas = [], {}
    out = ROOT / "out" / "steppedtest"; shutil.rmtree(out, ignore_errors=True)
    page = _player_page("nib-hello")
    r = subprocess.run(["node", "tools/plate_check.mjs", f"file://{page}?shot=s1", str(out), "0,40,120"], cwd=ROOT, capture_output=True, text=True, timeout=600)
    res = json.loads(r.stdout.strip().splitlines()[-1]) if r.stdout.strip() else {"error": r.stderr[-300:]}
    if not res.get("plate"):
        return [f"no plate offered for nib-hello: {res}"], meas
    pl = Image.open(out / "plate.png").convert("RGBA"); worst = 0
    for f in (0, 40, 120):
        whole = np.asarray(Image.open(out / f"normal_{f}.png").convert("RGB")).astype(int)
        c = pl.copy(); c.alpha_composite(Image.open(out / f"plate_{f}.png").convert("RGBA"))
        worst = max(worst, int(np.abs(whole - np.asarray(c.convert("RGB")).astype(int)).max()))
    meas["max_difference"] = worst
    if worst > 2:
        bad.append(f"plate frames differ from whole frames by up to {worst}")
    return bad, meas


def _transitions_test():
    """WP-15: three synthetic shots (red, green, blue; 2 s each) joined with a 0.5 s dissolve and an auto-length dip,
    over handles: the picture keeps 180 frames, the dissolve is half-way at the cut, colours are pure outside the
    transitions, and the seam check fails the hard cuts but passes the transitions"""
    import numpy as np
    from . import layout_qa as LQ
    bad, meas = [], {}
    d = ROOT / "out" / "transtest"; shutil.rmtree(d, ignore_errors=True); bd = d / "build" / "shots"; bd.mkdir(parents=True)
    fps = 30
    s = {"fps": fps, "shots": [{"id": "a", "start": 0, "end": 2}, {"id": "b", "start": 2, "end": 4, "transition": {"kind": "dissolve", "dur": 0.5}},
                               {"id": "c", "start": 4, "end": 6, "transition": {"kind": "dip", "dur": "auto"}}]}
    col = {"a": "0xd03030", "b": "0x30b040", "c": "0x3050d0"}
    def clip(path, colour, n):
        _run(["ffmpeg", "-v", "error", "-y", "-f", "lavfi", "-i", f"color=c={colour}:s=192x108:r={fps}", "-frames:v", str(n), "-c:v", "libx264", "-crf", "1", "-pix_fmt", "yuv420p", str(path)])
    for x in s["shots"]:
        pre, post = _handles(s, x["id"], fps)
        clip(bd / f"{x['id']}.mp4", col[x["id"]], 60)
        if pre or post:
            clip(bd / f"{x['id']}.hd.mp4", col[x["id"]], 60 + pre + post)
    pic = d / "build" / "picture.mp4"
    made = _join_shots(d, s, fps, pic)
    raw = subprocess.run(["ffmpeg", "-v", "error", "-i", str(pic), "-f", "rawvideo", "-pix_fmt", "rgb24", "-"], capture_output=True, check=True).stdout
    fr = np.frombuffer(raw, np.uint8).reshape(-1, 108, 192, 3).astype(int)[:, 54, 96]
    meas["frames"] = len(fr); meas["transitions"] = made
    if len(fr) != 180:
        bad.append(f"{len(fr)} frames, not 180")
    a_, b_ = _tr_frames(s["shots"][1]["transition"], fps)
    mid = fr[60 - 1:60 + 1].mean(axis=0)   # half-way between red and green at the cut
    meas["at_cut"] = mid.round().tolist()
    if not (abs(mid[0] - (0xd0 + 0x30) / 2) < 25 and abs(mid[1] - (0x30 + 0xb0) / 2) < 25):
        bad.append(f"the dissolve is not half-way at the cut: {mid.round().tolist()}")
    for k, c_ in ((10, "a"), (60 + b_ + 5, "b"), (175, "c")):
        want = [int(col[c_][i:i + 2], 16) for i in (2, 4, 6)]
        if np.abs(fr[k] - want).max() > 12:
            bad.append(f"frame {k} is {fr[k].tolist()}, not {c_}'s colour {want}")
    tw = {round(x["at"], 3): (x["before"], x["after"]) for x in made}
    with_tr = LQ.seams(pic, [2, 4], fps, tw)["seams"]
    cut = d / "build" / "cut.mp4"; (bd / "list.txt").write_text("".join(f"file '{(bd / (x + '.mp4')).resolve()}'\n" for x in "abc"))
    _run(["ffmpeg", "-v", "error", "-y", "-f", "concat", "-safe", "0", "-i", str(bd / "list.txt"), "-c", "copy", str(cut)])
    hard = LQ.seams(cut, [2, 4], fps)["seams"]
    seam_max = LQ.DEFAULTS["seam_max"]
    meas["seams"] = {"hard_cuts": [x["change"] for x in hard], "transitions": [x["change"] for x in with_tr], "limit": seam_max}
    if any(x["change"] <= seam_max for x in hard) or any(x["change"] > seam_max for x in with_tr):
        bad.append(f"seams: {meas['seams']}")
    return bad, meas


